BEGIN;
WITH p AS (SELECT value AS r FROM jsonb_array_elements($ap$[{"id": "6a1bc9ce-9c71-4212-afa6-89c6a0a42395", "term": "Sculpture Material Pad", "definition": "The Material Pad is a two-dimensional control in Apple's Logic Pro Sculpture that sets the physical character of the modeled string. One axis controls Stiffness and the other controls Inner Loss (damping of high frequencies), and moving the ball adjusts both at once. The corners give metallic, glass- or bell-like, nylon/catgut, and wood-like materials. The Material Pad is a proprietary Apple feature within Sculpture.", "plain_english": "The Material Pad is a square control in Sculpture, part of Logic Pro from Apple. It sets what the modeled string is made of. One direction changes stiffness; the other changes how fast high tones fade. You drag a ball around the square to blend materials. Corners sound like metal, glass, nylon, or wood.", "purpose_function": "It lets an engineer shape the core timbre of Sculpture's string by choosing its material behavior, which strongly affects the whole sound.", "practical_application": "A sound designer drags the Material Pad ball toward the steel or nylon corner to change a patch from a bright metallic tone to a softer, mellower one.", "category": "Synthesizer control", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Sculpture", "Sculpture Morph Pad", "Physical modeling", "Stiffness", "Inner loss", "Timbre"], "common_mistakes": ["Confusing the Material Pad with the Morph Pad, which blends whole snapshots", "Assuming the axes are volume or pan rather than stiffness and damping", "Making tiny moves and missing how strongly the corners change the tone"], "scenario_contexts": ["Turning a bright metallic patch into a soft nylon-string tone", "Dialing in a glassy bell character for a lead", "Automating the pad position for a shifting timbre"], "formula_symbolic": "", "formula_words": ""}, {"id": "39ed9b82-3ee8-44a1-ba88-e7693eba3d86", "term": "Sculpture Morph Pad", "definition": "The Morph Pad is a two-dimensional control in Apple's Logic Pro Sculpture that blends between up to five snapshots of morphable parameters stored at its four corners and center. Moving the ball, or recording its motion, smoothly interpolates all morph-enabled settings between those snapshots, and each voice can morph independently. The Morph Pad is a proprietary Apple feature within Sculpture.", "plain_english": "The Morph Pad is a square control in Sculpture, part of Logic Pro from Apple. It stores up to five saved sounds: one at each corner and one in the middle. Dragging the ball blends smoothly between those saved sounds. You can record the movement so the sound keeps changing as it plays.", "purpose_function": "It lets an engineer capture several settings and morph between them, creating evolving, animated sounds from a single patch.", "practical_application": "A sound designer stores different Sculpture settings at the corners, then moves or records the Morph Pad ball to make a patch shift smoothly over time.", "category": "Synthesizer control", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Sculpture", "Sculpture Material Pad", "Morphing", "Vector synthesis", "Snapshot", "Automation"], "common_mistakes": ["Confusing the Morph Pad with the Material Pad, which sets string material only", "Forgetting to store snapshots at the corners before morphing", "Expecting only two sounds to blend when up to five points are available"], "scenario_contexts": ["Recording a slow morph for an evolving film-score texture", "Blending a soft and a bright version of a patch live", "Adding movement to an otherwise static pad"], "formula_symbolic": "", "formula_words": ""}, {"id": "f743eca6-6b2a-40fc-99de-e971023c8c31", "term": "Space Designer", "definition": "Space Designer is a convolution reverb plug-in in Apple's Logic Pro that recreates real or imagined acoustic spaces. It generates reverb by convolving (combining) the input signal with an impulse response, which is a recording of a space's reflections. It also provides synthesized impulse responses, envelopes, filters, and output EQ, and works in mono, stereo, true stereo, and surround. Space Designer is a proprietary Apple feature; the underlying method is generic convolution reverb.", "plain_english": "Space Designer is a reverb plug-in in Logic Pro from Apple. It uses a recording of a real room's echoes, called an impulse response. It combines that recording with your sound to place it in that space. This method is called convolution reverb. It can copy real rooms or invented spaces.", "purpose_function": "It places a sound convincingly into a real or invented acoustic space, which is why engineers use it for realistic ambience and creative spatial effects.", "practical_application": "A mixing engineer loads a hall or plate impulse response in Space Designer on a reverb bus, then sets the reverb length, EQ, and wet level to place vocals or instruments in that space.", "category": "Reverb plug-in", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Convolution reverb", "Impulse response", "ChromaVerb", "Reverb", "Early reflections", "Wet/dry mix"], "common_mistakes": ["Confusing convolution reverb with algorithmic reverb, which computes reflections instead of using a recording", "Automating parameters heavily, since Space Designer must recalculate the impulse response", "Choosing an impulse response whose size does not fit the source, so the space sounds wrong"], "scenario_contexts": ["Placing a lead vocal in a realistic concert hall", "Using a recorded cathedral impulse response for a choir", "Loading a speaker-cabinet impulse response for a special tone"], "formula_symbolic": "", "formula_words": ""}, {"id": "d83825c0-ae79-4381-ac93-9e8391c0afd0", "term": "Spectral Gate", "definition": "Spectral Gate is a creative filter effect in Apple's Logic Pro that divides the frequency spectrum around a user-set center band and processes the ranges above and below a threshold separately. Center Freq and Bandwidth define the band, a Threshold sets when the split occurs, and Super Energy and Sub Energy control the level of frequencies above and below it, with speed and modulation controls for movement. Spectral Gate is a proprietary Apple feature that works in the frequency domain.", "plain_english": "Spectral Gate is a special filter effect in Logic Pro from Apple. It splits a sound into frequency bands around a center point. It then treats the loud and quiet parts differently, splitting them at a level you set called a threshold. Controls set the center, the width, and how much of each part comes through. It is mainly used for odd, creative sounds.", "purpose_function": "It reshapes a sound by frequency and level in ways ordinary filters cannot, so engineers reach for it as a sound-design and special-effects tool.", "practical_application": "A sound designer inserts Spectral Gate, sets the center frequency and threshold, then adjusts Super and Sub Energy and the modulation to create robotic, gated, or metallic textures.", "category": "Filter effect", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Multimode filter", "Noise gate", "Frequency spectrum", "Threshold", "Sound design", "Vocoder"], "common_mistakes": ["Expecting a normal noise gate instead of a frequency-based, spectral effect", "Setting the threshold so extreme that the sound drops out entirely", "Confusing the center-band controls with a standard EQ band"], "scenario_contexts": ["Creating robotic or metallic vocal textures", "Designing glitchy sound effects for electronic music", "Adding unusual movement to a synth or pad"], "formula_symbolic": "", "formula_words": ""}, {"id": "79cfca76-bf09-4b96-b3f5-854d971088ae", "term": "Step FX", "definition": "Step FX is a multi-effect plug-in in Apple's Logic Pro that adds pattern-based, rhythmic modulation using three independent step modulators of up to 128 steps each. The modulators can control parameters of its built-in multimode filter, modulation, delay, reverb, and distortion effects, and an assignable XY pad modulates up to four parameters. Effects run in a reorderable series. Step FX is a proprietary Apple feature built from standard filter, delay, and distortion effects driven by step sequencers.", "plain_english": "Step FX is an effects plug-in in Logic Pro from Apple. It changes a sound in a repeating, rhythmic pattern. Three step sequencers move the controls step by step, in time with the music. It includes a filter, delay, reverb, and distortion. You use it for gated, glitchy, and rhythmic effects.", "purpose_function": "It lets an engineer apply tempo-locked, evolving modulation to effects, creating rhythmic gating, glitch, and movement without drawing automation by hand.", "practical_application": "A producer inserts Step FX on a synth or drum track and programs the step modulators to sweep the filter and delay in time, adding rhythmic pulses and glitches.", "category": "Multi-effect plug-in", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Phat FX", "Remix FX", "Step sequencer", "Multimode filter", "Low-frequency oscillator (LFO)", "Automation"], "common_mistakes": ["Confusing the step modulators with a musical note sequencer that plays pitches", "Setting steps that fight the track's tempo or groove", "Modulating too many parameters at once, making the result chaotic"], "scenario_contexts": ["Creating a rhythmic gating effect on a pad", "Adding stepped filter movement to a bassline", "Designing glitchy transitions for electronic music"], "formula_symbolic": "", "formula_words": ""}, {"id": "37d9d5bf-6cfe-488d-bef6-0e1d99f770ff", "term": "Ultrabeat", "definition": "Ultrabeat is a drum synthesizer and drum-machine instrument in Apple's Logic Pro with 24 assignable drum sounds plus a 25th chromatic voice, and a built-in step sequencer. Each voice combines synthesis sources such as oscillators, a noise generator, filters, and ring modulation, and can also play imported samples. The first 24 MIDI notes trigger the drum voices, while notes from C3 up play the 25th voice melodically. Ultrabeat is a proprietary Apple feature that combines drum synthesis and sampling.", "plain_english": "Ultrabeat is a drum machine in Logic Pro from Apple. It has 24 separate drum sounds plus one extra voice you can play as notes. Each sound is built from synthesis parts or from a sample. A built-in step sequencer lets you program beats. You use it to make and play drum patterns.", "purpose_function": "It combines drum sound design and pattern sequencing in one instrument, so an engineer can both build custom drum sounds and program the beats that play them.", "practical_application": "A producer loads Ultrabeat, assigns kick, snare, and hats to the pads, tweaks each voice's synthesis, then programs a groove in the built-in step sequencer.", "category": "Drum instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Drum Machine Designer", "Quick Sampler", "Step sequencer", "Drum synthesis", "Ring modulation", "Sample"], "common_mistakes": ["Forgetting that the 25th voice from C3 up plays chromatically, not as a drum", "Editing one voice while expecting the change to affect all pads", "Relying only on the internal sequencer and ignoring MIDI region playback"], "scenario_contexts": ["Programming an electronic drum pattern from scratch", "Designing a custom synthesized kick and snare", "Layering an imported sample with a synthesized drum voice"], "formula_symbolic": "", "formula_words": ""}, {"id": "01876af5-f210-42ce-adb8-8546f319cfa6", "term": "Vintage B3", "definition": "Vintage B3 is an organ instrument in Apple's Logic Pro that emulates a Hammond B3-type tonewheel electromechanical organ, with two manuals, a pedalboard, and drawbars. Drawbars mix the levels of harmonically related tones (modeled tonewheels) to build the sound, and the instrument includes the Scanner Vibrato/Chorus and Rotor Cabinet effects. Vintage B3 is a proprietary Apple feature; the underlying instrument is a generic tonewheel organ (Hammond is a trademark of its owner).", "plain_english": "Vintage B3 is an organ instrument in Logic Pro from Apple. It copies a classic tonewheel organ, like the Hammond B3. You mix its sound using sliders called drawbars. Each drawbar adds a related tone at a chosen level. It also includes the organ's vibrato, chorus, and spinning-speaker effects.", "purpose_function": "It reproduces the sound and controls of a classic tonewheel organ so an engineer can play authentic organ parts without the original heavy instrument.", "practical_application": "A keyboardist loads Vintage B3, sets the drawbars for the desired tone, and adds Scanner Vibrato and the Rotor Cabinet to play jazz, rock, gospel, or soul organ parts.", "category": "Organ instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Rotor Cabinet", "Scanner Vibrato", "Drawbar", "Tonewheel organ", "Leslie speaker", "Hammond organ"], "common_mistakes": ["Thinking drawbars are volume faders rather than harmonic level controls", "Forgetting to add the rotary-speaker effect, so the organ sounds static and dry", "Confusing the tonewheel organ model with a pipe-organ sound"], "scenario_contexts": ["Playing a jazz organ comp with a slow rotary speaker", "Setting screaming drawbars and fast rotor for a rock solo", "Recreating a gospel or soul organ part"], "formula_symbolic": "", "formula_words": ""}, {"id": "40c03ce9-4680-4314-a515-a183df4e7fdc", "term": "ADR Taker", "definition": "ADR Taker is the name Steinberg uses for the Automatic Dialogue Replacement (ADR) toolset built into its Nuendo audio post-production software. It drives the ADR workflow with cue markers and dedicated rehearse, record, and review modes, letting a dubbing artist re-record dialogue in sync with picture and a guide track. ADR itself is a standard film and television technique; the ADR Taker name and its implementation belong to Steinberg Media Technologies, a Yamaha subsidiary.", "plain_english": "ADR means re-recording an actor's lines in a studio after filming. Nuendo is post-production software made by Steinberg. Its ADR Taker tools help an actor watch the scene and match new lines to it. A sound editor uses markers to cue, rehearse, record, and check each line.", "purpose_function": "It exists to organize and speed up dialogue replacement, so an editor can loop each line, cue the performer, capture takes locked to picture and a guide track, and review them without rebuilding the setup for every cue.", "practical_application": "A dialogue editor uses it to re-record lines that were too noisy on set, or to dub a film into another language, recording take after take against the original guide track and synced video.", "category": "ADR / Dialogue", "difficulty": "intermediate", "achievement_id": "9c9ab954-ce21-4610-9207-b7ce6016f36e", "cross": [], "related_terms": ["Nuendo", "ADR (Automatic Dialogue Replacement)", "Guide Track", "Cue Marker", "Dialogue Editing", "Signal Switchboard"], "common_mistakes": ["Confusing ADR Taker, which is Steinberg's tool name, with ADR itself, a general film technique found in many programs", "Forgetting to record-enable the target track, so takes are never captured", "Assuming ADR is only for foreign-language dubbing; it also replaces unusable production dialogue", "Not loading synced video and a guide track, which makes accurate lip-sync recording much harder"], "scenario_contexts": ["Replacing dialogue recorded near a noisy freeway during an outdoor film shoot", "Dubbing a television drama into a second language for international release", "Looping a single line an actor delivers repeatedly until the director approves a take", "Reviewing several recorded takes with the director to pick the best match to picture"], "formula_symbolic": "", "formula_words": ""}, {"id": "3aeb0d71-74ba-42ff-be69-c87f4568b893", "term": "Game Audio Connect", "definition": "Game Audio Connect is a feature in Steinberg's Nuendo software that transfers game audio assets from Nuendo to a game audio engine or middleware, such as Audiokinetic Wwise. It provides a two-way link: assets can be sent to the engine, and from the engine a user can open the Nuendo project that contains a selected asset. The feature is a Steinberg (Steinberg Media Technologies, a Yamaha subsidiary) implementation; Wwise is a separate product of Audiokinetic.", "plain_english": "Video games play sounds through special software called a game audio engine. Game Audio Connect links Nuendo, a post-production program by Steinberg, to that engine. A sound designer can build a sound in Nuendo and send it straight to the game tool. They can also jump back from the game tool to the Nuendo project that made a sound.", "purpose_function": "It exists to remove manual export and import steps between sound design and game implementation, keeping audio assets and their source projects linked as designers make repeated changes.", "practical_application": "A game sound designer edits weapon or footstep sounds in Nuendo and pushes them into Wwise, then jumps straight back to the exact Nuendo project when a sound needs another revision.", "category": "Game Audio", "difficulty": "intermediate", "achievement_id": "9c9ab954-ce21-4610-9207-b7ce6016f36e", "cross": [], "related_terms": ["Nuendo", "Wwise", "Game Audio Middleware", "Sound Design", "Audio Asset", "Digital Audio Workstation"], "common_mistakes": ["Thinking Game Audio Connect is a game engine itself; it is a bridge between Nuendo and an external engine such as Wwise", "Assuming it works with any middleware without setup; the network connection between Nuendo and the engine must be configured first", "Overlooking the two-way link, so designers export files manually instead of opening the source project from the engine", "Confusing exported game assets with a finished linear mix; game audio is delivered as many separate implementation-ready assets"], "scenario_contexts": ["Sending a batch of edited creature vocal sounds from Nuendo into Wwise for a game build", "Opening the original Nuendo session directly from the game engine to fix a sound flagged in testing", "Iterating on ambient loops between a sound designer in Nuendo and an implementer in the audio engine", "Keeping asset versions aligned between the DAW and middleware during a long game production"], "formula_symbolic": "", "formula_words": ""}, {"id": "4326a9b0-5c63-4265-aced-d3b69bc52d2c", "term": "Nuendo", "definition": "Nuendo is a professional digital audio workstation (DAW) developed by Steinberg Media Technologies, a subsidiary of Yamaha, aimed at audio post-production for film, television, and game audio. It shares its core audio engine with Steinberg's Cubase but adds post-focused tools such as ADR, immersive and surround mixing, field-recorder import, and synchronization to picture and timecode. It runs on Windows and macOS.", "plain_english": "A digital audio workstation, or DAW, is software for recording, editing, and mixing sound. Nuendo is a DAW made by Steinberg, a company owned by Yamaha. It is built mainly for sound work on film, TV, and games. It handles jobs like dialogue editing, surround mixing, and syncing sound to video.", "purpose_function": "It exists to give post-production sound teams one program to edit dialogue, effects, and music, mix in stereo or immersive formats, and lock audio to picture and timecode.", "practical_application": "A re-recording mixer uses Nuendo to assemble dialogue, effects, and music stems and mix a final soundtrack in surround or Dolby Atmos, synced to the film's video and timecode.", "category": "Post-Production DAW", "difficulty": "intermediate", "achievement_id": "9c9ab954-ce21-4610-9207-b7ce6016f36e", "cross": [], "related_terms": ["Cubase", "Digital Audio Workstation", "ADR Taker", "Nuendo SyncStation", "Stems", "Dolby Atmos"], "common_mistakes": ["Thinking Nuendo and Cubase are identical; they share an engine, but Nuendo adds post-production and immersive tools", "Assuming VST and ASIO are Nuendo-only; Steinberg created them, but they are cross-industry standards", "Believing Nuendo is only for music; it is aimed mainly at film, television, and game audio post", "Treating Nuendo as a free plug-in; it is a paid, standalone application"], "scenario_contexts": ["Mixing a feature film soundtrack in Dolby Atmos on a dubbing stage", "Editing and syncing dialogue for a television episode against locked picture", "Designing and delivering interactive sound assets for a video game", "Conforming a soundtrack to picture changes using timecode and markers"], "formula_symbolic": "", "formula_words": ""}, {"id": "f3d9cfa3-9fec-476e-9176-4026ce24ac24", "term": "Nuendo Live", "definition": "Nuendo Live is a streamlined live multitrack recording application from Steinberg Media Technologies, separate from the full Nuendo DAW. It records many inputs at once through an ASIO audio driver, automatically creating one track per active input port, and supports markers and session metadata. Projects recorded in Nuendo Live can be opened in Nuendo (or Cubase) for later editing and mixing. It runs on Windows and macOS.", "plain_english": "Nuendo Live is a simple recording program made by Steinberg. It is built to capture a live show on many tracks at once. It makes one track for each input and can start fast with one-button recording. Later, an engineer opens the recording in bigger software like Nuendo to mix it.", "purpose_function": "It exists to give live-sound engineers a fast, reliable way to capture every channel of a concert or event with minimal setup, ready for later post-production.", "practical_application": "At a concert, an engineer runs Nuendo Live on a laptop fed from the mixing console's digital output, uses Easy Record to capture all channels, and drops markers between songs for editing.", "category": "Live Recording", "difficulty": "intermediate", "achievement_id": "9c9ab954-ce21-4610-9207-b7ce6016f36e", "cross": [], "related_terms": ["Nuendo", "Multitrack Recording", "ASIO", "Digital Audio Workstation", "Marker", "Mixing Console"], "common_mistakes": ["Confusing Nuendo Live with full Nuendo; Nuendo Live is a simpler capture-focused tool", "Not selecting the correct ASIO driver in Settings, so no inputs appear", "On digital connections, failing to set the mixing console as word-clock master, which risks clicks and dropouts", "Expecting to do the full mix in it; heavy editing and mixing are done in Nuendo or Cubase"], "scenario_contexts": ["Recording every channel of a live band performance for a later studio mix", "Capturing a conference or theater show as a safety multitrack backup", "Using Easy Record to arm and start all tracks quickly before a show begins", "Marking song boundaries during a concert so editors can split takes afterward"], "formula_symbolic": "", "formula_words": ""}, {"id": "7b34ee8a-5bd3-4cab-8f2d-dcf4da8ca82f", "term": "Nuendo SyncStation", "definition": "The Nuendo SyncStation is a hardware synchronizer made by Steinberg Media Technologies for audio post-production. It reads, generates, and distributes timecode over LTC, MTC, and Sony 9-pin (RS-422), locks audio to a video sync reference (bi-level SD or tri-level HD), and distributes word clock and digital audio clock, keeping a Nuendo system frame- and sample-accurate with external video and machines. It also provides machine control (MMC and Sony 9-pin) of VTRs and other transports.", "plain_english": "The Nuendo SyncStation is a hardware box made by Steinberg. Its job is to keep sound and picture playing in perfect step. It reads and sends timecode, the clock that labels each film frame. It also locks the audio computer to the video and can control tape and video machines.", "purpose_function": "It exists to give a Nuendo post-production room one central unit that ties the computer, video reference, timecode, and outboard machines together so everything runs in exact sync.", "practical_application": "On a mixing stage, an engineer uses the SyncStation to lock Nuendo to house video sync and timecode and to control a video playback machine over Sony 9-pin during a film mix.", "category": "Sync Hardware", "difficulty": "intermediate", "achievement_id": "9c9ab954-ce21-4610-9207-b7ce6016f36e", "cross": [], "related_terms": ["Timecode", "LTC (Linear Timecode)", "Word Clock", "9-Pin (Sony P2) Machine Control", "Nuendo", "Video Sync"], "common_mistakes": ["Assuming it is only a clock generator; it also handles timecode, video sync, and machine control", "Forgetting to enable Activate External Sync in Nuendo, so the system does not lock to the SyncStation", "Mixing up word clock with timecode; word clock aligns samples, while timecode labels frames and positions", "Choosing the wrong video sync type, such as feeding tri-level HD reference to a bi-level SD setup"], "scenario_contexts": ["Locking a Nuendo mixing stage to house video reference and timecode for a film re-record", "Controlling an external video deck over 9-pin from Nuendo's transport", "Distributing word clock to interfaces and converters so all digital audio stays sample-aligned", "Regenerating timecode to feed several devices from one master reference"], "formula_symbolic": "", "formula_words": ""}, {"id": "e98d7277-28dd-4111-a707-d5cb3331dedf", "term": "Acoustic Agent", "definition": "Acoustic Agent is one of the three rhythm modules inside Groove Agent, Steinberg's virtual drum instrument. It plays realistic acoustic drum kits built from detailed multisamples of real drums, and it uses a Style Player with ready-made patterns such as intros, fills, main grooves, and endings. Groove Agent and Acoustic Agent are trademarks of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "Acoustic Agent is a part of Groove Agent, a drum software instrument. It plays recordings of real acoustic drum kits. It also comes with built-in drum patterns like fills and grooves. You trigger the drums and patterns from a keyboard or MIDI.", "purpose_function": "It exists to give producers convincing, playable acoustic drum tracks without recording a live drummer, using multisampled kits and pattern-based styles.", "practical_application": "A technician loads an Acoustic Agent kit in Groove Agent, picks a style, and drops fills and grooves into a song to build a natural-sounding drum track.", "category": "Drum Instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Groove Agent", "Beat Agent", "Percussion Agent", "HALion Sonic", "Multisampling"], "common_mistakes": ["Confusing Acoustic Agent with the whole Groove Agent plug-in; it is only one module inside it", "Thinking its kits are synthesized; they are multisampled recordings of real drums", "Assuming the built-in styles cannot be changed; complexity and performance controls edit them"], "scenario_contexts": ["Building a realistic drum track for a pop or rock song", "Auditioning fills and grooves against a project tempo", "Layering an acoustic kit under a programmed beat"], "formula_symbolic": "", "formula_words": ""}, {"id": "f8d42b1d-126c-467f-b5fd-893c302a0136", "term": "Audio Stream Input/Output", "definition": "Audio Stream Input/Output (ASIO) is an audio driver standard developed by Steinberg that lets audio software communicate directly with an audio interface. It bypasses the operating system's audio layer to provide low-latency, multichannel input and output, chiefly on Windows. Although Steinberg owns the trademark and specification, ASIO has become a cross-industry standard supported by most professional interfaces and Windows audio programs.", "plain_english": "ASIO stands for Audio Stream Input/Output. It is a special driver that links music software to your audio interface. It skips extra Windows processing so sound reaches you with very little delay. Steinberg created it, but almost every audio interface now supports it.", "purpose_function": "It exists to cut latency and give reliable, multichannel audio streaming between a DAW and hardware, which is essential for recording and live monitoring.", "practical_application": "A technician selects the interface's ASIO driver in the DAW's audio settings and adjusts the buffer size to balance latency against CPU load.", "category": "Audio Driver Standard", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Virtual Studio Technology", "Latency", "Buffer Size", "Digital Audio Workstation", "Sample Rate"], "common_mistakes": ["Confusing ASIO with a plug-in; it is a driver protocol, not an effect or instrument", "Assuming ASIO4ALL is Steinberg's official driver; it is a third-party wrapper", "Setting the buffer too low, which causes audio dropouts and clicks"], "scenario_contexts": ["Configuring a USB interface for low-latency recording in a DAW", "Troubleshooting audio dropouts by raising the ASIO buffer size", "Setting up multi-output routing from a DAW to a mixer"], "formula_symbolic": "", "formula_words": ""}, {"id": "9addc92d-cb57-41f1-bc92-0c5155e1bd5c", "term": "Backbone Decompose", "definition": "Decompose is a function in Steinberg Backbone, a drum layering and re-synthesis instrument. It analyzes a loaded sample and splits it into two new samples: one holding the tonal (pitched) content and one holding the noise content, using Sensitivity, Cutoff, and Duration settings. Each part can then be edited, replaced, or rebalanced separately. Backbone is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "Decompose is a tool inside Steinberg's Backbone drum software. It takes a drum sound apart into two pieces. One piece holds the clear, pitched part. The other holds the noisy part. You can then change each piece on its own.", "purpose_function": "It exists to let sound designers reshape or rebuild drum sounds by treating their pitched body and their noise content separately.", "practical_application": "A technician decomposes a snare sample in Backbone, then swaps its noise layer for a different snare's noise to design a new hybrid drum.", "category": "Sound Design Tool", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Beat Agent", "Groove Agent", "HALion", "Sampler", "Transient"], "common_mistakes": ["Expecting Decompose to isolate transients; it separates tonal versus noise content, not attack from body", "Assuming the split is perfect; the Sensitivity, Cutoff, and Duration settings change the result", "Thinking Backbone is a full drum machine like Groove Agent rather than a re-synthesis instrument"], "scenario_contexts": ["Designing a custom snare from parts of two samples", "Cleaning up or replacing the noise tail of a drum hit", "Re-pitching only the tonal body of a kick"], "formula_symbolic": "", "formula_words": ""}, {"id": "96191719-d6c4-45ba-be84-303f6dd14607", "term": "Beat Agent", "definition": "Beat Agent is one of the three rhythm modules inside Groove Agent, Steinberg's virtual drum instrument. It is a sample-based drum module: you load kits of individual drum samples onto pads, layer and shape them, and you can import your own samples. It also includes a Decompose function that splits samples into tonal and noise parts. Groove Agent is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "Beat Agent is a part of Groove Agent, a drum software instrument. It plays drum sounds loaded onto pads. You can use its own kits or import your own samples. It is built for making electronic and hip-hop style beats.", "purpose_function": "It exists to give producers a flexible, sample-based drum engine for beat-making and sound design, where each pad holds and shapes a drum sample.", "practical_application": "A technician loads samples onto Beat Agent pads, tweaks pitch and filtering, and programs a beat for an electronic track.", "category": "Drum Instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Groove Agent", "Acoustic Agent", "Percussion Agent", "Backbone Decompose", "Sampler"], "common_mistakes": ["Confusing Beat Agent with the whole Groove Agent plug-in; it is one module inside it", "Assuming it only plays factory kits; it also imports user samples", "Overlooking the Decompose function for reshaping loaded samples"], "scenario_contexts": ["Programming a hip-hop or electronic beat from sampled drums", "Importing custom one-shots to build a signature kit", "Layering two samples on one pad for a fuller sound"], "formula_symbolic": "", "formula_words": ""}, {"id": "4f7cf4fb-02c9-4dc1-9c0b-9afc03f46291", "term": "Groove Agent", "definition": "Groove Agent is a virtual drum instrument from Steinberg, available as a VST plug-in and standalone application. It combines three rhythm modules - Acoustic Agent, Beat Agent, and Percussion Agent - can load up to four kits at once, and ships with a large library of patterns and styles. Groove Agent is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "Groove Agent is a drum software instrument. It works like a drum machine and a drum sampler in one. It has three engines: real acoustic kits, sampled beats, and percussion. It comes with many ready-made drum patterns you can play and edit.", "purpose_function": "It exists to provide programmable drum tracks, combining playable kits with pattern-based styles for producing rhythm parts inside a DAW.", "practical_application": "A technician loads Groove Agent on a MIDI track, chooses a kit and style, and builds a drum arrangement by triggering pads and patterns.", "category": "Virtual Drum Instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Acoustic Agent", "Beat Agent", "Percussion Agent", "HALion Sonic", "Virtual Studio Technology"], "common_mistakes": ["Confusing the full Groove Agent with its single Agent modules", "Assuming Groove Agent SE (bundled with Cubase) has the full version's content", "Thinking it only plays factory patterns; kits and patterns can be edited or user-built"], "scenario_contexts": ["Creating a drum track for a song without a live drummer", "Combining an acoustic kit with a programmed electronic beat", "Performing drum patterns live from pads or a MIDI keyboard"], "formula_symbolic": "", "formula_words": ""}, {"id": "c04645a0-d70c-45c1-9584-a11955ded245", "term": "HALion", "definition": "HALion is a virtual sampler and sound-design workstation from Steinberg, available as a VST plug-in and standalone application. Beyond sample playback, it includes multiple synthesis engines - among them granular, wavetable, virtual analog (subtractive), FM, spectral, and organ - plus deep editing and scripting for building custom instruments. HALion is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "HALion is a software sampler and sound-building tool. A sampler plays back recorded sounds across a keyboard. HALion can also create sounds using several synthesis methods. Sound designers use it to build their own instruments from scratch.", "purpose_function": "It exists to let users play sampled instruments and design new ones, combining sampling with many synthesis methods in one deep environment.", "practical_application": "A technician builds a custom sampled instrument in HALion by mapping samples across the keyboard, then adds synthesis layers and effects.", "category": "Sampler Workstation", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["HALion Sonic", "Padshop", "Sampler", "Wavetable Synthesis", "Virtual Studio Technology"], "common_mistakes": ["Confusing HALion with HALion Sonic; HALion is the full editor, Sonic is mainly a player", "Thinking it is only a sampler; it also offers granular, wavetable, and other synthesis", "Underestimating its scripting and macro tools when just loading presets"], "scenario_contexts": ["Building a sample-based instrument library for a studio", "Designing a hybrid sample-and-synth patch", "Editing multisamples and key mapping for a custom kit"], "formula_symbolic": "", "formula_words": ""}, {"id": "9b97266e-605c-4c9b-972d-20d7e6732f66", "term": "HALion Sonic", "definition": "HALion Sonic is a multitimbral workstation instrument and content player from Steinberg. It plays HALion sound programs and presets across up to 16 slots, with quick controls, arpeggiators, and effects, but it is aimed at performing and lightly tweaking ready-made sounds rather than deep sound creation. HALion Sonic is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "HALion Sonic is a software instrument that plays ready-made sounds. It loads presets and can play up to 16 at once. It is the player version of HALion, the bigger sound-building tool. Musicians use it to quickly find and play sounds.", "purpose_function": "It exists to give musicians a large, ready-to-play sound library with light editing, acting as the player counterpart to HALion's full creation tools.", "practical_application": "A technician loads HALion Sonic, browses presets, and layers several instrument sounds across its slots for a live rig or a quick production.", "category": "Instrument Player", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["HALion", "Groove Agent", "Virtual Studio Technology", "Multitimbral", "Preset"], "common_mistakes": ["Confusing HALion Sonic with HALion; Sonic mainly plays content, HALion creates it", "Assuming HALion Sonic SE (free with Cubase) includes the full library", "Expecting deep sound-design tools that belong to full HALion"], "scenario_contexts": ["Loading multiple instrument sounds for a live keyboard rig", "Quickly auditioning presets during a session", "Playing orchestral or synth sounds inside a DAW"], "formula_symbolic": "", "formula_words": ""}, {"id": "81704283-a4ba-4097-abc2-f0fab0ce9c56", "term": "Magneto", "definition": "Magneto is Steinberg's tape-saturation effect plug-in; the current version, Magneto II, simulates the saturation and compression of recording onto analog tape machines. It adds harmonic warmth and gentle compression to individual tracks or full mixes. Magneto is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary, and the underlying method is analog tape emulation.", "plain_english": "Magneto is a Steinberg effect that copies the sound of analog tape. Old tape recorders added a warm, slightly squashed color. Magneto recreates that color on digital audio. Engineers use it to make tracks sound fuller and less harsh.", "purpose_function": "It exists to add analog tape character - saturation, harmonics, and mild compression - to digital recordings that can otherwise sound clean or clinical.", "practical_application": "A technician inserts Magneto II on a drum bus or full mix and drives the input to add warmth and glue.", "category": "Saturation Effect", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Quadrafuzz", "REVerence", "Saturation", "Harmonic Distortion", "Compression"], "common_mistakes": ["Overdriving the input so saturation becomes unwanted distortion", "Assuming it models one specific named tape machine; it is a general tape emulation", "Confusing tape saturation with a compressor; it does both subtly, not heavy dynamics control"], "scenario_contexts": ["Warming up a clean digital mix", "Adding subtle drive to a drum bus", "Taming a harsh top end on a bright source"], "formula_symbolic": "", "formula_words": ""}, {"id": "775db4b8-8f60-4fe7-ba6e-51f4bb5dd233", "term": "Padshop", "definition": "Padshop is a software synthesizer from Steinberg built on granular synthesis; the current version, Padshop 2, adds a spectral oscillator. Its grain oscillator plays many short slices (grains) of a sample in sequence to build evolving pads and textures, while the spectral oscillator resynthesizes sound from a sample's frequency content. Padshop is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary, and the core method is granular (and spectral) synthesis.", "plain_english": "Padshop is a Steinberg synthesizer that uses granular synthesis. Granular synthesis chops a sound into tiny grains and replays them. This builds rich, slowly changing textures and pads. The newer version can also rebuild sounds from their frequencies.", "purpose_function": "It exists to create evolving pads, textures, and atmospheres by turning sample material into grains or into resynthesized spectra.", "practical_application": "A technician loads a sample into Padshop and adjusts grain and position controls to design an evolving pad for a film or ambient cue.", "category": "Software Synthesizer", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["HALion", "Retrologue", "Granular Synthesis", "Wavetable Synthesis", "Virtual Studio Technology"], "common_mistakes": ["Confusing granular synthesis with simple sample playback", "Expecting a classic analog synth; Padshop is granular and spectral, not subtractive like Retrologue", "Assuming grains always sound smooth; grain size and envelope settings affect artifacts"], "scenario_contexts": ["Designing an evolving pad for ambient or film music", "Turning a spoken-word or noise sample into a pitched texture", "Creating drones and soundscapes from short samples"], "formula_symbolic": "", "formula_words": ""}, {"id": "9bc8bdfc-4157-4f23-8037-abdbfdf45670", "term": "Percussion Agent", "definition": "Percussion Agent is one of the three rhythm modules inside Groove Agent, Steinberg's virtual drum instrument. It focuses on multisampled percussion instruments and includes percussion styles designed to complement Acoustic Agent's drum styles. Groove Agent is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "Percussion Agent is a part of Groove Agent, a drum software instrument. It plays percussion sounds like congas, shakers, and tambourines. It also has percussion patterns. These patterns are made to sit alongside the acoustic drum kits.", "purpose_function": "It exists to add realistic, pattern-based percussion that layers under or beside a main drum kit in a production.", "practical_application": "A technician adds a Percussion Agent style over an Acoustic Agent groove to bring extra rhythmic movement to a track.", "category": "Drum Instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Groove Agent", "Acoustic Agent", "Beat Agent", "HALion Sonic", "Multisampling"], "common_mistakes": ["Confusing Percussion Agent with the whole Groove Agent plug-in", "Using its complement styles without a main kit, so the rhythm feels incomplete", "Assuming it plays full drum kits rather than percussion instruments"], "scenario_contexts": ["Layering congas and shakers over a drum groove", "Adding percussion fills to a Latin or pop arrangement", "Building a percussion-only rhythmic bed"], "formula_symbolic": "", "formula_words": ""}, {"id": "7fb61266-d4a0-4453-9de6-ed81072ec063", "term": "Quadrafuzz", "definition": "Quadrafuzz is Steinberg's multiband distortion effect; the current version, Quadrafuzz v2, splits the signal into up to four frequency bands and distorts each band independently, offering several distortion modes. It is aimed at processing drums and loops but also works on vocals and other sources. Quadrafuzz is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary, and the underlying method is multiband distortion.", "plain_english": "Quadrafuzz is a Steinberg distortion effect. It splits a sound into up to four frequency ranges. Then it distorts each range on its own. This lets you add grit to the highs without wrecking the lows. It is popular on drums and loops.", "purpose_function": "It exists to apply controlled, frequency-specific distortion, so different parts of a sound get different amounts and types of grit.", "practical_application": "A technician uses Quadrafuzz v2 on a drum loop to add bite to the high band while keeping the kick clean in the low band.", "category": "Distortion Effect", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Magneto", "REVerence", "Multiband Compression", "Distortion", "Saturation"], "common_mistakes": ["Treating it as a single-band fuzz; its point is separate frequency bands", "Distorting the low band too hard, which muddies the sound", "Ignoring the band crossover settings that decide where each band sits"], "scenario_contexts": ["Adding aggressive grit to a drum loop", "Distorting only the high frequencies of a bass", "Roughening a vocal for a special effect"], "formula_symbolic": "", "formula_words": ""}, {"id": "d1cf06ff-88b4-422e-8ca6-a0969e072b7f", "term": "REVerence", "definition": "REVerence is a convolution reverb effect from Steinberg, included in Cubase and Nuendo. It applies the acoustic character of a real space to audio by convolving the signal with an impulse response - a recording that captures how a room responds to sound. REVerence is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary, and the underlying method is convolution reverb.", "plain_english": "REVerence is a Steinberg reverb effect. It uses recordings of real spaces called impulse responses. It stamps that room's echo onto your audio. So a dry voice can sound like it was recorded in a cathedral. This is called convolution reverb.", "purpose_function": "It exists to place audio in a realistic acoustic space by using measured impulse responses of real rooms, halls, and hardware units.", "practical_application": "A technician loads a concert-hall impulse response into REVerence on a vocal to make it sound recorded in that hall.", "category": "Reverb Effect", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Magneto", "Quadrafuzz", "Impulse Response", "Convolution", "Reverberation"], "common_mistakes": ["Confusing convolution reverb with algorithmic reverb; REVerence uses recorded impulse responses", "Loading many impulse responses at once, which uses large amounts of RAM", "Assuming any audio file works well as an impulse response"], "scenario_contexts": ["Placing a dry vocal in a realistic concert hall", "Matching a foley recording to an on-screen room", "Applying a captured hardware unit's impulse response to a mix"], "formula_symbolic": "", "formula_words": ""}, {"id": "343a0918-96a9-4e11-bbb8-bb772a545618", "term": "Retrologue", "definition": "Retrologue is a virtual analog synthesizer from Steinberg based on subtractive synthesis. It provides oscillators, filters, envelopes, LFOs, a modulation matrix, an arpeggiator, and built-in effects to create classic synthesizer sounds. Retrologue is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary, and the underlying method is virtual analog (subtractive) synthesis.", "plain_english": "Retrologue is a Steinberg synthesizer. It copies the way old analog synths work. It starts with rich waveforms and filters out parts of them. This is called subtractive synthesis. Musicians use it for basses, leads, and pads.", "purpose_function": "It exists to produce classic analog-style synth sounds - basses, leads, pads, and effects - using modelled subtractive synthesis inside a DAW.", "practical_application": "A technician loads Retrologue, picks oscillator waveforms, and shapes a bass sound with the filter and envelope for a track.", "category": "Software Synthesizer", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Padshop", "HALion", "Subtractive Synthesis", "Oscillator", "Virtual Studio Technology"], "common_mistakes": ["Confusing virtual analog with sampling; Retrologue generates sound, it does not play samples", "Ignoring the filter, which is central to subtractive synthesis", "Expecting granular textures like Padshop; Retrologue is a subtractive synth"], "scenario_contexts": ["Programming an analog-style bass or lead", "Designing a warm pad for a pop track", "Creating classic synth sweeps and effects"], "formula_symbolic": "", "formula_words": ""}, {"id": "6fd04351-cf1d-4b60-8283-5cef870dbbc9", "term": "Audio Montage", "definition": "The Audio Montage is a multichannel, multitrack, non-destructive editing environment in Steinberg's WaveLab. It lets an engineer arrange, edit, cross-fade, process, and play back audio clips on unlimited mono or stereo tracks, with clip- and track-based effects and volume/pan automation. It is the primary workspace for sequencing and mastering albums and for authoring Audio CDs and DDP images. Audio Montage and WaveLab are trademarks of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "The Audio Montage is WaveLab's multitrack workspace. You place song clips on separate tracks and arrange them in order. Editing is non-destructive, so your original files stay untouched. Engineers use it to master albums and build CDs or delivery files.", "purpose_function": "It exists to let engineers assemble, sequence, and master several audio clips together non-destructively, then output the result as a CD, DDP image, or set of files.", "practical_application": "A mastering engineer drops each song onto Montage tracks, sets fades and gaps, adds mastering plug-ins per clip, then renders the album or burns a CD or DDP master.", "category": "Mastering Environment", "difficulty": "intermediate", "achievement_id": "59ad0dd1-d2da-4067-ba31-93c84eaf69db", "cross": [], "related_terms": ["WaveLab", "MasterRig", "Meta Normalizer", "SuperClip", "Master Section", "DDP"], "common_mistakes": ["Confusing the Audio Montage with a simple wave editor; it is a multitrack, non-destructive arranger", "Thinking edits change the source files; the Montage stores instructions and leaves originals intact", "Forgetting to render or burn the finished montage, so the arranged and processed result is never produced"], "scenario_contexts": ["Sequencing and mastering an album before creating a CD or DDP master", "Producing a radio spot by layering voice, music, and effect clips", "Assembling songs recorded at different sample rates into one album project"], "formula_symbolic": "", "formula_words": ""}, {"id": "c8298c4f-552c-45a3-8307-b17bf994b4f5", "term": "MasterRig", "definition": "MasterRig is a modular mastering plug-in bundled with Steinberg's WaveLab. It provides a reorderable chain of mastering modules - Equalizer, Dynamic EQ, Compressor, Saturator, Imager, and Limiter - that the user adds and arranges freely, with multiband and Mid/Side processing available. MasterRig and WaveLab are trademarks of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "MasterRig is a mastering effect built into WaveLab. It holds several modules, such as an equalizer, compressor, saturator, and limiter. You stack the modules in any order to build a mastering chain. Engineers use it to polish a finished mix's tone, dynamics, and loudness.", "purpose_function": "It exists to give mastering engineers a single, reorderable chain of core mastering processors - EQ, dynamics, saturation, stereo imaging, and limiting - inside WaveLab.", "practical_application": "On a master, a technician loads MasterRig, adds EQ, compressor, and limiter modules, and orders them to shape tone, control dynamics, and set the final level.", "category": "Mastering Plug-in", "difficulty": "intermediate", "achievement_id": "59ad0dd1-d2da-4067-ba31-93c84eaf69db", "cross": [], "related_terms": ["WaveLab", "Audio Montage", "Master Section", "Limiter", "Dynamic EQ", "Mid/Side processing"], "common_mistakes": ["Assuming module order is fixed; MasterRig modules can be reordered to change the chain", "Thinking it is a single processor; it is a rack of separate mastering modules", "Over-driving the Limiter module and crushing the master's dynamics and transients"], "scenario_contexts": ["Building a mastering chain on a final stereo mix", "Applying multiband compression and Mid/Side EQ during mastering", "Setting the final limiter stage before rendering a master"], "formula_symbolic": "", "formula_words": ""}, {"id": "a6e34807-6f18-4394-96d4-080945ccf684", "term": "Meta Normalizer", "definition": "The Loudness Meta Normalizer is a WaveLab Audio Montage tool that matches the loudness of every clip so all songs play at the same perceived level. It works purely by adjusting clip gains - it applies no compression and does not alter the source audio - and it lowers other clips' gain when needed to avoid clipping. Loudness is measured to the EBU R 128 recommendation, which is based on ITU-R BS.1770. Loudness Meta Normalizer and WaveLab are trademarks of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "The Loudness Meta Normalizer makes every song on an album sound equally loud. It only changes each clip's volume level, not the audio itself. It measures loudness using the EBU R128 broadcast standard. If matching would cause clipping, it turns other clips down instead.", "purpose_function": "It exists to give an album consistent loudness across all tracks, so listeners need not change the volume between songs, while stopping peaks from clipping.", "practical_application": "After sequencing an album, a mastering engineer runs the Meta Normalizer to bring all songs to a common loudness target before rendering the final master.", "category": "Loudness Tool", "difficulty": "intermediate", "achievement_id": "59ad0dd1-d2da-4067-ba31-93c84eaf69db", "cross": [], "related_terms": ["Audio Montage", "WaveLab", "LUFS", "EBU R128", "True-peak", "Loudness normalization"], "common_mistakes": ["Thinking it compresses audio; it only changes gain and never adds compression", "Assuming it edits the source files; it works non-destructively on clip gains", "Expecting identical peak levels; it matches perceived loudness, not peaks"], "scenario_contexts": ["Matching loudness across all songs on an album before the final render", "Bringing a compilation of tracks to one broadcast loudness target", "Raising quieter songs to match louder ones without clipping"], "formula_symbolic": "", "formula_words": ""}, {"id": "9b9b324f-3d5c-4da6-9d14-11ac043c0339", "term": "SuperClip", "definition": "In Steinberg's WaveLab, a super clip is a clip in an Audio Montage that represents another (sub) audio montage nested inside it. The sub-montage is rendered to an audio file that plays back like an ordinary clip; to change it, the user reopens the super clip, edits the sub-montage, and re-renders. Super clips can be mono or stereo and can hold audio at a different sample rate from the main montage. The super clip is a WaveLab feature; WaveLab is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "A super clip lets you put one WaveLab montage inside another. WaveLab renders the inner montage to an audio file. That file then behaves like a normal clip in the main project. To edit it, you reopen the super clip and render it again.", "purpose_function": "It exists to simplify complex montages: each song gets its own detailed sub-montage, and the main album montage just holds the finished super clips in order.", "practical_application": "For an album, an engineer builds each song as its own montage, turns each into a super clip, and arranges the super clips in one master album montage.", "category": "Montage Feature", "difficulty": "intermediate", "achievement_id": "59ad0dd1-d2da-4067-ba31-93c84eaf69db", "cross": [], "related_terms": ["Audio Montage", "WaveLab", "MasterRig", "Meta Normalizer", "Non-destructive editing"], "common_mistakes": ["Assuming a super clip updates automatically; you must re-render it after editing the sub-montage", "Confusing it with clipping or level overload; it is about nesting montages, not distortion", "Forgetting a super clip can hold a different sample rate than the main montage"], "scenario_contexts": ["Building an album where each song is its own sub-montage", "Editing one song in isolation, then re-rendering its super clip into the album", "Delivering an album at 44.1 kHz while sub-montages hold 96 kHz audio"], "formula_symbolic": "", "formula_words": ""}, {"id": "80fa9f85-8e6d-491f-92a5-2254347050b3", "term": "WaveLab", "definition": "WaveLab is an audio editing and mastering application developed by Steinberg for macOS and Windows. It provides sample-accurate wave editing, the multitrack Audio Montage, mastering plug-ins, spectral editing and restoration, loudness and spectral analysis and metering, batch processing, and Audio CD and DDP authoring. It is sold in tiers - WaveLab Pro, WaveLab Elements, and the entry-level WaveLab Cast. WaveLab is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "WaveLab is Steinberg's software for editing and mastering audio. You can edit single files down to the sample, or arrange many clips on tracks. It includes mastering effects, loudness meters, and repair tools. Engineers use it to finish and deliver masters, CDs, and podcasts.", "purpose_function": "It exists as a dedicated environment for the final stages of audio production - mastering, editing, restoration, analysis, and delivery - rather than for tracking and mixing a full multitrack session.", "practical_application": "A mastering engineer imports a mix into WaveLab, edits and processes it, checks loudness meters, then renders masters or authors a CD or DDP image for release.", "category": "Mastering Software", "difficulty": "intermediate", "achievement_id": "59ad0dd1-d2da-4067-ba31-93c84eaf69db", "cross": [], "related_terms": ["Audio Montage", "MasterRig", "WaveLab Cast", "WaveLab Exchange", "Meta Normalizer", "DDP"], "common_mistakes": ["Treating WaveLab as a full recording and mixing DAW; it targets editing, mastering, and delivery", "Assuming all features exist in every tier; Cast and Elements have fewer tools than Pro", "Editing destructively without realizing the Audio Montage offers a non-destructive workflow"], "scenario_contexts": ["Mastering a stereo mix and rendering release-ready files", "Authoring an Audio CD or DDP image for replication", "Restoring and cleaning up an archived recording"], "formula_symbolic": "", "formula_words": ""}, {"id": "c51dba8d-a39e-4ed4-81ab-f695ae77b10b", "term": "WaveLab Cast", "definition": "WaveLab Cast is the entry-level edition of Steinberg's WaveLab, aimed at podcasters and social and video content creators. It offers multitrack recording (for example, one track per podcast speaker), sample-accurate and non-destructive Audio Montage editing, VST effects, EBU R 128 loudness metering and normalization, and podcast publishing with RSS feed management. WaveLab and WaveLab Cast are trademarks of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "WaveLab Cast is the beginner version of WaveLab. It is made for people who record and publish podcasts or online video audio. You can record each speaker on a separate track and edit it. It also checks loudness for streaming and helps you publish your podcast.", "purpose_function": "It exists to give podcasters and content creators a simple tool to record, edit, level, and publish spoken-word and multimedia audio at the loudness that streaming platforms expect.", "practical_application": "A podcaster records each guest to a separate track in WaveLab Cast, edits and levels the episode to an EBU R128 target, then publishes it through an RSS feed.", "category": "Mastering Software", "difficulty": "intermediate", "achievement_id": "59ad0dd1-d2da-4067-ba31-93c84eaf69db", "cross": [], "related_terms": ["WaveLab", "Audio Montage", "Meta Normalizer", "LUFS", "EBU R128", "Loudness normalization"], "common_mistakes": ["Expecting full WaveLab Pro mastering tools; Cast is a reduced entry-level edition", "Ignoring loudness targets, so the podcast is too quiet or too loud for platforms", "Recording all speakers to one track, losing the ability to edit each voice separately"], "scenario_contexts": ["Recording and editing a multi-speaker podcast episode", "Normalizing a video voiceover to a platform loudness target", "Publishing a podcast episode through an RSS feed"], "formula_symbolic": "", "formula_words": ""}, {"id": "316b05da-1047-4020-9739-edbcf1bafbab", "term": "WaveLab Exchange", "definition": "WaveLab Exchange is a feature that links Steinberg's WaveLab Pro with Steinberg's Cubase and Nuendo DAWs so each can act as an external audio editor for the other. It lets a user send a clip from Cubase Pro, Cubase Artist, or Nuendo to WaveLab Pro for detailed editing, then return the processed WAV file to the DAW, and vice versa. It requires compatible versions (Cubase Pro/Artist 8.5.10 or higher, Nuendo 7.1.20 or higher) and works with the WAV file format. WaveLab, Cubase, and Nuendo are trademarks of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "WaveLab Exchange connects WaveLab with Steinberg's Cubase and Nuendo. It lets you send an audio clip from Cubase or Nuendo into WaveLab for close editing. When you finish, the edited file goes back to the DAW. It works both ways and uses WAV files.", "purpose_function": "It exists to give a smooth round-trip workflow, so an engineer can do sample-level or mastering edits in WaveLab without manually exporting and re-importing files.", "practical_application": "A mixing engineer opens a clip from Cubase or Nuendo in WaveLab Pro for detailed cleanup, and the edited WAV returns to the project automatically.", "category": "DAW Integration", "difficulty": "intermediate", "achievement_id": "59ad0dd1-d2da-4067-ba31-93c84eaf69db", "cross": [], "related_terms": ["WaveLab", "Audio Montage", "MasterRig", "Cubase", "Nuendo"], "common_mistakes": ["Assuming any DAW works; Exchange only links WaveLab Pro with Steinberg's Cubase and Nuendo", "Overlooking the minimum version requirements for Cubase, Nuendo, and WaveLab", "Expecting non-WAV formats; the exchange operates on WAV files"], "scenario_contexts": ["Sending a noisy vocal clip from Nuendo to WaveLab for restoration", "Doing sample-accurate edits in WaveLab, then returning to a Cubase mix", "Round-tripping a stem for mastering between Cubase and WaveLab"], "formula_symbolic": "", "formula_words": ""}, {"id": "3159ed54-c2a9-4416-ba3b-ab64c9e55432", "term": "Chord Assistant", "definition": "The Chord Assistant is a feature in Steinberg's Cubase and Nuendo that suggests chords to follow a selected chord, helping build chord progressions on the Chord Track or with Chord Pads. It offers several modes, including a List mode, a Proximity mode that ranks suggestions by how closely they relate to the current chord, and a Circle of Fifths mode based on classical harmonic relationships. Chord Assistant is a trademark feature of Steinberg Media Technologies GmbH, a Yamaha subsidiary; the underlying harmony rules, such as voice leading and the circle of fifths, are standard music theory.", "plain_english": "The Chord Assistant helps you pick chords that sound good together. You choose one chord, and it suggests chords that fit after it. It can rank the choices by how closely they relate to your chord. This helps if you do not know much music theory.", "purpose_function": "It exists to speed up songwriting and help users find musically sensible chord progressions without deep theory knowledge, by suggesting related chords.", "practical_application": "A songwriter opens the Chord Editor, clicks Chord Assistant, and auditions suggested chords to build or extend a progression on the Chord Track.", "category": "Composition Tool", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["Chord Track", "Chord Pads", "MIDI", "Circle of Fifths", "Digital Audio Workstation"], "common_mistakes": ["Thinking it writes a whole song automatically; it only suggests chords one step at a time", "Assuming every mode is in every edition; List and Proximity modes are Cubase Pro only", "Confusing the Chord Assistant with Chord Pads; the Assistant suggests chords, while Chord Pads trigger them"], "scenario_contexts": ["Building a chord progression when unsure which chord comes next", "Exploring reharmonization options for an existing part", "Teaching chord relationships using the Circle of Fifths mode"], "formula_symbolic": "", "formula_words": ""}, {"id": "1e1777c7-cd83-4836-bcd0-cf22270b236f", "term": "Field Recorder Audio Import", "definition": "Field Recorder Audio Import is a feature in Steinberg's Nuendo and Cubase, used mainly in post-production to locate the original location recordings that match audio events already in a project. It scans folders of Broadcast Wave (BWF) files and reads embedded metadata, such as iXML scene, take, timecode, and channel names, to find matching takes and additional channels, which can be auditioned and imported; polyphonic files are split into separate mono files. The feature is part of Steinberg Media Technologies GmbH software, a Yamaha subsidiary, and relies on the open BWF and iXML metadata standards.", "plain_english": "Field recorders capture sound on set, often on many channels. This feature finds those original files that match clips already in your project. It reads hidden data like scene, take, and timecode to match them. You can then bring in the higher-quality or extra channels.", "purpose_function": "It exists to let dialog editors reunite timeline clips with the full original field recordings, including alternate microphone channels, by matching file metadata.", "practical_application": "A dialog editor points the tool at the sound-report folder, lets it match events by timecode and scene/take, and imports the isolated boom and lavalier channels for editing.", "category": "Media Import", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["Broadcast Wave Format", "iXML", "Timecode", "Conforming", "AAF"], "common_mistakes": ["Expecting matches without valid timecode or metadata in the files; matching depends on it", "Forgetting that polyphonic files are split into separate mono files on import", "Assuming it alters the original files; it imports copies referenced to the events"], "scenario_contexts": ["Reuniting a rough-cut timeline with original production sound for a film", "Pulling isolated lavalier channels for dialog editing", "Conforming location recordings after the picture edit"], "formula_symbolic": "", "formula_words": ""}, {"id": "e9de70dd-3d86-4391-8ec4-eaeb3adb3188", "term": "LoopMash", "definition": "LoopMash is a Steinberg VST instrument that remixes audio loops in real time by slicing them into short segments, by default eighth-note slices, and rearranging them. It analyses each loop for perceptual features such as tempo, rhythm, and timbre, then during playback replaces slices of a master loop with acoustically similar slices from other loaded loops. LoopMash is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "LoopMash is a software instrument that mixes up drum and music loops. It cuts each loop into small slices. As it plays, it swaps slices between loops that sound alike. This lets you make new grooves from loops you already have.", "purpose_function": "It exists as a creative tool to generate new rhythmic variations and mashups from existing loops, keeping a rhythmic pattern while blending sounds from several loops.", "practical_application": "A producer loads several loops into LoopMash, sets a master track, and adjusts similarity and track priority to morph between loops and capture new grooves.", "category": "Virtual Instrument", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["Virtual Studio Technology", "Loop", "VST Sound", "Slice", "Groove Agent"], "common_mistakes": ["Treating it like a simple loop player; it re-sequences slices rather than playing loops straight", "Expecting identical results each pass; slice selection changes as you adjust similarity", "Loading loops at very different tempos and expecting clean results without matching tempo"], "scenario_contexts": ["Creating a new beat from a folder of drum loops", "Adding rhythmic variation to a track during production", "Live-morphing between loops using performance controls"], "formula_symbolic": "", "formula_words": ""}, {"id": "cf29ae89-7e62-4b38-891d-764696f34a52", "term": "TrackVersions", "definition": "TrackVersions is a feature in Steinberg's Cubase and Nuendo that lets you create and manage multiple versions of the events and parts on a single track, with one version active at a time. It works on audio, MIDI, and instrument tracks, plus chord, tempo, and signature tracks, and is used for recording fresh takes, comparing takes and comps, and trying alternate arrangements. TrackVersions is a trademark feature of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "TrackVersions lets one track hold several versions of its recording. Only one version plays at a time. You can switch between them to compare takes or ideas. This keeps alternatives tidy on one track instead of many extra tracks.", "purpose_function": "It exists to let engineers keep and compare alternative takes, edits, or arrangements on one track without cluttering the project with duplicate tracks.", "practical_application": "A technician records a new vocal pass as a fresh TrackVersion, then switches between versions to pick the best one or comp parts together.", "category": "Track Management", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["Comping", "Lanes", "Take", "Digital Audio Workstation", "MIDI"], "common_mistakes": ["Confusing TrackVersions with take lanes; a version holds a whole alternative set of track contents", "Forgetting that only one version is active and audible at a time", "Assuming it works on automation tracks; it does not"], "scenario_contexts": ["Keeping alternate vocal takes on one track", "Trying a different arrangement without deleting the original", "Comparing edit versions of a dialog track"], "formula_symbolic": "", "formula_words": ""}, {"id": "580d8551-8aad-4570-bfff-f5395bb2471a", "term": "VST Connect", "definition": "VST Connect is Steinberg's remote-recording system built into Cubase and Nuendo (also sold as VST Connect Pro and SE) that lets an engineer record a musician in another location over the internet. The engineer runs it within the DAW's Control Room while the performer uses the free VST Connect Performer application, exchanging a cue mix, talkback, and video, and, in the Pro version, a locally recorded HD audio track that is synced back later. VST Connect is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "VST Connect lets a studio record a musician who is far away, over the internet. The engineer works inside Cubase or Nuendo as usual. The performer uses a free app to join the session. They share a headphone mix, talkback, and video, almost like being in the same room.", "purpose_function": "It exists to enable studio-style remote recording sessions over the internet, giving the engineer DAW control and the performer a cue mix and communication.", "practical_application": "An engineer invites a singer to a session, sets up the cue mix and talkback, records the take, and later pulls the performer's high-quality local recording for tight timing.", "category": "Remote Recording", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["VST Connect Performer", "Control Room", "Cue Mix", "Talkback", "Latency"], "common_mistakes": ["Expecting perfectly latency-free monitoring; internet delay is managed, not eliminated", "Forgetting the performer needs the VST Connect Performer app to join", "Relying only on the streamed audio when the HD local recording gives better quality (Pro)"], "scenario_contexts": ["Recording a remote vocalist into a Cubase session", "Directing a session musician in another city", "Capturing an HD performer track for later sync in post"], "formula_symbolic": "", "formula_words": ""}, {"id": "4e76f4d6-974a-4f58-8f5d-baf5a5f19117", "term": "VST Connect Performer", "definition": "VST Connect Performer is Steinberg's free companion application that a remote musician uses to join a VST Connect session hosted in Cubase or Nuendo, without needing their own DAW. It sends the performer's audio and video to the engineer, receives a personalised cue mix and talkback, and, with VST Connect Pro, records a high-definition audio track locally for later synchronisation. VST Connect Performer is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "VST Connect Performer is a free app for the musician joining a remote session. They do not need their own recording software. The app sends their sound and video to the engineer. It also plays back the headphone mix and the engineer's talkback.", "purpose_function": "It exists to let a remote performer take part in a studio session simply, providing their audio and video, a cue mix, and, on Pro, a local HD recording for quality.", "practical_application": "A guest musician installs VST Connect Performer, enters the session key from the engineer, and plays while hearing the cue mix and click over the internet.", "category": "Remote Recording", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["VST Connect", "Cue Mix", "Talkback", "Latency", "Control Room"], "common_mistakes": ["Thinking it is a full DAW; it is a lightweight client for joining sessions", "Skipping the HD local recording option and losing the best-quality take (Pro)", "Assuming any version connects to any engineer version; matching versions are needed"], "scenario_contexts": ["A singer joining an engineer's remote session from home", "A session player recording an HD track to sync later", "Auditioning a remote musician over the internet"], "formula_symbolic": "", "formula_words": ""}, {"id": "dff27fbb-6cfa-4931-a5b4-5f901771ea57", "term": "VST Expression", "definition": "VST Expression is a set of tools in Steinberg's Cubase and Nuendo for managing instrument articulations and dynamics during MIDI editing. Its Expression Maps let you define articulations, such as legato, staccato, or pizzicato, and switch between them from the score, key switches, or controllers, so a project can audition realistic articulation changes on playback. VST Expression is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "Instruments can be played in different ways, like short or smooth notes. VST Expression lets you set up these playing styles for software instruments. You build a map of the styles, then switch between them as the music plays. This makes MIDI parts sound more realistic.", "purpose_function": "It exists to make virtual instruments sound more human by organizing and switching articulations and dynamics from one place, rather than juggling raw key switches by hand.", "practical_application": "A composer builds an Expression Map for a string library, then assigns legato, staccato, and pizzicato to notes so playback uses the right articulation automatically.", "category": "MIDI Expression", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["Expression Map", "VST Note Expression", "Articulation", "MIDI", "Virtual Studio Technology"], "common_mistakes": ["Confusing VST Expression (articulation switching) with VST Note Expression (per-note parameter data)", "Forgetting to match the map's key switches to the actual instrument library", "Assuming every library uses the same articulation names and switches"], "scenario_contexts": ["Setting up articulations for an orchestral mockup", "Switching a string part between legato and staccato", "Auditioning dynamics changes in a MIDI arrangement"], "formula_symbolic": "", "formula_words": ""}, {"id": "22823073-233a-47d9-9608-f557b08ac496", "term": "VST Live", "definition": "VST Live is Steinberg's software application for live stage performance, organising a show into a Setlist of Songs, each built from Parts. It hosts VST instruments and effects in Layers and Stacks, plays back audio, MIDI, video, lyric, chord, and DMX tracks in a built-in live-oriented sequencer, and provides mixing and stage integration. VST Live is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary; it was first released in early 2023.", "plain_english": "VST Live is software for playing music live on stage. You organize your show as a setlist of songs. It plays backing tracks and lets you play software instruments live. It can also show lyrics, run video, and control stage lights. Everything stays in time together.", "purpose_function": "It exists to give performing bands one program to run backing tracks, live instruments, video, lyrics, and lighting in sync, replacing several separate stage tools.", "practical_application": "A performer builds a setlist, loads backing tracks and VST instruments per song, and triggers parts, lyrics, and video from the stage during the show.", "category": "Live Performance Software", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["Virtual Studio Technology", "Setlist", "Backing Track", "MIDI", "DMX"], "common_mistakes": ["Confusing VST Live with Cubase; it is a separate stage-performance program", "Overloading the CPU with live plug-ins and causing dropouts on stage", "Not preparing and testing the full setlist before the show"], "scenario_contexts": ["Running backing tracks and a click for a live band", "Playing software synths live and switching sounds per song", "Displaying lyrics and running video and lighting cues on stage"], "formula_symbolic": "", "formula_words": ""}, {"id": "a210dd52-1f3a-4011-ac10-c277a5fc8dbf", "term": "VST Note Expression", "definition": "VST Note Expression is a feature in Steinberg's Cubase and Nuendo that stores and edits controller data for each individual note, rather than for a whole MIDI channel. Working with VST3 instruments that support it, it lets each note carry its own independent parameter changes, such as pitch, volume, or tuning, edited together with the note as one unit. VST Note Expression is a trademark feature of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "Normally MIDI changes affect every note on a channel at once. Note Expression lets each note have its own changes. So one note can bend or swell while the others stay steady. You edit these changes right on the note itself.", "purpose_function": "It exists to give fine, per-note expressive control that ordinary channel-based MIDI cannot, using VST3 instruments that understand individual note parameters.", "practical_application": "A composer draws a vibrato or volume curve on a single sustained note so it swells on its own, without affecting the other notes in the chord.", "category": "MIDI Expression", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["VST Expression", "MIDI", "MPE", "Virtual Studio Technology", "Controller Data"], "common_mistakes": ["Confusing Note Expression with VST Expression articulation maps", "Expecting it to work on instruments that do not support VST3 note expression", "Assuming channel MIDI CC and per-note data behave the same way"], "scenario_contexts": ["Adding independent vibrato to one note in a chord", "Shaping per-note pitch slides on a lead line", "Editing expressive detail for a realistic solo instrument"], "formula_symbolic": "", "formula_words": ""}, {"id": "a62ead30-c38e-4201-a000-00a1c4dcdbf9", "term": "VST Sound", "definition": "VST Sound is Steinberg's content and file format, the .vstsound container, that bundles tagged audio content such as loops, samples, and presets into a single library file for use in Cubase, Nuendo, and Steinberg instruments. Registered and organised by the Steinberg Library Manager and browsed in MediaBay, it makes factory and add-on content searchable by tags. VST Sound is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "VST Sound is how Steinberg packages its sound content. Loops, samples, and presets are stored in special library files. A tool called the Library Manager installs and organizes them. You then search the sounds by tags inside the software.", "purpose_function": "It exists to distribute and manage large sound libraries as tidy, tagged, searchable packages instead of loose files, making content easy to install and find.", "practical_application": "A technician installs a .vstsound loop set with the Steinberg Library Manager, then finds and previews its content by tag in MediaBay.", "category": "Content Management", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["MediaBay", "Steinberg Library Manager", "Loop", "Preset", "Virtual Studio Technology"], "common_mistakes": ["Moving or deleting .vstsound files by hand instead of using the Library Manager", "Confusing the VST Sound content format with the VST plug-in format", "Assuming content appears without registering the library first"], "scenario_contexts": ["Installing an expansion loop or preset library", "Relocating sound content to another drive with the Library Manager", "Searching factory content by tag in MediaBay"], "formula_symbolic": "", "formula_words": ""}, {"id": "b30c5661-014c-413d-bcb5-939135e99a83", "term": "VST System Link", "definition": "VST System Link is a networking system in Steinberg's Cubase and Nuendo that links several computers using ordinary digital audio hardware and cables, such as ADAT, S/PDIF, or AES/EBU, rather than a computer network. It carries a small sync signal within one audio bit to share sample-accurate transport, timecode, and MIDI between the linked machines. VST System Link is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "VST System Link joins several computers into one system. It uses normal digital audio cables, not a network cable. This keeps all the machines locked tightly in time. You can spread recording and processing across the computers.", "purpose_function": "It exists to combine the power and inputs of multiple computers with sample-accurate sync, using existing digital audio connections instead of dedicated sync hardware.", "practical_application": "An engineer connects two DAW computers by ADAT, enables VST System Link on one bit, and runs extra instruments and tracks on the second machine locked to the first.", "category": "Synchronization", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["ADAT", "S/PDIF", "Word Clock", "Sample Rate", "Digital Audio Workstation"], "common_mistakes": ["Confusing it with an Ethernet or LAN link; it runs over digital audio cables", "Forgetting all machines must share the same sample rate and word clock", "Using the linked audio bit for audio and losing the sync signal"], "scenario_contexts": ["Adding a second computer for more virtual instruments", "Linking a recording and a mixing machine in sample-accurate sync", "Distributing plug-in processing across computers"], "formula_symbolic": "", "formula_words": ""}, {"id": "8992a77f-2d42-43cb-923b-f05b817f9e2a", "term": "VST Transit", "definition": "VST Transit was Steinberg's cloud-based music collaboration service, integrated into Cubase Pro and Artist, that let musicians share and synchronise project tracks over the internet, find collaborators, and message each other. Related tools included VST Transit Join, a plug-in for other DAWs, and VST Transit Go, an iPad app. VST Transit was a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary; Steinberg discontinued the service on 31 August 2023.", "plain_english": "VST Transit was Steinberg's online tool for making music together. Musicians could share and sync their tracks through the cloud. They could also find collaborators and chat. Steinberg shut the service down in 2023.", "purpose_function": "It existed to let musicians in different places collaborate on the same project through the cloud, syncing tracks and communicating, without shipping files by hand.", "practical_application": "Before it closed, a producer uploaded project tracks to VST Transit so a remote collaborator could download them, add parts, and sync changes back.", "category": "Cloud Collaboration", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["VST Transit Go", "Cloud Storage", "Digital Audio Workstation", "VST Connect", "Collaboration"], "common_mistakes": ["Assuming the service still runs; Steinberg discontinued it on 31 August 2023", "Confusing VST Transit (cloud collaboration) with VST Connect (live remote recording)", "Expecting real-time jamming; it synced project data, not live performance"], "scenario_contexts": ["Sharing a song project with a remote co-writer (historically)", "Finding collaborators through the service", "Syncing added tracks back into a shared project"], "formula_symbolic": "", "formula_words": ""}, {"id": "1290de34-e311-49b1-b9ce-d6e56b60cc36", "term": "Virtual Studio Technology", "definition": "Virtual Studio Technology (VST) is Steinberg's software interface standard for connecting audio plug-ins, both virtual instruments (VSTi) and effect processors, to host applications such as DAWs. Introduced in 1996, it defines how a host passes audio, and MIDI, to a plug-in that processes it and returns it; the current generation is VST3. Steinberg Media Technologies GmbH, a Yamaha subsidiary, owns the trademark and publishes the SDK, but VST is a widely adopted cross-industry standard supported by most DAWs and thousands of third-party plug-ins.", "plain_english": "VST stands for Virtual Studio Technology. It is a standard way to add software instruments and effects to recording programs. The program feeds sound to the plug-in, which changes it and sends it back. Steinberg created it, but almost every DAW and plug-in now uses it.", "purpose_function": "It exists to let any compatible plug-in run inside any compatible host, so instruments and effects from many makers can work together in one DAW.", "practical_application": "A technician installs a VST3 synth or effect, and it then appears for loading on tracks inside Cubase or another VST-compatible DAW.", "category": "Plug-in Standard", "difficulty": "intermediate", "achievement_id": "a4311985-4458-4715-a888-8c89de417012", "cross": [], "related_terms": ["VST Instrument", "Audio Stream Input/Output", "Plug-in", "Digital Audio Workstation", "VST3"], "common_mistakes": ["Confusing the VST plug-in standard with the VST Sound content format", "Assuming VST2 and VST3 are interchangeable; VST3 is a different, rewritten standard", "Thinking VST means only instruments; it also covers audio effect plug-ins"], "scenario_contexts": ["Loading a third-party synth into a DAW as a VST instrument", "Adding a VST effect plug-in to a channel insert", "Choosing VST3 versions of plug-ins for current DAW support"], "formula_symbolic": "", "formula_words": ""}, {"id": "7dba2a13-c861-4fb8-b065-626b6169d680", "term": "Spectral Casting", "definition": "Spectral Casting is an Imprint process in Steinberg's SpectraLayers spectral audio editor. It uses the spectral amplitude peaks (the bright spots in the spectrogram) of a chosen source layer to carve the matching frequencies out of the active layer, reducing overlap between the two layers. SpectraLayers is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "Spectral Casting is a tool inside SpectraLayers, an audio editing app. It looks at the loud frequencies in one sound layer. Then it removes those same frequencies from another layer. This helps two overlapping sounds stay out of each other's way.", "purpose_function": "It exists to reduce frequency overlap between two layers by subtracting one layer's spectral peaks from another, which helps clean a mix or separate sounds that share the same frequencies.", "practical_application": "A restoration engineer casts a noise or instrument layer's peaks out of a target layer to cut down bleed where their frequencies collide.", "category": "Spectral Editing", "difficulty": "intermediate", "achievement_id": "ab73f3b5-426f-4585-8a7c-f829e2a03138", "cross": [], "related_terms": ["Spectral Molding", "Imprint", "Spectral editing", "Spectrogram", "Unmix Components"], "common_mistakes": ["Confusing Casting, which carves out frequencies, with Molding, which reshapes them", "Expecting it to separate sources on its own; it needs a prepared source layer to imprint from", "Setting Strength too high and leaving gaps or artifacts in the target layer"], "scenario_contexts": ["Reducing overlap between two instruments that share a frequency range", "Carving a captured noise profile out of a music layer", "Cleaning bleed between layers during a restoration session"], "formula_symbolic": "", "formula_words": ""}, {"id": "5e9e1011-e98f-4867-8ac5-9659b89a3947", "term": "Spectral Molding", "definition": "Spectral Molding is the other Imprint operation in Steinberg's SpectraLayers spectral audio editor. Rather than carving frequencies away, it reshapes the active layer's spectral amplitudes to follow the amplitude peaks of a chosen source layer, blending the two layers' spectral profiles. SpectraLayers is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "Spectral Molding is a tool in SpectraLayers. It takes the frequency shape of one sound layer. Then it presses that shape onto another layer. The second sound starts to match the first one's frequency pattern. Casting removes frequencies, but molding reshapes them.", "purpose_function": "It reshapes one layer using another layer's spectral peaks, mainly for sound design and for blending or matching the tonal character of two layers.", "practical_application": "A sound designer molds one layer's frequency profile onto another to fuse two sounds or transfer a spectral character between them.", "category": "Spectral Editing", "difficulty": "intermediate", "achievement_id": "ab73f3b5-426f-4585-8a7c-f829e2a03138", "cross": [], "related_terms": ["Spectral Casting", "Imprint", "Spectral editing", "Spectrogram", "Unmix Components"], "common_mistakes": ["Confusing Molding, which reshapes amplitudes, with Casting, which carves them out", "Forgetting to select a source layer before applying the imprint", "Using very high Strength and producing unnatural, artifact-heavy results"], "scenario_contexts": ["Blending two layers into a hybrid sound in design work", "Matching the tonal shape of one recording to another", "Transferring spectral character between two layers"], "formula_symbolic": "", "formula_words": ""}, {"id": "a291d8d0-9178-4c3c-afe6-417caaa559fb", "term": "SuperVision", "definition": "SuperVision is Steinberg's modular audio metering and analysis plug-in, supplied with Cubase, Nuendo, and WaveLab. It provides up to nine customizable module slots drawn from categories such as signal/level, spectral, phase, spatial, and waveform analysis, with two processing modes (Maximum Audio Performance and Sample-Accurate Display). SuperVision is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "SuperVision is a metering plug-in from Steinberg. It shows you what your audio is actually doing. You can add up to nine display panels at once. Each panel shows something like level, frequency, phase, or waveform. Engineers use it to check a mix, not just trust their ears.", "purpose_function": "It gives engineers a configurable set of meters and analyzers in one window so they can monitor levels, loudness, frequency balance, phase, and stereo image while they work.", "practical_application": "A mix or mastering engineer loads SuperVision on the master bus and arranges modules such as a loudness meter, spectrum analyzer, and phase scope to verify the mix.", "category": "Metering & Analysis", "difficulty": "intermediate", "achievement_id": "ab73f3b5-426f-4585-8a7c-f829e2a03138", "cross": [], "related_terms": ["Spectrum analyzer", "Loudness meter (LUFS)", "Phase correlation meter", "Vectorscope", "Peak meter", "Waveform display"], "common_mistakes": ["Treating meter readings as a substitute for critical listening", "Confusing the two processing modes, Maximum Audio Performance and Sample-Accurate Display", "Assuming it changes the audio; it only monitors and displays the signal"], "scenario_contexts": ["Checking loudness compliance on a master bus", "Diagnosing phase problems between stereo channels", "Watching the frequency spectrum while mixing"], "formula_symbolic": "", "formula_words": ""}, {"id": "ca0c95fa-7b72-49c3-a52e-9a13ae41d366", "term": "Unmix Components", "definition": "Unmix Components is a SpectraLayers process that automatically separates the selected layer into tonal, transient, and noise components, each placed on its own layer, using machine-learning-based analysis. It can run non-destructively, so the resulting layers sum back to the original, or reconstruct noise that was hidden beneath tonal and transient content. SpectraLayers is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "Unmix Components is a tool in SpectraLayers. It splits one sound into three parts. One part is the steady tones. One part is the sharp hits, like drum attacks. One part is the noise. Each part becomes its own layer you can edit on its own.", "purpose_function": "It exists to break audio into tonal, transient, and noise elements so each can be edited, reduced, or rebalanced separately during restoration or sound design.", "practical_application": "A technician runs Unmix Components to move noise or transients onto their own layer, then attenuates or reshapes just that element without touching the rest.", "category": "Source Separation", "difficulty": "intermediate", "achievement_id": "ab73f3b5-426f-4585-8a7c-f829e2a03138", "cross": [], "related_terms": ["Unmix Song", "Source separation", "Transient", "Noise reduction", "Spectral editing", "Layer"], "common_mistakes": ["Expecting perfect separation; overlapping content can leak between the components", "Leaving Reconstruct Hidden Noise on when a clean non-destructive split is wanted", "Confusing component separation (tonal/transient/noise) with stem separation by instrument"], "scenario_contexts": ["Isolating broadband noise onto its own layer for reduction", "Separating transients to reshape a recording's attack", "Splitting out tonal content for pitch or harmonic editing"], "formula_symbolic": "", "formula_words": ""}, {"id": "84a30425-59f6-4ee1-9024-b42638980825", "term": "Unmix Song", "definition": "Unmix Song is a SpectraLayers process that separates a mixed music recording into instrument stems, such as Vocals, Drums, Bass, Guitar, Piano, Sax & Brass, and Other, using machine-learning source separation. Quality presets (for example Fast, Balanced, and High) trade processing time against separation accuracy. SpectraLayers is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "Unmix Song is a tool in SpectraLayers. It takes a finished song and splits it into parts. You can pull out the vocals, drums, bass, and more. Each part becomes its own track. Faster settings are quicker, and higher settings sound cleaner but take longer.", "purpose_function": "It exists to extract individual instrument and vocal stems from a stereo mix when the original multitrack is not available, for remixing, restoration, or teaching.", "practical_application": "An engineer runs Unmix Song on a stereo master to pull out a vocal stem for a remix or to remove an instrument from a recording.", "category": "Source Separation", "difficulty": "intermediate", "achievement_id": "ab73f3b5-426f-4585-8a7c-f829e2a03138", "cross": [], "related_terms": ["Unmix Components", "Stem", "Source separation", "Vocal isolation", "Spectral editing", "SpectraLayers"], "common_mistakes": ["Expecting flawless stems; artifacts and bleed remain, especially on dense mixes", "Confusing Unmix Song (instrument stems) with Unmix Components (tonal/transient/noise)", "Using the fastest preset, then blaming the tool for low quality"], "scenario_contexts": ["Extracting a vocal stem from a stereo mix for a remix", "Removing an instrument from a recording where no multitrack exists", "Making practice or backing tracks by isolating parts"], "formula_symbolic": "", "formula_words": ""}, {"id": "0f5e8e3f-20d9-49a3-bad0-6806c1d4f9ad", "term": "Voice Enhance", "definition": "Voice Enhance is a SpectraLayers restoration module (introduced in version 12) that reconstructs a high-quality voice recording from poorly recorded material using generative resynthesis, addressing damage such as lost high frequencies, clipping, noise, and reverb together. Its controls include a DeNoise First option and an Enhancement Ratio; because it is a generative process, it can produce incorrect voice reconstruction from severely damaged audio. SpectraLayers is a trademark of Steinberg Media Technologies GmbH, a Yamaha subsidiary.", "plain_english": "Voice Enhance is a SpectraLayers tool for fixing bad voice recordings. It rebuilds the voice instead of just filtering it. It can fix missing high tones, clipping, noise, and echo at the same time. Because it rebuilds the sound, it can get the voice wrong on very damaged clips.", "purpose_function": "It exists to recover clear, natural-sounding speech from poor recordings by resynthesizing the voice rather than only subtracting the problems.", "practical_application": "A dialogue editor runs Voice Enhance on a noisy, band-limited field recording to recover clearer speech, then checks the output for reconstruction errors.", "category": "Voice Restoration", "difficulty": "intermediate", "achievement_id": "ab73f3b5-426f-4585-8a7c-f829e2a03138", "cross": [], "related_terms": ["Voice DeNoise", "Voice DeReverb", "De-clipping", "Speech intelligibility", "Resynthesis", "Noise reduction"], "common_mistakes": ["Trusting the output blindly; generative reconstruction can invent wrong content on badly damaged audio", "Pushing the Enhancement Ratio too high and adding unnatural artifacts", "Assuming it filters like a traditional de-noiser; it resynthesizes the voice"], "scenario_contexts": ["Recovering intelligible dialogue from a noisy phone or field recording", "Restoring speech that lost high frequencies through low-bitrate compression", "Cleaning archival interview recordings for broadcast"], "formula_symbolic": "", "formula_words": ""}, {"id": "9d39d71a-fd9f-4d77-9a4a-4106096ec0f6", "term": "ANTI 1992 High Gain Amp", "definition": "A Universal Audio, Inc. UAFX guitar-effects pedal that emulates a high-gain 120-watt American tube amplifier head of the early 1990s associated with metal and hard rock, together with matched speaker-cabinet and microphone modeling. Universal Audio does not license or name the original amplifier; the pedal recreates that circuit's tone rather than being a UA-designed amp. It adds a noise gate, an overdrive/boost stage, and six modeled mic-and-cabinet combinations.", "plain_english": "This is a guitar pedal made by Universal Audio. It copies the sound of a famous 1990s tube amp used in metal. It also fakes the speaker cabinet and the microphone. You get that heavy tone without hauling a loud amp around.", "purpose_function": "It captures a specific heavy amp-and-cabinet sound for recording or live use without miking a loud tube amp. The modeling recreates the amplifier's gain and tone in the digital domain.", "practical_application": "A technician runs a guitar into the pedal and takes a direct output to an interface or PA, picking a mic/cab preset instead of setting up a real amp and microphone.", "category": "Guitar amp emulation", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UAFX", "Lion 68 Super Lead Amp", "Dream 65 Reverb Amplifier", "OX Amp Top Box", "OX Dynamic Speaker Modeling"], "common_mistakes": ["Assuming Universal Audio designed the amplifier itself; the pedal models another maker's early-1990s tube head", "Thinking it is a UAD plug-in; ANTI 1992 ships only as a hardware UAFX pedal", "Leaving the built-in cabinet and mic modeling engaged when feeding a real guitar amp, which double-processes the tone"], "scenario_contexts": ["Recording a high-gain metal rhythm part direct with no loud amp in the room", "Sending the pedal's cab and mic emulation to a PA for a live show", "Bypassing the cabinet modeling to drive the front end of a real tube amp"], "formula_symbolic": "", "formula_words": ""}, {"id": "05012c83-3e28-4b67-87bc-eba0cbac38d0", "term": "API Summing Extension", "definition": "A Universal Audio, Inc. LUNA Extension that emulates the summing bus of a large-format API mixing console, whose sound comes from API's 2520 discrete op-amps feeding output transformers. API (Automated Processes, Inc.) made the original console circuitry; the Extension models that summing amplifier, not a UA-invented design. It adds the console's coloration to LUNA's mix bus with per-channel bypass, headroom, and trim controls.", "plain_english": "This add-on for Universal Audio's LUNA software copies how an old API mixing desk blends tracks. Real analog desks add a bit of tone and punch when they mix signals. The Extension recreates that API flavor inside the computer. API, not Universal Audio, designed the original desk.", "purpose_function": "It recreates the subtle tone and 'glue' that an API console's summing circuit adds when many tracks combine into one mix. It exists so an in-the-box mix can take on that analog console character.", "practical_application": "An engineer enables the Extension on LUNA's mix bus to give a fully digital session the punchy, forward coloration of an API desk.", "category": "Console emulation", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Neve Summing Extension", "API Vision Console Emulation", "UAD", "UAD Console", "Ampex ATR-102 Tape Extension"], "common_mistakes": ["Believing Universal Audio invented the summing sound; it models API's 2520 op-amp console circuit", "Expecting a loudness boost; summing emulation adds coloration, not level", "Confusing it with the API Vision channel-strip plug-in, which models preamp and EQ modules rather than the summing bus"], "scenario_contexts": ["Mixing entirely in LUNA and wanting an API-style console bus tone", "A/B comparing API summing versus Neve summing on the same mix", "Adding gentle analog character to a modern pop mix bus"], "formula_symbolic": "", "formula_words": ""}, {"id": "156eb2ae-5ad5-4360-aa76-7d3f9b50b28e", "term": "API Vision Console Emulation", "definition": "A Universal Audio, Inc. software emulation of the channel modules of API's Vision large-format recording console, made by API (Automated Processes, Inc.). It models the 212L preamp, the 550L four-band parametric and 560L ten-band graphic equalizers, the 225L compressor, and the 235L gate/expander. It reproduces API's discrete-circuit channel-strip sound rather than being a UA-original design.", "plain_english": "This copies the channel strip of an API recording console in software. It includes the preamp, the equalizers, the compressor, and the gate from that desk. You get the API sound on a track without owning the console. API built the real hardware, not Universal Audio.", "purpose_function": "It gives engineers API's console preamp, EQ, and dynamics tone on any track inside a DAW. It exists to bring a full analog channel strip's character to in-the-box mixing.", "practical_application": "An engineer inserts the emulation on a drum or vocal track to shape tone with the 550L EQ and control dynamics with the 225L compressor, mirroring an API console channel.", "category": "Console emulation", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["API Summing Extension", "Neve Summing Extension", "UAD", "UAD Powered Plug-Ins", "UADx"], "common_mistakes": ["Treating the EQ curves as generic; the 550L and 560L are specific API designs with their proportional-Q behavior", "Assuming it models the summing bus; this emulates the channel modules, while the API Summing Extension models the bus", "Thinking Universal Audio created the circuit; it emulates API hardware"], "scenario_contexts": ["Adding API-style punch and EQ to individual drum tracks", "Building an all-API mix chain in software", "Teaching students the sound of a Vision console channel strip"], "formula_symbolic": "", "formula_words": ""}, {"id": "bf37db37-b6ce-4fa8-adda-b43978ef4c31", "term": "Accelerated Realtime Monitoring", "definition": "Accelerated Realtime Monitoring (ARM) is a Universal Audio, Inc. feature in the LUNA recording system that combines Apollo interface hardware, UAD DSP, and software to give near-zero-latency monitoring while recording through UAD plug-ins. When ARM is active on a track, that track's monitoring buffer drops to near zero while the project can keep a larger buffer for mixing. Only UAD-format plug-ins process on ARM audio tracks; other plug-in formats are bypassed during ARM monitoring.", "plain_english": "This is a Universal Audio feature that removes the delay you hear while recording. Normally the computer adds a lag when effects are on your input. ARM uses the Apollo interface's own chips to process the sound instantly. So a singer hears themselves with effects and almost no delay.", "purpose_function": "It lets performers monitor themselves through UAD effects in real time without the distracting delay a computer normally adds. It exists so tracking and mixing can use different buffer settings at once.", "practical_application": "An engineer arms a vocal track with ARM so the singer hears a UAD compressor and reverb live with no perceptible latency, while the rest of the session runs a high buffer.", "category": "Monitoring technology", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Universal Audio Digital", "UAD", "UAD Console", "UAD Powered Plug-Ins", "UADx"], "common_mistakes": ["Expecting all plug-in formats to run on an ARM track; non-UAD formats are bypassed during ARM monitoring", "Assuming ARM works without an Apollo interface; it depends on Apollo DSP hardware", "Thinking ARM channel count is unlimited; it is capped by the specific Apollo model"], "scenario_contexts": ["Tracking a vocal through UAD effects with no monitoring delay", "Recording a band while keeping a high mixing buffer for the rest of the session", "Using ARM aux buses for real-time reverb during overdubs"], "formula_symbolic": "", "formula_words": ""}, {"id": "c566d599-9fca-49a5-a7ee-c0b9d9eaaee7", "term": "Ampex ATR-102 Tape Extension", "definition": "A Universal Audio, Inc. emulation of the Ampex ATR-102, a professional two-track (mastering) tape machine made by the Ampex Corporation, offered as a plug-in and as a LUNA Extension. It models the machine's full signal path, including transformers, amplifiers, and the repro, sync, and input stages, with selectable tape speeds, tape formulas, and emphasis EQ. The 'Extension' form integrates the ATR-102 model directly into the LUNA recording system.", "plain_english": "This copies a classic Ampex two-track tape machine in software. Mix engineers used to run finished mixes to that tape for warmth and glue. The plug-in recreates the tape saturation and tone. Ampex built the original machine, not Universal Audio.", "purpose_function": "It adds analog tape saturation, low-end weight, and cohesion to a mix or master, recreating how engineers printed mixes to an Ampex ATR-102. It exists to bring that mastering-tape character to digital work.", "practical_application": "A mastering engineer places the ATR-102 on the mix bus, picks a tape speed and formula, and drives it for gentle glue and harmonic warmth on the final master.", "category": "Tape machine emulation", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Oxide Tape Extension", "Studer A800 Tape Extension", "API Summing Extension", "UAD", "UADx"], "common_mistakes": ["Thinking Universal Audio made the tape machine; the ATR-102 is an Ampex product being modeled", "Assuming all tape speeds and formulas sound alike; each changes saturation and frequency response", "Overdriving the tape stage and losing transients when only subtle glue was wanted"], "scenario_contexts": ["Printing a stereo mix through the ATR-102 model for tape glue", "Mastering a track with tape saturation instead of a limiter alone", "Comparing 15 vs 30 IPS tape speed for low-end response"], "formula_symbolic": "", "formula_words": ""}, {"id": "1bad4f7e-5409-494e-ae95-7c45a1a068c7", "term": "Astra Modulation Machine", "definition": "A Universal Audio, Inc. UAFX guitar-effects pedal that emulates three vintage modulation effects: a bucket-brigade chorus/vibrato modeled on a mid-1970s Japanese stompbox, a flanger/doubler modeled on a late-1970s studio rack unit, and an optical tube tremolo modeled on a 1960s American amplifier. Each effect recreates specific hardware behavior rather than being a UA-original circuit. It uses dual stereo processing engines and supports MIDI and app control.", "plain_english": "This is a guitar pedal that holds three classic modulation effects. It has a warm chorus, a swooshing flanger, and an amp-style tremolo. Each one copies a different vintage unit. You get several wobble and swirl sounds from one box.", "purpose_function": "It gives guitarists faithful recreations of classic chorus, flanger, and tremolo hardware in one pedal. It exists to cover common modulation textures without owning several vintage units.", "practical_application": "A guitarist selects the Brigade chorus for a lush clean tone or the tube tremolo for a rhythmic pulse, dialing the depth and rate from the pedal or the UAFX Control app.", "category": "Effects modeling", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UAFX", "Del-Verb Ambience Companion", "Galaxy 74 Tape Echo & Reverb", "Golden Reverberator", "UAFX Dual-Engine Processing"], "common_mistakes": ["Assuming Universal Audio designed these effects; each models another maker's vintage unit", "Thinking it is a plug-in; Astra is a hardware UAFX pedal", "Setting modulation depth too high, which can make pitch wobble sound seasick"], "scenario_contexts": ["Adding vintage chorus to a clean guitar for a 1980s feel", "Using the tube tremolo for a surf or blues rhythm part", "Blending flanger and reverb for an ambient soundscape"], "formula_symbolic": "", "formula_words": ""}, {"id": "60869f01-5110-4a57-aa74-81c5e36d51a0", "term": "Del-Verb Ambience Companion", "definition": "A Universal Audio, Inc. UAFX guitar-effects pedal that combines three delay and three reverb effects modeled on vintage hardware. Its delays emulate a 1970s tape echo, a bucket-brigade analog delay, and a modern digital delay; its reverbs emulate a 1960s tube-amp spring, a studio plate, and a 1980s digital reverb. Dual stereo engines let a delay and a reverb run at once; the effects model existing hardware rather than being UA-original circuits.", "plain_english": "This guitar pedal pairs echo and reverb in one box. It has three delay types and three reverb types, each copying a classic unit. You can run an echo and a reverb together for depth. It is made as a companion to add space to your tone.", "purpose_function": "It provides delay and reverb 'ambience' from one pedal so a player can add space and depth without two separate boxes. It exists to cover time-based effects compactly.", "practical_application": "A guitarist pairs the tape echo with the plate reverb to place a lead line in a large, warm space during a live set or recording.", "category": "Effects modeling", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UAFX", "Golden Reverberator", "Galaxy 74 Tape Echo & Reverb", "Starlight Echo Station", "UAFX Dual-Engine Processing"], "common_mistakes": ["Assuming Universal Audio invented these delays and reverbs; each models specific vintage gear", "Piling on both long delay and long reverb, which can muddy the sound", "Thinking it is a plug-in; Del-Verb is a hardware UAFX pedal"], "scenario_contexts": ["Adding echo and reverb to a lead guitar in one pedal step", "Creating ambient washes with tape delay into plate reverb", "Using spring reverb and slapback delay for a rockabilly tone"], "formula_symbolic": "", "formula_words": ""}, {"id": "8c59d9d2-b1a2-42bb-a3e1-cc6e19c8e610", "term": "Dream 65 Reverb Amplifier", "definition": "A Universal Audio, Inc. UAFX guitar-effects pedal that emulates a mid-1960s American tube combo amplifier of the Fender '65 Deluxe Reverb type, including its tube-driven spring reverb and vibrato. It also provides speaker-cabinet and microphone modeling derived from UA's OX Amp Top Box. Universal Audio does not license the original brand name; the pedal recreates that amp's circuit tone rather than being a UA-designed amplifier.", "plain_english": "This guitar pedal copies a famous 1960s American combo amp. That amp is known for its clean tone, spring reverb, and vibrato wobble. The pedal also fakes the speaker and microphone. You get that classic clean sound without a real amp.", "purpose_function": "It captures a mid-1960s clean tube-amp tone with its built-in reverb and vibrato for direct recording or live use. The cabinet and mic modeling let it be used without a real amp.", "practical_application": "A player takes a direct feed from the pedal to an interface for a clean, reverb-rich rhythm part, or bypasses the cab modeling to run into a real amp.", "category": "Guitar amp emulation", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UAFX", "Lion 68 Super Lead Amp", "ANTI 1992 High Gain Amp", "OX Amp Top Box", "OX Dynamic Speaker Modeling"], "common_mistakes": ["Thinking Universal Audio built the amplifier; it models a Fender-style 1960s combo", "Leaving cabinet/mic modeling on when feeding a real amp, which double-processes the signal", "Assuming Dream 65 is pedal-only; the same emulation also ships as a native UADx/UAD plug-in"], "scenario_contexts": ["Recording a clean, spring-reverb rhythm guitar direct", "Getting classic vibrato tones for surf or blues", "Running the pedal into a PA with cab modeling at a small gig"], "formula_symbolic": "", "formula_words": ""}, {"id": "e4c6db4f-4e43-4145-9b09-470f65609e7c", "term": "Electra 88", "definition": "Electra 88 (Vintage Keyboard Studio) is a Universal Audio, Inc. native software instrument built from deep sampling of a 1974 Fender Rhodes Eighty-Eight Suitcase Mark I electric piano. It pairs the sampled electric piano with a modeled studio of vintage microphones, amplifiers, effects, and dynamics processing. It runs as a plug-in in any DAW and needs no UA hardware.", "plain_english": "This is a software electric piano from Universal Audio. It is built from careful recordings of a real 1974 Fender Rhodes. It also adds vintage amps, mics, and effects around the piano. You play it with a MIDI keyboard in your recording software.", "purpose_function": "It gives producers a detailed vintage electric-piano sound with a built-in effects studio, so a Rhodes tone can be recorded without the real instrument. It exists to deliver a ready-to-mix keyboard sound.", "practical_application": "A producer loads Electra 88 on a MIDI track, picks a preset, and shapes the Rhodes tone with the built-in amp, tremolo, and reverb for a soul or R&B part.", "category": "Virtual instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Ravel", "Opal Morphing Synthesizer", "PolyMAX", "Waterfall B3", "UADx"], "common_mistakes": ["Assuming it is sampled from many pianos; it is deep-sampled from one hand-picked Fender Rhodes Mark I", "Thinking it needs UA hardware; it is a native plug-in", "Ignoring the built-in effects studio and adding redundant outboard reverb"], "scenario_contexts": ["Recording a vintage Rhodes part for a soul or pop track", "Using the built-in amp and tremolo for a lo-fi keyboard texture", "Layering electric piano under a vocal without a physical instrument"], "formula_symbolic": "", "formula_words": ""}, {"id": "930a3455-edaa-4caf-8705-893e09909e29", "term": "Galaxy 74 Tape Echo & Reverb", "definition": "A Universal Audio, Inc. UAFX guitar-effects pedal that emulates a mid-1970s Japanese multi-head tape echo and spring reverb of the Roland RE-201 Space Echo type. It models the machine's multi-head tape delay with wow, flutter, and saturation, its spring reverb, and its preamp coloration. The pedal recreates that hardware's behavior rather than being a UA-original design.", "plain_english": "This guitar pedal copies a 1970s tape echo machine with spring reverb. Real tape echoes had a warm, slightly unstable repeat sound. The pedal recreates the wobble, saturation, and reverb. You get vintage echo without a fragile tape machine.", "purpose_function": "It provides warm, organic multi-head tape echo and spring reverb in a reliable pedal, recreating a classic Space Echo unit. It exists so players can get that sound without maintaining real tape.", "practical_application": "A guitarist uses the pedal's tape delay for rhythmic repeats and adds spring reverb for dub, ambient, or surf textures, adjusting head selection and feedback for self-oscillation.", "category": "Effects modeling", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UAFX", "Starlight Echo Station", "Del-Verb Ambience Companion", "Golden Reverberator", "UAFX Dual-Engine Processing"], "common_mistakes": ["Thinking Universal Audio made the original unit; it models a Roland-style tape echo", "Expecting perfectly clean repeats; tape echo intentionally adds wow, flutter, and saturation", "Assuming it is a plug-in; Galaxy 74 is a hardware UAFX pedal"], "scenario_contexts": ["Adding warm tape repeats to a lead guitar line", "Creating dub-style feedback swells live", "Pairing tape echo with spring reverb for ambient textures"], "formula_symbolic": "", "formula_words": ""}, {"id": "b4f09e32-07ae-416f-9a21-c80405aa5bc8", "term": "Golden Reverberator", "definition": "A Universal Audio, Inc. UAFX guitar-effects pedal that emulates three classic reverb types: a 1960s American tube-amp spring reverb, a studio plate reverb of the EMT 140 type, and a late-1970s digital hall reverb of the Lexicon 224 type. Each engine models specific hardware behavior rather than being a UA-original algorithm. Dual stereo engines allow layered, three-dimensional reverb.", "plain_english": "This guitar pedal holds three kinds of reverb. It has a spring reverb, a studio plate reverb, and a vintage digital hall. Each one copies a famous piece of gear. You pick the space you want and add depth to your tone.", "purpose_function": "It gives guitarists three distinct, high-quality reverbs in one pedal, from amp spring to lush digital hall. It exists to cover the main reverb flavors without several units.", "practical_application": "A player selects the spring for a vintage amp feel, the plate for a smooth sheen on a lead, or the hall for ambient wash, blending trails and modulation to taste.", "category": "Effects modeling", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UAFX", "Del-Verb Ambience Companion", "Galaxy 74 Tape Echo & Reverb", "Starlight Echo Station", "UAFX Dual-Engine Processing"], "common_mistakes": ["Assuming Universal Audio designed these reverbs; they model spring, EMT-style plate, and Lexicon-style hall hardware", "Using very long reverb tails that wash out fast passages", "Thinking it is a plug-in; Golden Reverberator is a hardware UAFX pedal"], "scenario_contexts": ["Adding spring reverb to a clean amp tone", "Using plate reverb for a smooth lead guitar", "Creating ambient pads with the digital hall setting"], "formula_symbolic": "", "formula_words": ""}, {"id": "f05b78a3-b284-4874-b0c5-a55d9289aee1", "term": "IsoSphere", "definition": "IsoSphere is a Universal Audio, Inc. patented feature within the UA Sphere modeling-microphone plug-ins that optimizes the modeled microphone for use with acoustic isolation (reflection) filters such as the sE Reflexion Filter, Aston Halo, or Kaotica Eyeball. It adjusts the modeled polar pattern for greater rear and off-axis rejection, applies a hypercardioid pattern at low frequencies, and corrects frequency response to counteract the filter's coloration. It is unavailable in 180-degree plug-in versions and cannot run at the same time as Off-Axis Correction.", "plain_english": "IsoSphere is a setting in Universal Audio's Sphere microphone software. It helps when you record with a foam or panel shield around the mic. It makes the mic reject more room sound and fixes the tone the shield changes. The result is a cleaner, drier recording in a bad-sounding room.", "purpose_function": "It exists so singers and instrumentalists can get cleaner, drier recordings in untreated rooms by pairing the Sphere mic with an isolation filter. It compensates for the tonal changes those filters cause.", "practical_application": "A home-studio engineer records vocals with a Sphere mic inside a reflection filter and turns on IsoSphere to tighten rejection and correct the tone.", "category": "Microphone modeling", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Sphere Modeling Microphone", "Sphere Mic Collection", "Sphere Dual Mode", "Sphere Stereo Mode", "Off-Axis Correction"], "common_mistakes": ["Expecting IsoSphere to remove all room sound; it improves rejection but does not replace a treated room", "Trying to enable it together with Off-Axis Correction, which is not allowed", "Assuming it works on any mic; it requires a UA Sphere modeling microphone"], "scenario_contexts": ["Recording vocals in an untreated bedroom with a reflection filter", "Reducing room bleed on a voiceover take", "Correcting the tonal dip an isolation shield adds to a Sphere mic"], "formula_symbolic": "", "formula_words": ""}, {"id": "b90c36a9-39d8-498a-b1f0-3ee9e9ee15ec", "term": "Lion 68 Super Lead Amp", "definition": "A Universal Audio, Inc. UAFX guitar-effects pedal that emulates late-1960s British 100-watt 'plexi'-style tube amplifiers of the Marshall Super Lead and Super Bass type, plus a hot-rodded 'Brown' variant. It models the amp's dual inputs, tone stack, and gain structure along with speaker-cabinet and microphone options. Universal Audio does not license the original brand name; the pedal recreates that circuit's tone rather than being a UA-designed amplifier.", "plain_english": "This guitar pedal copies famous 1960s British 100-watt tube amps. Those 'plexi' amps gave classic rock its roar. The pedal also fakes the speaker and mic. You get that big British crunch without a wall of amps.", "purpose_function": "It captures the crunch and roar of a British plexi amp for recording or live use, with cabinet and mic modeling built in. It exists to deliver that classic rock tone without a loud stack.", "practical_application": "A guitarist runs into the pedal, picks the Super Lead model and a mic/cab, and takes a direct output for a driven classic-rock rhythm or lead tone.", "category": "Guitar amp emulation", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UAFX", "Dream 65 Reverb Amplifier", "ANTI 1992 High Gain Amp", "OX Amp Top Box", "OX Dynamic Speaker Modeling"], "common_mistakes": ["Thinking Universal Audio built the amplifier; it models a Marshall-style British plexi", "Leaving cabinet/mic modeling on when feeding a real amp, which double-processes the tone", "Assuming Lion 68 is pedal-only; the same emulation also ships as a native UADx/UAD plug-in"], "scenario_contexts": ["Recording a classic-rock rhythm guitar direct", "Getting plexi lead tones without stage volume", "Driving a real power amp using the pedal's preamp with cab modeling off"], "formula_symbolic": "", "formula_words": ""}, {"id": "821605b8-3c97-47d2-abb9-8893dc7be763", "term": "Max Preamp & Dual Compressor", "definition": "A Universal Audio, Inc. UAFX guitar-effects pedal that combines a modeled UA 610 tube preamp with EQ and three modeled compressors: the UA 1176 FET compressor, the Teletronix LA-2A optical limiter, and a classic Dyna Comp-style pedal compressor. Two compressors can be stacked at once. The models recreate specific studio and pedal circuits rather than being UA-original designs.", "plain_english": "This guitar pedal gives you a studio preamp and two compressors in one box. It copies famous studio compressors like the 1176 and LA-2A, plus a classic pedal squeeze. You can run two at once to shape your dynamics. It adds warmth and control to your tone.", "purpose_function": "It brings studio-grade preamp coloration and compression to a pedalboard, letting players stack two compressor styles. It exists to add warmth, sustain, and level control to guitar or other instruments.", "practical_application": "A guitarist stacks the LA-2A for smooth leveling and the Dyna Comp for pedal snap, then uses the 610 preamp to add tube warmth before the amp or interface.", "category": "Effects modeling", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UAFX", "OX Amp Top Box", "Max Preamp", "ANTI 1992 High Gain Amp", "UAFX Dual-Engine Processing"], "common_mistakes": ["Assuming Universal Audio invented these compressors; each models specific studio or pedal hardware", "Stacking two heavy compressors and squashing the tone lifeless", "Thinking it is a plug-in; Max is a hardware UAFX pedal"], "scenario_contexts": ["Adding studio-style compression to a clean guitar", "Warming a direct signal with the 610 preamp model", "Stacking two compressors for country chicken-picking snap"], "formula_symbolic": "", "formula_words": ""}, {"id": "86379abf-025b-4b91-b6bc-1a89b7281572", "term": "Neve Summing Extension", "definition": "A Universal Audio, Inc. LUNA Extension that emulates the summing bus of a 1970s Neve mixing console, whose sound derives from Marinair transformers and the desk's amplifier circuitry. Neve made the original console; the Extension models that summing amplifier's coloration rather than being a UA-invented design. It applies the console's character to LUNA's mix bus with per-channel controls.", "plain_english": "This add-on for Universal Audio's LUNA software copies how a classic Neve mixing desk blends tracks. Real Neve desks add a rich, smooth tone when they combine signals. The Extension recreates that Neve flavor in the computer. Neve, not Universal Audio, designed the console.", "purpose_function": "It recreates the rich, warm 'glue' a Neve console adds when tracks combine into a mix. It exists so an in-the-box mix can take on that analog Neve character.", "practical_application": "An engineer enables the Extension on LUNA's mix bus to give a digital session the smooth, luxuriant coloration of a vintage Neve desk.", "category": "Console emulation", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["API Summing Extension", "API Vision Console Emulation", "UAD", "UAD Console", "Studer A800 Tape Extension"], "common_mistakes": ["Believing Universal Audio invented the summing sound; it models a Neve console circuit", "Expecting a level increase; summing emulation adds tone, not loudness", "Confusing it with a Neve channel-strip plug-in, which models preamp and EQ rather than the summing bus"], "scenario_contexts": ["Mixing in LUNA and wanting a Neve-style console bus tone", "A/B comparing Neve versus API summing on a mix", "Adding warm analog glue to a rock mix bus"], "formula_symbolic": "", "formula_words": ""}, {"id": "f73796f7-4dbd-4083-b074-5ee84eda95f1", "term": "OX Amp Top Box", "definition": "The OX Amp Top Box is a Universal Audio, Inc. hardware reactive load box and attenuator with built-in speaker-cabinet, microphone, room, and studio-effects modeling for tube guitar amplifiers. It connects to an amp's speaker output, presents a reactive load at selectable 4, 8, or 16 ohms, and lets the amp be played or recorded at any volume. It outputs modeled tones over balanced analog and S/PDIF digital connections and is controlled by hardware knobs or a companion app.", "plain_english": "The OX is a Universal Audio box that sits between a tube amp and its speaker. It safely soaks up the amp's power so you can play loud amps quietly. It also fakes the speaker cabinet, microphones, and room. You record great amp tones without a loud room or real mics.", "purpose_function": "It lets guitarists crank a tube amp for its natural tone while controlling loudness, and it captures a mic'd cabinet sound electronically. It exists to make loud-amp recording practical and quiet.", "practical_application": "An engineer connects the OX to a cranked tube amp's speaker output, selects a Rig with cabinet and mic modeling, and records a full amp tone silently to the interface.", "category": "Amp modeling", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["OX Rig", "OX Dynamic Speaker Modeling", "Dream 65 Reverb Amplifier", "Lion 68 Super Lead Amp", "ANTI 1992 High Gain Amp"], "common_mistakes": ["UNSAFE: connecting the OX to the wrong impedance or to a solid-state/line output can damage the amp or the OX; match the amp's speaker impedance and use the speaker output", "Thinking it is only an attenuator; it also provides speaker, mic, and effects modeling", "Assuming it needs no amp; the OX processes a real amp's output rather than generating tone alone"], "scenario_contexts": ["Recording a cranked tube amp silently in a home studio", "Playing a loud amp at low volume for practice", "Sending a modeled cabinet tone to front-of-house at a quiet-stage gig"], "formula_symbolic": "", "formula_words": ""}, {"id": "f4cc85a4-f84a-435e-a5f8-43b10c460d1b", "term": "OX Dynamic Speaker Modeling", "definition": "OX Dynamic Speaker Modeling is the Universal Audio, Inc. speaker-emulation technology used in the OX Amp Top Box and related UAFX products. Unlike a static impulse response, it models how a real speaker behaves dynamically, recreating speaker breakup, drive, and cone cry, along with harmonics and complexity that appear only at certain frequencies and volume levels. It aims to reproduce a loudspeaker's level- and frequency-dependent response rather than a single fixed snapshot.", "plain_english": "This is Universal Audio's way of faking a guitar speaker in software. A real speaker changes its sound as you push it louder. A plain sample cannot capture that, but this model does. It recreates the growl and breakup that come with volume.", "purpose_function": "It reproduces the way a guitar speaker's tone shifts with loudness and drive, which a fixed impulse response cannot. It exists to make modeled cabinets respond dynamically like real ones.", "practical_application": "A technician chooses a modeled cabinet in an OX or UAFX product and hears it break up and 'cry' as the amp is pushed harder, matching a real mic'd speaker.", "category": "Speaker modeling", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["OX Amp Top Box", "OX Rig", "Impulse Response", "Dream 65 Reverb Amplifier", "Lion 68 Super Lead Amp"], "common_mistakes": ["Assuming it is the same as a static impulse response; it models level- and frequency-dependent speaker behavior", "Expecting identical tone at all volumes; the model changes with drive like a real speaker", "Thinking it works without an amp signal; it shapes the sound of an amplified input"], "scenario_contexts": ["Capturing realistic speaker breakup when recording direct", "Comparing modeled cabinet response at low versus high drive", "Getting cone-cry character on a lead tone without a loud room"], "formula_symbolic": "", "formula_words": ""}, {"id": "2a5846f5-3583-4795-b0c5-c60908c319dd", "term": "OX Rig", "definition": "In the Universal Audio, Inc. OX Amp Top Box system, a Rig is one complete guitar tone that stores the settings of all of the OX's sonic controls. It includes the selected speaker cabinet, microphone choice and placement, room ambience, and the chain of studio effects such as EQ, compression, delay, and reverb. Up to six favorite Rigs can be assigned to the front-panel RIG knob for recall without the companion app.", "plain_english": "A Rig is a full saved guitar tone in the OX box. It holds the speaker, the microphones, the room, and the effects all at once. You can store your favorites and switch between them fast. Think of it as one complete preset for your sound.", "purpose_function": "It bundles every OX tone setting into one recallable preset so a player can switch complete sounds instantly. It exists to make full-tone recall fast, even in standalone use.", "practical_application": "A guitarist builds a clean Rig and a lead Rig, assigns them to the RIG knob, and switches between full cabinet-and-effects tones during a session or set.", "category": "Amp modeling", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["OX Amp Top Box", "OX Dynamic Speaker Modeling", "Dream 65 Reverb Amplifier", "Lion 68 Super Lead Amp", "UAFX Control"], "common_mistakes": ["Thinking a Rig is only a speaker cabinet; it stores mic, room, and effects settings too", "Assuming Rigs need the app to recall; six can live on the front-panel RIG knob", "Forgetting to save edits, so a favorite tone is lost when switching Rigs"], "scenario_contexts": ["Storing separate clean and lead tones for quick switching", "Recalling a full mic'd-cabinet sound without the app", "Sharing a complete tone preset between sessions"], "formula_symbolic": "", "formula_words": ""}, {"id": "0d54b05f-a7a5-4a45-9fde-52623ef6868c", "term": "Opal Morphing Synthesizer", "definition": "Opal Morphing Synthesizer is a Universal Audio, Inc. native software instrument that combines analog-style and wavetable synthesis with morphing controls. It features morphing filters, oscillators, LFOs, and noise sources, plus onboard effects such as spring reverb, tape delay, modulation, and 1176-style compression. It runs as a plug-in in a DAW and needs no UA hardware.", "plain_english": "Opal is a software synth from Universal Audio. It blends classic analog sounds with wavetable tones. Its controls can morph, or smoothly shift, between sounds. It also has built-in effects, so patches come out ready to use.", "purpose_function": "It gives sound designers a hybrid analog-and-wavetable synth with smooth morphing and built-in studio effects. It exists to make evolving, ready-to-mix synth sounds easy to create.", "practical_application": "A producer picks a preset, morphs the oscillators and filter for movement, and uses the onboard delay and reverb to place the patch in a mix.", "category": "Virtual instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["PolyMAX", "Electra 88", "Ravel", "UADx", "UAD Spark"], "common_mistakes": ["Assuming it models one specific vintage synth; it is a hybrid analog and wavetable design", "Overlooking its built-in effects and adding redundant outboard processing", "Thinking it needs UA hardware; it is a native plug-in"], "scenario_contexts": ["Designing evolving pads that morph over time", "Creating modern hybrid bass and lead sounds", "Using onboard effects for finished, mixable patches"], "formula_symbolic": "", "formula_words": ""}, {"id": "efcadfc7-f8b2-476c-9ec3-9756482d8472", "term": "Oxide Tape Extension", "definition": "A Universal Audio, Inc. tape-saturation emulation, offered as a plug-in and as a LUNA Extension, that adds analog tape color and low-end response through simple input and output controls. It models tape compression and circuit overdrive with selectable tape speeds (7.5 and 15 IPS) and emphasis EQ curves. Developed by the team behind UA's Ampex and Studer tape plug-ins, it does not model one specific named machine. The 'Extension' form integrates it directly into the LUNA recording system.", "plain_english": "This is a simple tape-warmth tool from Universal Audio. It adds the punch and low end of analog tape to your tracks. You mostly just set the input and output levels. Unlike its bigger tape plug-ins, it is meant to be quick and easy.", "purpose_function": "It adds analog tape saturation and cohesion quickly, with fewer controls than UA's detailed tape-machine models. It exists as a fast 'tape glue' tool for tracks or a mix.", "practical_application": "An engineer drops Oxide on a drum bus or mix, raises the input for saturation, and sets the output to keep level steady while adding tape warmth.", "category": "Tape machine emulation", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Ampex ATR-102 Tape Extension", "Studer A800 Tape Extension", "API Summing Extension", "UAD", "UADx"], "common_mistakes": ["Assuming it models a specific named tape machine; it does not name one", "Pushing input too hard and adding harshness instead of subtle glue", "Thinking speed choice does nothing; 7.5 and 15 IPS change saturation and tone"], "scenario_contexts": ["Adding quick tape warmth to a drum bus", "Gluing a mix with light saturation", "Softening harsh digital transients on individual tracks"], "formula_symbolic": "", "formula_words": ""}, {"id": "a90f9436-6178-47bb-aefe-4c3934b27c72", "term": "PolyMAX", "definition": "PolyMAX (PolyMAX Synth) is a Universal Audio, Inc. native software synthesizer that emulates classic 1970s-80s polyphonic analog synths, offering up to eight voices. Rather than modeling one instrument, it draws on the characters of Prophet, Oberheim, and Jupiter-style polysynths. It provides two analog-modeled oscillators with waveform morphing, FM and sync, a multimode resonant filter with 2- or 4-pole slopes, LFO and dual ADSR envelopes, and onboard modulation and space effects.", "plain_english": "PolyMAX is a software synth from Universal Audio. It copies the warm sound of famous 1970s and 1980s analog synths. It can play many notes at once for lush chords. It has classic controls plus built-in effects for a finished sound.", "purpose_function": "It recreates the sound and feel of vintage polyphonic analog synths in a modern plug-in with familiar controls. It exists to give producers classic analog pads, keys, and leads without vintage hardware.", "practical_application": "A producer loads PolyMAX, shapes a warm pad with the oscillators and filter, and adds the onboard chorus and reverb for a lush polysynth part.", "category": "Virtual instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Opal Morphing Synthesizer", "Electra 88", "Ravel", "UADx", "UAD Spark"], "common_mistakes": ["Assuming it models a single synth; it blends Prophet, Oberheim, and Jupiter-style characters", "Ignoring the 2- versus 4-pole filter choice, which changes the tone strongly", "Thinking it needs UA hardware; it is a native plug-in"], "scenario_contexts": ["Programming lush analog-style pads for a track", "Recreating vintage synth-pop lead and bass sounds", "Layering polysynth chords under a modern production"], "formula_symbolic": "", "formula_words": ""}, {"id": "d0497867-10ce-47ff-856b-d8e89996688e", "term": "Ravel", "definition": "Ravel is a Universal Audio, Inc. native software piano instrument that recreates a Steinway Model B grand piano using physical-modeling techniques and UA's UltraResonance technology for sympathetic string resonance. It offers three vintage microphone pairs with adjustable close/room blend, plus tone, volume, and a reverse-piano mode. It runs as a plug-in in any DAW and needs no UA hardware.", "plain_english": "Ravel is a software grand piano from Universal Audio. It recreates a Steinway Model B, a piano heard on many records. It uses modeling to capture how the strings ring together. You play it with a MIDI keyboard and pick the mic blend you like.", "purpose_function": "It provides a detailed, mixable studio grand piano sound with realistic string resonance for recording and production. It exists to deliver a Steinway-style piano without a real instrument or room.", "practical_application": "A producer loads Ravel on a MIDI track, blends the close and room mics, and adjusts tone to sit the piano in a pop or singer-songwriter mix.", "category": "Virtual instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Electra 88", "Opal Morphing Synthesizer", "PolyMAX", "UADx", "UAD Spark"], "common_mistakes": ["Assuming it is pure sampling; it uses physical modeling with UltraResonance for string resonance", "Ignoring the mic blend, which strongly changes the sound and space", "Thinking it needs UA hardware; it is a native plug-in"], "scenario_contexts": ["Recording a studio grand piano part for a pop song", "Blending close and room mics for a more intimate or spacious tone", "Creating reversed piano textures for an intro"], "formula_symbolic": "", "formula_words": ""}, {"id": "fa22ea7e-e68b-4ac2-8109-aefe4792372d", "term": "Ruby 63 Top Boost Amplifier", "definition": "Ruby '63 Top Boost Amplifier is a Universal Audio guitar amp emulation of an early-1960s British 'Top Boost' valve combo of the Vox AC30 type, modeling its preamp, power amp, tone stack, and mic'd speaker cabinets. It ships both as a UAFX hardware pedal and as a UADx/UAD software plug-in. The name is a trademark of Universal Audio, Inc.; the Vox AC30 it emulates is a separate product of Vox Amplification.", "plain_english": "This is Universal Audio's copy of a famous 1960s British guitar amp, the Vox AC30. It captures the amp's chime, breakup, and built-in tremolo. You can buy it as a stompbox pedal or as software. Universal Audio owns the Ruby name; Vox makes the real amp.", "purpose_function": "It lets guitarists get classic British 'Top Boost' amp tones without owning or setting up and mic'ing the real amplifier.", "practical_application": "A technician runs a guitar into the Ruby '63 pedal or plug-in, picks a channel and speaker cabinet, and records an AC30-style tone direct.", "category": "Amp Emulation", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UAFX", "Woodrow 55 Instrument Amplifier", "UAFX Dual-Engine Processing", "UADx", "Amp modeling"], "common_mistakes": ["Thinking Ruby '63 is a Vox product; it is Universal Audio's emulation of a Vox-type amp", "Assuming it is only a pedal; it also exists as a UADx/UAD plug-in", "Leaving cabinet emulation on when re-amping through a real amplifier"], "scenario_contexts": ["Recording a chiming rhythm guitar direct with no amp in the room", "Getting AC30-style edge-of-breakup tones on a live stage", "Layering a British amp tone under a pop vocal"], "formula_symbolic": "", "formula_words": ""}, {"id": "4271c841-0acf-4329-a9e2-b5eefc111cdc", "term": "Sphere", "definition": "Sphere is Universal Audio's microphone modeling system: a dual-capsule large-diaphragm condenser microphone paired with the Sphere plug-in, which recreates the response of many classic and modern studio microphones. Because the mic captures the sound field from separate front and rear capsules, the plug-in can reconstruct different microphones' polar patterns and tone after recording. Sphere is a trademark of Universal Audio, Inc.; the technology originated with Townsend Labs.", "plain_english": "Sphere is a microphone and software combo from Universal Audio. The mic has two capsules that record sound from front and back. The software then makes it sound like many famous studio microphones. You can even change the mic choice and pickup pattern after you record.", "purpose_function": "It exists so engineers can access the sound of many costly vintage and modern mics from one microphone, and adjust the mic choice later.", "practical_application": "An engineer records a vocal through the Sphere mic, then auditions different modeled mics in the plug-in afterward to pick the best fit.", "category": "Modeling Microphone", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Sphere Modeling Microphone", "Sphere Mic Collection", "Sphere Dual Mode", "Sphere Stereo Mode", "Polar pattern"], "common_mistakes": ["Thinking Sphere is only a plug-in; it needs its dual-capsule hardware mic to work", "Assuming you must commit to a mic model while tracking; the model is chosen or changed later", "Recording only one channel and losing the ability to change patterns afterward"], "scenario_contexts": ["Auditioning several classic vocal mics after the session", "Matching a new take to an older one made with a specific mic", "Capturing a source when unsure which mic will suit the mix"], "formula_symbolic": "", "formula_words": ""}, {"id": "1ffd565b-e83a-4ca5-a7ce-8d9062f846e0", "term": "Sphere Dual Mode", "definition": "Sphere Dual Mode is a Sphere plug-in setting that applies two different microphone models at once — one to the front capsule and one to the rear capsule of the Sphere microphone. Each modeled mic can have its own type, tone, and polar pattern, and the two are blended or routed separately. It is part of Universal Audio's Sphere system.", "plain_english": "Dual Mode lets the Sphere microphone act like two different mics at the same time. One model is used for the front, another for the back. You can blend them or keep them apart. For example, put a bright mic on one side and a bassier mic on the other.", "purpose_function": "It exists to let engineers combine the character of two different modeled mics from a single recorded source.", "practical_application": "On acoustic guitar, a technician sets a small-diaphragm model on the neck side and a large-diaphragm model on the body side, then blends them.", "category": "Modeling Microphone", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Sphere", "Sphere Modeling Microphone", "Sphere Stereo Mode", "Sphere Mic Collection", "Polar pattern"], "common_mistakes": ["Confusing Dual Mode with Stereo Mode; Dual Mode blends two mic models, not a stereo image", "Thinking both capsules must use the same model, when each side can run a different mic model", "Forgetting Dual Mode relies on the mic's two-capsule capture"], "scenario_contexts": ["Blending two mic characters on a single acoustic guitar", "Combining a warm and a bright model on a vocal", "Shaping tone by mixing front and rear mic models"], "formula_symbolic": "", "formula_words": ""}, {"id": "bd678fe1-afed-47aa-9a31-a888f7024104", "term": "Sphere Mic Collection", "definition": "The Sphere Mic Collection is the library of emulated microphone models included with the Sphere plug-in, recreating a range of classic and modern studio microphones. The number of models depends on the Sphere hardware (for example, 38 models with the DLX and Townsend Labs L22, and 20 with the LX). It is part of Universal Audio's Sphere modeling system.", "plain_english": "The Mic Collection is the set of microphone sounds built into the Sphere software. Each one copies a famous studio mic. You pick one and your Sphere mic takes on that sound. Bigger Sphere models come with more mic choices.", "purpose_function": "It gives users a ready library of modeled microphones to choose from within the Sphere plug-in.", "practical_application": "An engineer scrolls the Mic Collection to find a modeled tube condenser that flatters a particular singer.", "category": "Modeling Microphone", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Sphere", "Sphere Modeling Microphone", "Sphere Dual Mode", "Sphere Stereo Mode", "UADx"], "common_mistakes": ["Assuming every Sphere model includes the same number of mics; the count depends on the hardware", "Treating the modeled mics as the actual branded mics rather than emulations", "Thinking the collection works without the Sphere hardware microphone"], "scenario_contexts": ["Choosing a modeled mic for a vocal from the built-in list", "Comparing several modeled mics on one recorded take", "Matching a modeled mic to gear used on an earlier session"], "formula_symbolic": "", "formula_words": ""}, {"id": "00156780-a3be-4cf5-b2a4-e4782f6c73e6", "term": "Sphere Modeling Microphone", "definition": "The Sphere Modeling Microphone is the dual-capsule large-diaphragm condenser microphone at the heart of the Sphere system, sold as models such as the UA Sphere DLX and LX (and the original Townsend Labs L22). Its two capsules capture the directional and distance information that the Sphere plug-in uses to model other microphones. The hardware is made by Universal Audio, Inc.", "plain_english": "This is the actual microphone in the Sphere system. It has two capsules instead of one. Those capsules record extra detail about where sound comes from. The Sphere software uses that detail to copy other famous mics. Models include the UA Sphere DLX and LX.", "purpose_function": "It captures the raw dual-capsule signal the Sphere plug-in needs to accurately model other microphones and polar patterns.", "practical_application": "A technician sets up the Sphere mic like any large-diaphragm condenser, records both capsule channels, then chooses mic models in the plug-in.", "category": "Modeling Microphone", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Sphere", "Sphere Mic Collection", "Sphere Dual Mode", "Sphere Stereo Mode", "Condenser microphone"], "common_mistakes": ["Recording only one capsule channel, which blocks later pattern or stereo changes", "Treating it as an ordinary single-capsule condenser microphone", "Forgetting it needs the Sphere plug-in to apply mic models"], "scenario_contexts": ["Tracking vocals with a mic whose model can change later", "Recording an instrument for flexible post-session mic choice", "Setting up a single mic that can later become a stereo pair"], "formula_symbolic": "", "formula_words": ""}, {"id": "d2cc0f59-8fc8-46c4-9081-61e5045f1e66", "term": "Sphere Stereo Mode", "definition": "Sphere Stereo Mode uses the Sphere microphone's two capsules to produce a coincident stereo image from a single mic. With the mic rotated 90 degrees, the front capsule becomes the left channel and the rear becomes the right, forming a back-to-back (180-degree) coincident pair that requires a Sphere '180' plug-in instance for discrete left/right outputs. It is part of Universal Audio's Sphere system.", "plain_english": "Stereo Mode turns one Sphere mic into a stereo pair. The two capsules become the left and right channels. You turn the mic sideways to set this up. It gives a wide stereo image from a single microphone.", "purpose_function": "It lets engineers capture a stereo recording from one Sphere microphone instead of setting up two mics.", "practical_application": "To record a stereo acoustic guitar, a technician rotates the Sphere mic 90 degrees and loads a Sphere 180 plug-in for separate left and right outputs.", "category": "Modeling Microphone", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Sphere", "Sphere Modeling Microphone", "Sphere Dual Mode", "Sphere Mic Collection", "Stereo miking"], "common_mistakes": ["Confusing Stereo Mode with Dual Mode; Stereo Mode makes a left/right image", "Forgetting to rotate the mic 90 degrees for the intended stereo field", "Not loading the Sphere 180 plug-in needed for discrete outputs"], "scenario_contexts": ["Recording a stereo acoustic guitar with one mic", "Capturing a stereo room image from a single microphone", "Getting a coincident stereo pair without two mic stands"], "formula_symbolic": "", "formula_words": ""}, {"id": "dba1d33e-009d-4a93-ab6e-973f7b24c3ce", "term": "Starlight Echo Station", "definition": "Starlight Echo Station is a Universal Audio delay effect that emulates classic echo units, including an early-1970s EP-III tape echo, a late-1970s analog bucket-brigade (DMM-style) delay, and a modern precision digital delay. It uses UAFX dual-engine processing so a live delay and a preset delay can run at once with spillover trails. It ships as a UAFX pedal and as a UADx/UAD plug-in; the name is a trademark of Universal Audio, Inc.", "plain_english": "Starlight is a delay, or echo, effect from Universal Audio. It copies three classic echo types: tape, analog, and digital. It has two engines, so echoes can trail off smoothly when you switch sounds. You can get it as a pedal or as software.", "purpose_function": "It provides several vintage and modern delay sounds in one unit, with smooth trailing switching between them.", "practical_application": "A guitarist dials a tape-echo slapback on the Starlight pedal, then taps in a longer digital delay for a solo without cutting off the trails.", "category": "Delay Effect", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UAFX", "UAFX Dual-Engine Processing", "UAFX Control", "UADx", "Delay"], "common_mistakes": ["Assuming the tape mode is a real tape machine rather than an emulation", "Ignoring dual-engine spillover and getting cut-off trails when switching", "Thinking it produces only one delay type"], "scenario_contexts": ["Adding tape slapback to a rockabilly rhythm part", "Switching from short to long delay during a solo with trails intact", "Recording an analog-style modulated delay direct into a DAW"], "formula_symbolic": "", "formula_words": ""}, {"id": "da074d25-f2ef-4ba7-b4e8-fd4321fb5fc3", "term": "Studer A800 Tape Extension", "definition": "Studer A800 Tape Extension is Universal Audio's UAD/UADx plug-in emulation of the Studer A800 multitrack analog tape recorder, modeling its complete electronic signal path, tape saturation, and noise. It reproduces controls such as tape speed (7.5, 15, and 30 inches per second), tape formulations (250, 456, 900, GP9), and calibration and bias settings. The A800 machine is made by Studer; the emulation is a product of Universal Audio, Inc.", "plain_english": "This is Universal Audio's software copy of the Studer A800, a professional analog tape recorder. It adds the warm sound, gentle saturation, and hiss of real tape to your tracks. You can choose the tape speed and tape type. Studer made the real machine; UA made the emulation.", "purpose_function": "It lets engineers add the sound of a classic 2-inch analog tape machine to a digital session.", "practical_application": "A mixer inserts the Studer A800 plug-in on a drum bus and chooses 15 inches per second to add analog glue and low-end weight.", "category": "Tape Emulation", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UAD", "UAD Powered Plug-Ins", "UADx", "Tape saturation", "UAD Console"], "common_mistakes": ["Assuming higher tape speed always means more saturation; each speed changes the tone differently", "Thinking it is a UA original design rather than an emulation of a Studer machine", "Overdriving the input and adding unwanted distortion by mistake"], "scenario_contexts": ["Adding analog warmth to a digital mix bus", "Softening harsh transients on drums with tape saturation", "Emulating a classic tape-tracked sound on vocals"], "formula_symbolic": "", "formula_words": ""}, {"id": "961f1f12-a8c2-4914-bfa0-7183c08424ee", "term": "UAD", "definition": "UAD (Universal Audio Digital) is Universal Audio's audio plug-in platform. UAD plug-ins run either on dedicated UA DSP hardware (Apollo interfaces and UAD-2 accelerators) or natively on the computer's CPU as UADx. The platform hosts emulations of classic studio hardware alongside native effects. UAD is a trademark of Universal Audio, Inc.", "plain_english": "UAD is Universal Audio's system of audio plug-ins. Some run on special UA hardware chips, and newer ones run on your computer. Many copy classic studio gear like compressors and equalizers. UAD stands for Universal Audio Digital.", "purpose_function": "It provides high-quality effect and hardware-emulation plug-ins, with the option to offload processing onto dedicated DSP hardware.", "practical_application": "An engineer loads UAD plug-ins in a DAW, running some on Apollo DSP for low-latency tracking and others natively while mixing.", "category": "Plug-In Platform", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UADx", "UAD Powered Plug-Ins", "UAD Console", "UAD Spark", "Universal Audio Digital"], "common_mistakes": ["Thinking all UAD plug-ins need UA hardware; UADx versions run on the CPU", "Confusing the whole UAD platform with a single plug-in", "Assuming UAD and UAFX are the same; UAFX is the guitar pedal line"], "scenario_contexts": ["Running vintage-style compressors on a mix", "Tracking through Apollo DSP with low latency", "Choosing between DSP and native versions of a plug-in"], "formula_symbolic": "", "formula_words": ""}, {"id": "bbfc24e3-ef6d-4e17-85aa-e8fe2a48f346", "term": "UAD Console", "definition": "UAD Console is the software mixer application for Universal Audio's Apollo audio interfaces. It provides near-zero-latency input monitoring, Unison preamp modeling, and real-time UAD (UAD-2 DSP) plug-in processing performed on the Apollo hardware rather than the computer's CPU. It is a product of Universal Audio, Inc.", "plain_english": "UAD Console is the mixing app for Universal Audio's Apollo audio interfaces. It lets performers hear themselves with almost no delay. It can add UAD effects and modeled mic preamps while recording. The Apollo hardware does this work, not your computer.", "purpose_function": "It exists to give low-latency monitoring and to run UAD plug-ins and Unison preamps in real time during tracking.", "practical_application": "An engineer sets up cue mixes and inserts a modeled preamp and compressor in Console so a singer hears processed, latency-free vocals.", "category": "Interface Software", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UAD", "UAD Powered Plug-Ins", "Unison", "UAD Meter & Control Panel", "UAD Spark"], "common_mistakes": ["Trying to insert native UADx plug-ins in Console; it hosts DSP (UAD-2) plug-ins", "Thinking the computer's CPU does Console's processing", "Confusing Console with the DAW's own mixer"], "scenario_contexts": ["Building low-latency headphone mixes for a session", "Recording through a Unison-modeled mic preamp", "Monitoring or printing UAD effects while tracking"], "formula_symbolic": "", "formula_words": ""}, {"id": "e88dfa9d-fc41-4336-950f-9d6f5f6e8bb9", "term": "UAD Meter & Control Panel", "definition": "The UAD Meter & Control Panel is Universal Audio's utility application for UAD hardware. Its meter displays the DSP load of Apollo, Satellite, and UAD-2 PCIe devices, while the Control Panel provides device status, configuration settings, and diagnostics. It is a product of Universal Audio, Inc.", "plain_english": "This is a small helper program for Universal Audio hardware. Its meter shows how much of the UA processing chips you are using. The control panel holds settings and status messages. Engineers use it to check the hardware and fix problems.", "purpose_function": "It lets users monitor DSP usage and manage or troubleshoot UAD hardware settings.", "practical_application": "When plug-ins stop loading, a technician opens the UAD Meter to check DSP load and reads the Control Panel for status messages.", "category": "Utility Software", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UAD", "UAD Console", "UAD Powered Plug-Ins", "DSP", "Apollo"], "common_mistakes": ["Ignoring the DSP meter and overloading the hardware until plug-ins drop out", "Confusing it with UAD Console, which is the mixer", "Thinking it processes audio; it only meters and configures the hardware"], "scenario_contexts": ["Checking DSP headroom before adding more plug-ins", "Diagnosing why a UAD device is not recognized", "Adjusting UAD system settings after an install"], "formula_symbolic": "", "formula_words": ""}, {"id": "242963d1-005b-4e27-8174-a6921359e9b2", "term": "UAD Powered Plug-Ins", "definition": "UAD Powered Plug-Ins are Universal Audio plug-ins that run on dedicated UA DSP hardware — Apollo interfaces or UAD-2 accelerators — instead of the host computer's CPU. Offloading the processing frees CPU resources and enables low-latency use while tracking. 'UAD Powered Plug-Ins' is a product line of Universal Audio, Inc.", "plain_english": "These are Universal Audio effects that run on special UA hardware chips, not your computer. That keeps your computer free to do other work. It also lets you record with effects and almost no delay. Many of them copy classic studio gear.", "purpose_function": "They move plug-in processing onto UA DSP hardware to save computer CPU and allow real-time, low-latency use.", "practical_application": "An engineer inserts UAD Powered Plug-Ins across many channels, letting the Apollo DSP carry the load instead of the computer.", "category": "Plug-In Platform", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UAD", "UADx", "UAD Console", "UAD Meter & Control Panel", "DSP"], "common_mistakes": ["Thinking they run on the CPU; they run on UA DSP hardware", "Loading more than the DSP can handle and running out of processing", "Confusing them with the native UADx versions"], "scenario_contexts": ["Tracking with low latency through Apollo DSP", "Freeing computer CPU on a large mix", "Running many hardware emulations at once on DSP"], "formula_symbolic": "", "formula_words": ""}, {"id": "83eea1e0-e950-429a-ab5f-7ce15359ffca", "term": "UAD Spark", "definition": "UAD Spark is Universal Audio's subscription service that gives access to a growing collection of UAD native (UADx) plug-ins for a monthly or annual fee, without requiring UA DSP hardware. It is a product of Universal Audio, Inc.", "plain_english": "UAD Spark is a subscription from Universal Audio. You pay monthly or yearly to use its UADx software plug-ins. You do not need any UA hardware to use them. It is a way to rent access to their effects.", "purpose_function": "It offers access to UA's native plug-ins on a subscription basis instead of buying each one outright.", "practical_application": "A producer subscribes to UAD Spark to use UADx compressors and equalizers on a laptop with no UA hardware.", "category": "Subscription Service", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UADx", "UAD", "UAD Powered Plug-Ins", "VST3", "Perpetual license"], "common_mistakes": ["Thinking Spark requires UA hardware; UADx plug-ins run natively on the CPU", "Assuming a lapsed subscription keeps the plug-ins active", "Confusing Spark (subscription) with owning a perpetual license"], "scenario_contexts": ["Trying UA plug-ins without buying hardware", "Getting many plug-ins for a monthly fee", "Working on a laptop-only mobile setup"], "formula_symbolic": "", "formula_words": ""}, {"id": "2085c302-5e52-4dea-afc8-8101fd7f2a9b", "term": "UADx", "definition": "UADx is the name for Universal Audio's native UAD plug-ins that run on the host computer's CPU, without requiring an Apollo interface or UAD-2 device. They are provided in VST3, AU, and AAX formats and are available through UAD Spark or as perpetual licenses. UADx is a product of Universal Audio, Inc.", "plain_english": "UADx plug-ins are Universal Audio effects that run on your computer, not on UA hardware. They work in most recording programs. You can get them by subscription or by buying them. They are the native version of UAD plug-ins.", "purpose_function": "It brings UA's plug-in emulations to any computer, removing the need for dedicated UA DSP hardware.", "practical_application": "A mixer loads UADx versions of UA plug-ins in a DAW on a computer that has no UA interface.", "category": "Plug-In Platform", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UAD", "UAD Spark", "UAD Powered Plug-Ins", "VST3", "Native processing"], "common_mistakes": ["Thinking UADx needs UA hardware; it runs on the CPU", "Confusing UADx (native) with UAD-2 DSP plug-ins", "Assuming UADx plug-ins work in UAD Console, which hosts DSP plug-ins"], "scenario_contexts": ["Mixing on a computer with no UA hardware", "Using UA plug-ins in a laptop setup", "Choosing a native plug-in to avoid DSP limits"], "formula_symbolic": "", "formula_words": ""}, {"id": "62b5561c-c4df-4025-8eb4-fa25fb51ef49", "term": "UAFX", "definition": "UAFX is Universal Audio's line of guitar and bass effects, built as stompbox pedals (with matching UADx/UAD plug-ins) that emulate classic amps, cabinets, delays, reverbs, modulation, and compression. UAFX pedals use a dual-engine DSP architecture. UAFX is a trademark of Universal Audio, Inc.", "plain_english": "UAFX is Universal Audio's range of guitar effects. Most are stompbox pedals that copy classic amps and effects. Some also come as software plug-ins. They use two processing engines for rich, detailed sounds.", "purpose_function": "It brings UA's studio-grade emulations to guitarists in pedal form for stage and studio use.", "practical_application": "A guitarist builds a pedalboard of UAFX amp, delay, and reverb pedals to gig without carrying a real amp.", "category": "Guitar Effects", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UAFX Control", "UAFX Dual-Engine Processing", "Ruby 63 Top Boost Amplifier", "Starlight Echo Station", "UADx"], "common_mistakes": ["Confusing UAFX (guitar pedals) with UAD (the studio plug-in platform)", "Assuming UAFX pedals cannot store presets or accept MIDI", "Skipping the UAFX Control app and missing extra effects and settings"], "scenario_contexts": ["Replacing a heavy amp rig with amp-emulator pedals", "Adding studio-quality delay and reverb on a pedalboard", "Recording guitar direct through a UAFX pedal"], "formula_symbolic": "", "formula_words": ""}, {"id": "b585a537-79f0-40e9-8b96-48331e212b64", "term": "UAFX Control", "definition": "UAFX Control is Universal Audio's companion mobile app (iOS and Android) for UAFX pedals. It connects over Bluetooth or a USB-C cable to load and manage presets, download additional effects and speaker cabinets, adjust global settings, and assign MIDI. It is a product of Universal Audio, Inc.", "plain_english": "UAFX Control is a phone app for Universal Audio's UAFX pedals. It connects by Bluetooth or a cable. You use it to save presets, add extra sounds, and change hidden settings. It helps you set up your pedals the way you want.", "purpose_function": "It gives users deeper control over UAFX pedals — presets, extra content, and hidden settings — beyond the pedal's own knobs.", "practical_application": "A guitarist opens UAFX Control on a phone to back up presets and load a bonus speaker cabinet onto a UAFX amp pedal.", "category": "Companion App", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UAFX", "UAFX Dual-Engine Processing", "Ruby 63 Top Boost Amplifier", "Starlight Echo Station", "Preset"], "common_mistakes": ["Thinking firmware updates happen in UAFX Control; the UA Connect app now handles updates", "Assuming the pedals need the app to make sound", "Forgetting to back up presets before making changes"], "scenario_contexts": ["Loading bonus cabinets or voicings onto a pedal", "Backing up and restoring pedal presets", "Setting footswitch and bypass behavior"], "formula_symbolic": "", "formula_words": ""}, {"id": "007a0b7f-347e-4fc7-9861-fc0cfe81738a", "term": "UAFX Dual-Engine Processing", "definition": "UAFX Dual-Engine Processing is the twin-DSP architecture in UAFX pedals that runs two independent stereo effect instances at once — typically one for the live setting and one for a stored preset. This lets the pedal switch between sounds with true stereo spillover (trails) instead of cutting off delay or reverb tails. It is a design of Universal Audio, Inc.", "plain_english": "UAFX pedals have two processing engines inside. That means two effects can run at the same time. When you switch sounds, the old echo or reverb can fade out smoothly. This smooth fade is called spillover, and it avoids abrupt cut-offs.", "purpose_function": "It exists to allow seamless switching between effect settings with natural, trailing decay.", "practical_application": "A guitarist switches from a rhythm delay to a solo delay on a UAFX pedal, and the first delay's trails ring out naturally.", "category": "Processing Architecture", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UAFX", "Starlight Echo Station", "UAFX Control", "Spillover", "DSP"], "common_mistakes": ["Expecting spillover when only one engine or effect is active", "Confusing dual-engine processing with true stereo input on every pedal", "Thinking it doubles the number of separate effects you can chain"], "scenario_contexts": ["Keeping reverb tails alive when changing presets", "Switching delay times mid-song without cutting trails", "Running a live effect and a preset effect together"], "formula_symbolic": "", "formula_words": ""}, {"id": "d38aa0d3-6ee0-4530-9b94-33c1669db02c", "term": "Universal Audio Digital", "definition": "Universal Audio Digital is the full name behind the 'UAD' abbreviation used across Universal Audio's DSP-accelerated and native plug-in platform. It denotes UA's line of digital audio plug-ins and the DSP hardware (Apollo, UAD-2) that can run them. UAD is a trademark of Universal Audio, Inc.", "plain_english": "Universal Audio Digital is what the letters UAD stand for. It refers to Universal Audio's digital plug-ins and processing hardware. The plug-ins copy classic studio gear. They can run on UA hardware or on your computer.", "purpose_function": "The name identifies Universal Audio's digital plug-in and DSP processing platform.", "practical_application": "An engineer sees 'Universal Audio Digital' or 'UAD' branding on plug-ins and hardware and knows they belong to UA's DSP and native ecosystem.", "category": "Plug-In Platform", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UAD", "UADx", "UAD Powered Plug-Ins", "UAD Console", "UAD Spark"], "common_mistakes": ["Thinking it is a different product from UAD; UAD is its abbreviation", "Assuming 'Digital' means CPU-only; it also covers DSP hardware", "Confusing it with UAFX, the guitar pedal line"], "scenario_contexts": ["Identifying UA plug-in and hardware branding", "Explaining what the UAD acronym means to a student", "Grouping UA's DSP and native plug-ins under one name"], "formula_symbolic": "", "formula_words": ""}, {"id": "4a2ead97-6acf-42a2-b195-c27b3ade8d6f", "term": "Waterfall B3", "definition": "Waterfall B3 is Universal Audio's virtual organ instrument that emulates a Hammond B-3 tonewheel organ together with a Leslie 147 rotary speaker cabinet. It models nine drawbars per manual, percussion, vibrato/chorus, tube overdrive, and the rotary speaker's motion, and runs as a UAD/UADx plug-in. The Hammond B-3 and Leslie cabinet are products of their respective makers; the emulation is by Universal Audio, Inc.", "plain_english": "Waterfall B3 is a software organ from Universal Audio. It copies the famous Hammond B-3 organ and its spinning Leslie speaker. You shape the sound with drawbars, just like the real organ. It runs as a plug-in in your recording program.", "purpose_function": "It lets producers play and record classic tonewheel organ and rotary-speaker sounds without the large original instruments.", "practical_application": "A keyboardist loads Waterfall B3, sets the drawbars, and records a gospel organ part with the rotary speaker sped up for effect.", "category": "Virtual Instrument", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UAD", "UADx", "UAD Spark", "UAD Powered Plug-Ins", "Rotary speaker"], "common_mistakes": ["Thinking Waterfall B3 is a UAFX pedal; it is a plug-in instrument", "Assuming it is a Hammond product rather than UA's emulation", "Forgetting to add rotary speaker motion for authentic movement"], "scenario_contexts": ["Recording a gospel or rock organ part in a DAW", "Adding tonewheel organ under a full band mix", "Automating the rotary speaker from slow to fast"], "formula_symbolic": "", "formula_words": ""}, {"id": "81731790-2122-442f-9040-49cb5a174c1d", "term": "Wood Works Acoustic Guitar Modeler", "definition": "Sound Machine Wood Works is a UAD/UADx plug-in that transforms the direct signal from a piezo-equipped acoustic-electric guitar into a realistic, multi-mic'd acoustic guitar tone, and can also re-voice previously recorded acoustic tracks. It is developed by Sound Machine, a UA partner developer, and distributed by Universal Audio, Inc.", "plain_english": "Wood Works is a plug-in that improves acoustic guitar sound. It takes the thin signal from an acoustic guitar's built-in pickup. Then it makes it sound like the guitar was recorded with studio microphones. It can also reshape guitar tracks you already recorded.", "purpose_function": "It exists to turn a plugged-in piezo acoustic guitar into a natural, mic'd studio acoustic tone without setting up microphones.", "practical_application": "On stage or in the studio, a guitarist runs a piezo acoustic through Wood Works to replace the harsh direct sound with a mic'd tone.", "category": "Instrument Modeler", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UAD", "UADx", "UAD Powered Plug-Ins", "Piezo pickup", "UAD Console"], "common_mistakes": ["Feeding it a magnetic electric guitar; it is designed for piezo acoustic pickups", "Expecting it to work well on unrelated sources", "Thinking it needs microphones; it models a mic'd tone from the direct signal"], "scenario_contexts": ["Improving a piezo acoustic's direct sound live", "Re-voicing a recorded acoustic guitar track", "Getting a mic'd acoustic tone without a microphone setup"], "formula_symbolic": "", "formula_words": ""}, {"id": "13d1227d-3964-4b5c-9204-b02168ad0f77", "term": "Woodrow 55 Instrument Amplifier", "definition": "Woodrow '55 Instrument Amplifier is a Universal Audio guitar amp emulation of a mid-1950s American 'tweed' tube combo of the Fender 5E3 Tweed Deluxe type, including its power amp, speaker cabinets, and microphone options. It ships as a UAFX hardware pedal and as a UADx/UAD plug-in. The name is a trademark of Universal Audio, Inc.; the tweed Deluxe it models is a separate Fender product.", "plain_english": "Woodrow '55 is Universal Audio's copy of a 1950s American tweed guitar amp, the Fender Tweed Deluxe. It captures the amp's warm, gritty overdrive. It also models speaker cabinets and microphones. You can buy it as a pedal or as software.", "purpose_function": "It gives guitarists classic 1950s tweed amp tones without owning or mic'ing the original amplifier.", "practical_application": "A guitarist plugs into the Woodrow '55 pedal, turns up the volume for natural tweed breakup, and records direct with a modeled cabinet and mic.", "category": "Amp Emulation", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["UAFX", "Ruby 63 Top Boost Amplifier", "UAFX Dual-Engine Processing", "UAFX Control", "UADx"], "common_mistakes": ["Thinking Woodrow '55 is a Fender product; it is UA's emulation of a tweed-type amp", "Leaving cabinet emulation on when running into a real amp", "Assuming it is only a pedal; it also exists as a plug-in"], "scenario_contexts": ["Recording gritty tweed rhythm guitar direct", "Getting natural amp breakup at low volume", "Using tweed tones on a pedalboard live"], "formula_symbolic": "", "formula_words": ""}, {"id": "c106c694-2daa-4b64-974a-1e3d865bf134", "term": "ARM Automatic Plug-In Conversion", "definition": "A behavior within Universal Audio, Inc.'s Accelerated Realtime Monitoring (ARM) in which the LUNA recording system automatically substitutes plug-ins so a record- or input-enabled signal path can run on Apollo hardware DSP. When ARM is active, a native UADx plug-in that has a UAD DSP equivalent is switched to its DSP version, and a plug-in with no DSP equivalent is bypassed while monitoring. ARM is a proprietary feature of the LUNA system; the underlying method is generic DSP-accelerated near-zero-latency monitoring.", "plain_english": "ARM stands for Accelerated Realtime Monitoring. It is a feature in Universal Audio's LUNA software. When you record, LUNA swaps each plug-in for a version that runs on the Apollo interface's chips. Plug-ins with no such version are turned off until you stop monitoring.", "purpose_function": "It lets a performer monitor through UAD effects with almost no delay by ensuring only hardware-accelerated plug-in versions are used while tracking.", "practical_application": "A technician records a vocalist through a UAD compressor, and ARM auto-converts the plug-in to its DSP version so the singer hears effects without latency.", "category": "Monitoring Workflow", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["ARM-Enabled Track", "ARM-Enabled Bus", "LUNA ARM", "Apollo Mode", "LUNA"], "common_mistakes": ["Assuming every plug-in keeps working during ARM; a plug-in with no UAD DSP equivalent is bypassed while monitoring.", "Thinking the swap is permanent, when the DAW mix uses the chosen plug-in format again after monitoring stops.", "Expecting the conversion in Core Audio or ASIO mode, when it works only in Apollo mode."], "scenario_contexts": ["Tracking a guitar through a UAD amp plug-in in LUNA with ARM enabled.", "Overdubbing a synth in LUNA while ARM keeps monitoring latency low.", "Comparing DSP and native versions of the same UAD plug-in during a session."], "formula_symbolic": "", "formula_words": ""}, {"id": "c7a1b824-4a46-4f4f-855d-ddd9f7dffb86", "term": "ARM-Enabled Bus", "definition": "In Universal Audio, Inc.'s Accelerated Realtime Monitoring (ARM), an ARM-enabled bus is an auxiliary (aux) send bus routed through Apollo's DSP so time-based effects such as reverb or delay are monitored with near-zero latency. ARM supports up to two dedicated DSP-accelerated aux buses, using UAD Console DSP rather than standard host (computer) processing.", "plain_english": "A bus is a channel that collects signals to add one shared effect. An ARM-enabled bus runs on the Apollo interface's chips. This lets performers hear reverb or delay in real time while recording. LUNA gives you up to two of these effect buses.", "purpose_function": "It provides low-latency reverb or delay in a performer's monitor mix without loading the host computer's processor.", "practical_application": "An engineer sends a singer's vocal to an ARM reverb bus so the artist hears ambience in real time while tracking.", "category": "Monitoring Workflow", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["ARM-Enabled Track", "ARM Automatic Plug-In Conversion", "LUNA ARM", "Apollo Mode", "Console Tracking Mode"], "common_mistakes": ["Adding more than two ARM aux buses, when only two DSP-accelerated aux buses are supported.", "Using a native-only reverb on the bus and expecting zero latency; it must be a UAD DSP plug-in.", "Confusing an ARM aux bus with a normal DAW aux, which the host CPU processes."], "scenario_contexts": ["Setting up a reverb cue send for a vocalist in LUNA.", "Adding a slap delay to a monitor mix during a tracking date.", "Running out of ARM aux buses and moving an effect to a native bus."], "formula_symbolic": "", "formula_words": ""}, {"id": "4d8244ba-60ba-472b-8dd0-241766d2a52d", "term": "ARM-Enabled Track", "definition": "In Universal Audio, Inc.'s Accelerated Realtime Monitoring (ARM), an ARM-enabled track is a record- or input-enabled audio or instrument track whose monitoring is accelerated through Apollo's DSP for near-zero latency. On audio tracks, ARM routes monitoring through Apollo hardware; on instrument tracks it forces the instrument to run at a lower buffer setting (on macOS). ARM operates in Apollo mode only.", "plain_english": "An ARM-enabled track is a track you have armed to record. Universal Audio's LUNA software sends its monitoring through the Apollo interface's chips. This means you hear yourself with almost no delay. For instrument tracks, it lowers the buffer so playing feels tight.", "purpose_function": "It removes the monitoring delay a performer would otherwise hear while recording through plug-ins.", "practical_application": "A drummer records to an ARM-enabled track and hears a UAD channel strip in real time as they play.", "category": "Monitoring Workflow", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["ARM-Enabled Bus", "ARM Automatic Plug-In Conversion", "LUNA ARM", "Apollo Mode", "LUNA"], "common_mistakes": ["Thinking ARM affects all tracks, when only record- or input-enabled tracks are accelerated.", "Expecting native AU or VST3 plug-ins to keep working on the track during ARM; they are bypassed.", "Leaving tracks input-enabled needlessly, which ties up Apollo DSP resources."], "scenario_contexts": ["Record-enabling a vocal track to monitor through Apollo DSP.", "Input-monitoring a bass DI through a UAD amp with no delay.", "A software instrument switched to a lower buffer while armed."], "formula_symbolic": "", "formula_words": ""}, {"id": "ca549db7-b3a6-4cdc-894e-913d273f1df1", "term": "Apollo", "definition": "Apollo is Universal Audio, Inc.'s line of professional audio interfaces that connect to a computer over Thunderbolt (or USB on some models). Each unit combines 24-bit/192 kHz analog-to-digital and digital-to-analog conversion, Unison-enabled microphone preamps, and onboard DSP that runs UAD plug-ins in real time, controlled through UAD Console software. The Apollo name is a trademark; the underlying functions (AD/DA conversion, mic preamps, DSP monitoring) are generic audio-interface concepts.", "plain_english": "Apollo is a family of audio interfaces made by Universal Audio. An audio interface connects mics and instruments to your computer. Apollo units turn sound into digital data and back again. They also have built-in chips that run effects while you record, so you hear them without delay.", "purpose_function": "It moves audio in and out of a computer while offering low-latency processing and modeled mic preamps for recording.", "practical_application": "An engineer plugs a mic into an Apollo, sets a Unison preamp, and records through UAD plug-ins monitored in Console.", "category": "Audio Interface", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["Apollo X", "Apollo Mode", "Apollo Expanded", "Apollo Flex Routing", "LUNA"], "common_mistakes": ["Confusing the Apollo interface with the UAD-2 DSP card; Apollo has DSP built in.", "Assuming every Apollo model uses Thunderbolt, when some connect over USB.", "Thinking UAD plug-ins run on the computer; on Apollo they run on the interface's DSP."], "scenario_contexts": ["Setting up an Apollo Twin for a home studio.", "Recording a band through an Apollo rack unit's preamps.", "Monitoring UAD effects live during tracking."], "formula_symbolic": "", "formula_words": ""}, {"id": "5aac0b6f-0cc0-4c30-b418-23983c610220", "term": "Apollo Expanded", "definition": "Apollo Expanded is Universal Audio, Inc.'s software feature that lets up to four Thunderbolt Apollo units (any mix of rack and desktop models) operate as one integrated system, supporting a total of up to six UAD-2 DSP devices. All units are controlled in a single Console window and their combined I/O appears in the DAW; one unit acts as the monitor (leader) and the others as expander (follower) units, with all clocking managed automatically over Thunderbolt.", "plain_english": "Apollo Expanded lets you link several Apollo interfaces together. They then work as one big interface with more inputs and outputs. You can join up to four units over Thunderbolt. One unit runs the speakers, and the others add extra channels.", "purpose_function": "It adds input/output count and DSP power by combining multiple Apollo units without extra clock or ADAT cabling.", "practical_application": "A studio cascades two Apollo rack units to record a full drum kit and still keep inputs free for other players.", "category": "Audio Interface", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["Apollo", "Apollo X", "Apollo Flex Routing", "UAD-2", "Apollo Mode"], "common_mistakes": ["Trying to link more than four Apollo units, when four is the limit.", "Adding separate word-clock cables between units; Thunderbolt manages clocking automatically.", "Assuming USB Apollos can be cascaded; cascading is a Thunderbolt feature."], "scenario_contexts": ["Cascading two Apollos for a large tracking session.", "Expanding I/O when a single interface runs out of inputs.", "Designating leader and follower units in Console."], "formula_symbolic": "", "formula_words": ""}, {"id": "bca47f2d-d731-41f2-a139-7fb36ee47197", "term": "Apollo Flex Routing", "definition": "Flex Routing (Output Flex Routing) is a Universal Audio, Inc. Console feature that lets any Apollo input channel be freely assigned to available hardware outputs instead of only the monitor outputs. On Apollo X rack models up to 16 output-route assignments are available (up to eight on other rack models); it is not a mix bus, so multiple inputs cannot be merged to one output, and it is unavailable on desktop models and at 176.4 or 192 kHz.", "plain_english": "Flex Routing lets you send an Apollo input straight to any hardware output. Normally inputs only reach the main monitor outputs. This feature gives you more freedom in where signals go. It is a routing tool, not a place to mix signals together.", "purpose_function": "It provides flexible direct output routing for feeding headphone amps, outboard gear, or separate speaker sets from Apollo inputs.", "practical_application": "An engineer flex-routes a talent mic directly to a broadcast feed output while still monitoring in the studio.", "category": "Interface Routing", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["Apollo", "Apollo X", "Apollo Expanded", "Console Recall", "Apollo Mode"], "common_mistakes": ["Trying to sum several inputs to one output with Flex Routing; it is not a mix bus.", "Expecting it on desktop Apollos, when it works only on rack models.", "Using it at 192 kHz, where the feature is unavailable."], "scenario_contexts": ["Routing an input to an external headphone amp.", "Sending a channel to a separate set of monitors.", "Feeding a signal to outboard gear directly from Apollo."], "formula_symbolic": "", "formula_words": ""}, {"id": "eed37fa4-4c9f-4f6a-98b2-8d0108df5d05", "term": "Apollo Mode", "definition": "Apollo mode is the operating mode of Universal Audio, Inc.'s LUNA recording system in which LUNA integrates directly with a connected Thunderbolt Apollo interface. In this mode LUNA automatically accesses all of the hardware's inputs, outputs, preamps, and Unison inserts, and Apollo-only features such as Accelerated Realtime Monitoring (ARM) and Unison become available. LUNA's other modes (Core Audio on Mac, ASIO on Windows) do not provide Unison or ARM.", "plain_english": "Apollo mode is a setting in Universal Audio's LUNA software. It turns on when a Thunderbolt Apollo interface is connected. In this mode, LUNA controls the Apollo's inputs, outputs, and preamps directly. Special features like Unison and ARM only work in this mode.", "purpose_function": "It gives LUNA the tightest link to Apollo hardware so features like ARM and Unison preamp modeling can be used.", "practical_application": "A user opens LUNA with an Apollo attached and works in Apollo mode to track through Unison preamps with ARM.", "category": "Recording System", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["LUNA", "LUNA Apollo Mode", "Apollo", "LUNA ARM", "Console Tracking Mode"], "common_mistakes": ["Expecting Unison or ARM in Core Audio or ASIO mode, when they need Apollo mode.", "Thinking Apollo mode is a hardware button; it is a LUNA software mode.", "Assuming any interface enables Apollo mode, when it requires Apollo hardware."], "scenario_contexts": ["Launching LUNA with a Thunderbolt Apollo connected.", "Switching a Mac session to Core Audio and losing Unison.", "Setting Unison preamps in an Apollo-mode LUNA session."], "formula_symbolic": "", "formula_words": ""}, {"id": "d36c10d5-8523-4cd5-822d-7375cbd47d02", "term": "Apollo Monitor Correction", "definition": "Apollo Monitor Correction is a Universal Audio, Inc. feature, developed with Sonarworks, that applies room, speaker, and headphone calibration to the monitor and headphone outputs of Apollo X interfaces. Calibration profiles are created in Sonarworks SoundID Reference software and then run on Apollo's onboard DSP in real time, so correction is applied to monitoring without that software needing to run during playback. It supports Apollo X series units in stereo and most surround monitoring modes.", "plain_english": "Apollo Monitor Correction fixes the sound of your speakers and headphones. Every room and headphone colors the sound a little. Software measures those errors and builds a fix. The Apollo X interface then applies that fix in real time using its own chips.", "purpose_function": "It gives a flatter, more accurate monitoring reference so mixing decisions translate better to other playback systems.", "practical_application": "An engineer loads a SoundID Reference room profile onto an Apollo X so their monitors sound neutral while mixing.", "category": "Interface Monitoring", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["Apollo X", "Apollo", "Console Recall", "Apollo Mode", "Apollo Flex Routing"], "common_mistakes": ["Expecting monitor correction on non-X Apollo models, when it requires Apollo X.", "Thinking the correction changes the recorded file; it only affects monitoring.", "Assuming the Sonarworks app must stay open, when the profile runs on Apollo DSP."], "scenario_contexts": ["Calibrating studio monitors in an untreated room.", "Applying a headphone profile for accurate reference on cans.", "Checking a mix on corrected monitors before export."], "formula_symbolic": "", "formula_words": ""}, {"id": "7a44b2d4-c222-4905-8924-22898f5eb6c0", "term": "Apollo X", "definition": "Apollo X is Universal Audio, Inc.'s series of Thunderbolt audio interfaces, announced in 2018 and positioned above the standard Apollo line. Apollo X models add HEXA Core UAD DSP (six processing cores), higher-performance conversion (up to 133 dB dynamic range on the x16), switchable +24/+20 dBu operation, surround monitoring up to 7.1 with speaker calibration and fold-down, a built-in talkback microphone, and support for Apollo Monitor Correction. Apollo X is a trademark; the underlying elements (converters, DSP, mic preamps) are generic interface technologies.", "plain_english": "Apollo X is Universal Audio's higher-end line of audio interfaces. It uses six DSP cores, so it can run more effects at once. Its converters are cleaner, and it supports surround sound and monitor correction. It also has a built-in talkback mic for talking to performers.", "purpose_function": "It provides more DSP power, cleaner conversion, and surround and monitoring features aimed at professional studios.", "practical_application": "A studio chooses an Apollo x8 for its extra DSP and talkback when tracking bands through many UAD plug-ins.", "category": "Audio Interface", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["Apollo", "Apollo Monitor Correction", "Apollo Expanded", "Apollo Flex Routing", "UAD-2"], "common_mistakes": ["Assuming all Apollos are Apollo X, when Apollo X is a specific higher-tier series.", "Thinking Monitor Correction works on any Apollo, when it needs Apollo X.", "Confusing HEXA Core (six cores) with the earlier QUAD (four cores) DSP."], "scenario_contexts": ["Selecting an Apollo X for surround monitoring.", "Using the built-in talkback mic during a tracking date.", "Running many UAD plug-ins on HEXA Core DSP."], "formula_symbolic": "", "formula_words": ""}, {"id": "ce6e1880-90db-4852-83f5-18899e356e8a", "term": "Console Recall", "definition": "Console Recall is a Universal Audio, Inc. plug-in (supplied in VST, AU, and AAX formats) that stores and restores the UAD Console configuration inside a DAW session. When its SYNC switch is engaged, the current Console state is saved in the DAW project file and automatically restored when the project is reopened; the plug-in also lets the user view and adjust Apollo's monitor level, mono, and mute states without leaving the DAW.", "plain_english": "Console Recall is a plug-in you put on a track in your DAW. It remembers your Apollo Console settings inside the song file. When you reopen the project, those settings come back automatically. It also lets you change monitor volume and mute without opening Console.", "purpose_function": "It ties Apollo and Console monitor and channel settings to each DAW project so they recall exactly when the project reopens.", "practical_application": "An engineer inserts Console Recall and engages SYNC so a mix session reopens with the same Console monitor setup.", "category": "Interface Monitoring", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["Console Tracking Mode", "Apollo", "Apollo Monitor Correction", "Apollo Flex Routing", "Apollo Mode"], "common_mistakes": ["Forgetting to engage SYNC, so Console settings are not saved with the project.", "Deleting the Console Recall plug-in and losing the stored recall data.", "Thinking it recalls plug-in audio processing; it recalls the Console configuration and monitor states."], "scenario_contexts": ["Reopening a mix and having Console settings restore automatically.", "Adjusting monitor level from the DAW without opening Console.", "Carrying a session's Console setup across days of work."], "formula_symbolic": "", "formula_words": ""}, {"id": "33d0b613-925d-4377-a285-79b0c145cb1c", "term": "Console Tracking Mode", "definition": "Console tracking is the workflow of using UAD Console, Universal Audio, Inc.'s mixing and monitoring software for Apollo interfaces, to record and input-monitor live sources through UAD plug-ins running on Apollo's DSP at near-zero latency, rather than monitoring through the DAW. The performer hears input processing with essentially no delay, and up to four independent stereo cue mixes can be fed to musicians. This hardware-DSP monitoring is what LUNA's Accelerated Realtime Monitoring (ARM) later replaced for LUNA users.", "plain_english": "Console tracking means recording while you monitor through Universal Audio's Console software. The Apollo interface adds effects using its own chips. So performers hear those effects with almost no delay. You can also send each player their own headphone mix.", "purpose_function": "It lets performers monitor through effects and modeled preamps in real time during recording, keeping the delay off the computer's processor.", "practical_application": "An engineer sets up Console with UAD plug-ins and cue mixes to track a singer monitoring through reverb at near-zero latency.", "category": "Monitoring Workflow", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["Console Recall", "LUNA ARM", "Apollo", "Apollo Mode", "ARM-Enabled Track"], "common_mistakes": ["Confusing Console tracking with mixing in the DAW; Console handles low-latency input monitoring on Apollo DSP.", "Expecting native computer plug-ins to work in Console, when only UAD plug-ins run on Apollo DSP.", "Recording the wet Console effect when only monitoring was intended, unless printing is chosen deliberately."], "scenario_contexts": ["Tracking vocals through a UAD channel strip in Console.", "Building separate cue mixes for a band during a session.", "Monitoring guitar through a UAD amp with no delay while recording the DI."], "formula_symbolic": "", "formula_words": ""}, {"id": "cf59d462-44c2-49f1-94ef-57286d52be13", "term": "LUNA", "definition": "LUNA is Universal Audio, Inc.'s recording system (a digital audio workstation) for macOS and Windows, providing recording, MIDI creation, editing, arranging, and mixing in one environment. It integrates tightly with Apollo interfaces in Apollo mode to offer features such as Accelerated Realtime Monitoring (ARM), Unison preamps, and UA instrument and tape emulations, and it can also run with Core Audio (Mac) or ASIO (Windows) devices with reduced hardware integration.", "plain_english": "LUNA is recording software made by Universal Audio. It is a type of program called a DAW, short for digital audio workstation. You use it to record, edit, arrange, and mix music. It works best with Universal Audio's Apollo interfaces, which unlock its special features.", "purpose_function": "It gives Apollo users a DAW built to use Apollo's preamps, DSP monitoring, and emulations directly.", "practical_application": "A producer records and mixes a track entirely in LUNA using an Apollo's Unison preamps and ARM monitoring.", "category": "Recording System", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["Apollo Mode", "LUNA ARM", "LUNA Apollo Mode", "Apollo", "Console Tracking Mode"], "common_mistakes": ["Thinking LUNA works only with Apollo, when it also runs with Core Audio or ASIO devices.", "Expecting Unison and ARM without an Apollo, when those need Apollo mode.", "Confusing LUNA (a DAW) with UAD Console (Apollo's mixer software)."], "scenario_contexts": ["Starting a new song project in LUNA.", "Recording through Apollo preamps inside LUNA.", "Using LUNA on Windows with an ASIO interface."], "formula_symbolic": "", "formula_words": ""}, {"id": "25b72370-3e0f-48e5-8dcf-eb655b4f89e9", "term": "LUNA ARM", "definition": "LUNA ARM refers to Accelerated Realtime Monitoring as implemented in Universal Audio, Inc.'s LUNA recording system: a deep hardware, DSP, and software integration that lets users record through UAD plug-ins at the lowest possible latency, available in Apollo mode only. ARM in LUNA replaces the need to use UAD Console for low-latency tracking and input monitoring, handles channel muting automatically, and supports accelerated tracks plus up to two DSP-accelerated aux buses.", "plain_english": "LUNA ARM is Universal Audio's real-time monitoring feature inside LUNA. ARM stands for Accelerated Realtime Monitoring. It sends your recording signal through the Apollo interface's chips. This lets you hear UAD effects with almost no delay as you record.", "purpose_function": "It builds low-latency, DSP-accelerated monitoring directly into LUNA, so no separate Console app is needed for tracking.", "practical_application": "A user enables ARM in LUNA to track a vocal through UAD plug-ins with no noticeable monitoring delay.", "category": "Monitoring Workflow", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["Apollo Mode", "ARM-Enabled Track", "ARM-Enabled Bus", "ARM Automatic Plug-In Conversion", "LUNA"], "common_mistakes": ["Trying to use ARM in Core Audio or ASIO mode, when it works only in Apollo mode.", "Expecting native AU or VST3 plug-ins to monitor through ARM; only UAD DSP plug-ins do.", "Thinking ARM still requires opening UAD Console; ARM replaces that step in LUNA."], "scenario_contexts": ["Enabling ARM before recording a live take.", "Monitoring through a DSP reverb bus during tracking.", "Switching off ARM to use native plug-ins on armed tracks."], "formula_symbolic": "", "formula_words": ""}, {"id": "33d6a154-ff6e-4e9b-b25b-cf20087beb2d", "term": "LUNA Apollo Mode", "definition": "LUNA Apollo mode is the state of Universal Audio, Inc.'s LUNA recording system when it is connected to and integrated directly with a Thunderbolt Apollo interface. In this mode LUNA automatically accesses all of the Apollo's inputs, outputs, preamps, and Unison inserts, and Apollo-only features (Accelerated Realtime Monitoring and Unison preamp modeling) become available; these features are not offered when LUNA runs in Core Audio or ASIO mode.", "plain_english": "LUNA Apollo mode is when Universal Audio's LUNA software is linked to an Apollo interface. LUNA then controls the Apollo's inputs, outputs, and preamps directly. Special tools like Unison and ARM turn on. Without an Apollo, LUNA runs in a more basic mode.", "purpose_function": "It is the mode that unlocks Apollo's tight hardware integration, including Unison and ARM, inside LUNA.", "practical_application": "With an Apollo connected, a user works in LUNA Apollo mode to set Unison preamps and monitor through ARM.", "category": "Recording System", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["Apollo Mode", "LUNA", "LUNA ARM", "Apollo", "Console Tracking Mode"], "common_mistakes": ["Assuming LUNA is always in Apollo mode, when without an Apollo it uses Core Audio or ASIO.", "Expecting Unison or ARM in non-Apollo modes, when they require Apollo mode.", "Confusing the LUNA software mode with an Apollo hardware button."], "scenario_contexts": ["Opening LUNA with a Thunderbolt Apollo attached.", "Losing Unison after switching LUNA to a Core Audio device.", "Setting up ARM monitoring in an Apollo-mode LUNA session."], "formula_symbolic": "", "formula_words": ""}, {"id": "5ffa5330-5fde-46ba-bd15-f86f6658a5e8", "term": "LUNA Console Emulation", "definition": "A type of LUNA Extension from Universal Audio that models the channel-strip and bus-summing behavior of a classic analog mixing console inside the LUNA recording system. The current example, the API Vision Console Emulation, recreates the signal path, EQ, dynamics, and summing of API's Vision-style desks. The name references API's hardware; the underlying method is analog console circuit emulation, not a UA-invented console.", "plain_english": "This is an add-on for Universal Audio's LUNA program. It makes your mix sound like it went through a classic analog mixing desk. It copies the tone, EQ, and blending of a real console. The current one is modeled on API consoles.", "purpose_function": "It applies the color, EQ, dynamics, and summing character of a hardware console to every track and the mix bus without owning the physical desk.", "practical_application": "A mixer enables the console emulation across a LUNA session so each channel and the stereo bus take on the modeled desk's tone and gain-stage behavior.", "category": "Analog Emulation", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["LUNA Extension", "LUNA Summing Extension", "LUNA Recording System", "LUNA Pro", "LUNA Tape Extension"], "common_mistakes": ["Thinking it is a plug-in usable in any DAW; Extensions run only inside LUNA", "Assuming UA designed the console, when the model recreates another maker's (API) circuit", "Confusing console emulation with tape or summing emulation"], "scenario_contexts": ["Mixing a rock session in LUNA with the API Vision console emulation for cohesive glue", "Adding console channel color to individual tracks during arrangement"], "formula_symbolic": "", "formula_words": ""}, {"id": "10ad4974-dd75-444a-ac93-92013598f709", "term": "LUNA Extension", "definition": "Universal Audio's term for optional analog-emulation add-ons that run exclusively inside the LUNA recording system, integrated directly into its mixer and signal flow. Extensions fall into categories such as tape (multitrack and mastering), console summing, and full console channel emulation. Many are modeled on named third-party hardware (Studer, Ampex, Neve, API), so the Extension emulates that maker's circuit rather than being a UA-original design.", "plain_english": "An Extension is an add-on that works only inside Universal Audio's LUNA program. It adds analog gear sound, like tape machines or mixing consoles, straight into your tracks. Some copy famous hardware from other brands. They are built into LUNA, not used as normal plug-ins.", "purpose_function": "Extensions bring analog tape and console character into the LUNA workflow with tight, built-in integration that ordinary plug-ins do not offer.", "practical_application": "An engineer enables a tape or console Extension on tracks or buses in LUNA to color the sound during tracking and mixing.", "category": "Analog Emulation", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["LUNA Recording System", "LUNA Tape Extension", "LUNA Summing Extension", "LUNA Console Emulation", "LUNA Pro", "UAD-2"], "common_mistakes": ["Trying to load an Extension in Pro Tools or another DAW; they only run in LUNA", "Assuming all Extensions are UA inventions rather than models of other makers' gear", "Confusing Extensions with standard UAD plug-ins"], "scenario_contexts": ["Adding a Studer tape Extension across a drum bus in LUNA", "Enabling a Neve summing Extension on the mix bus"], "formula_symbolic": "", "formula_words": ""}, {"id": "6bc0b6fb-512e-4fe7-a046-6102e54df333", "term": "LUNA Pro", "definition": "A paid tier and bundle of Universal Audio's LUNA recording system that unlocks a collection of premium Extensions, virtual instruments, and UAD plug-ins beyond the free base DAW. It includes items such as the API Vision console channel strip, tape-machine emulations (Ampex, Studer, Oxide), several instruments, ARA editing tools, and a set of UAD plug-ins. LUNA itself is offered free; LUNA Pro is the optional upgrade.", "plain_english": "LUNA is Universal Audio's free recording program. LUNA Pro is a paid upgrade. It unlocks extra add-ons like console and tape emulations, virtual instruments, and many plug-ins. You buy it to get more tools inside LUNA.", "purpose_function": "It bundles LUNA's premium analog emulations, instruments, and effects so users can expand the free DAW into a fuller production suite in one purchase.", "practical_application": "A producer buys LUNA Pro to get the API console, tape machines, instruments, and mixing plug-ins together instead of buying each separately.", "category": "DAW / Recording System", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["LUNA Recording System", "LUNA Extension", "LUNA Console Emulation", "LUNA Tape Extension", "LUNA Summing Extension"], "common_mistakes": ["Thinking LUNA requires a paid license to run; the base DAW is free", "Believing LUNA Pro is separate software rather than an upgrade bundle", "Assuming Pro extensions work outside LUNA"], "scenario_contexts": ["Upgrading a free LUNA install to Pro to access the API console and tape machines", "Choosing LUNA Pro to get bundled instruments for songwriting"], "formula_symbolic": "", "formula_words": ""}, {"id": "ee1ce958-aaa8-4c75-8e71-e9e0df34af59", "term": "LUNA Recording System", "definition": "Universal Audio's digital audio workstation (DAW) and recording environment for recording, MIDI, editing, arranging, and mixing, designed to integrate tightly with UA's Apollo interfaces and UAD DSP. In Apollo mode it auto-configures inputs, outputs, preamp and Unison settings and offers accelerated realtime monitoring for low-latency tracking through UAD plug-ins; it also supports Core Audio and ASIO devices. It hosts LUNA Extensions and instruments.", "plain_english": "LUNA is Universal Audio's recording program, a type of DAW (digital audio workstation). You use it to record, edit, arrange, and mix music. It works closely with UA's Apollo audio interfaces. That link lets you record through effects with very low delay.", "purpose_function": "It gives UA hardware owners a DAW built around their Apollo interface and UAD processing, streamlining low-latency tracking and analog-style mixing.", "practical_application": "An engineer records a band in LUNA using an Apollo interface, monitoring through UAD plug-ins in real time and mixing with Extensions.", "category": "DAW / Recording System", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["LUNA Extension", "LUNA Pro", "Unison Insert", "UAD-2", "UAD Record FX"], "common_mistakes": ["Thinking LUNA only runs on UA hardware; it also supports Core Audio and ASIO devices", "Assuming it is just a control app rather than a full DAW", "Confusing LUNA the DAW with the individual Extensions that run inside it"], "scenario_contexts": ["Tracking vocals in LUNA through an Apollo with Unison preamp models", "Building a MIDI arrangement in LUNA before mixing"], "formula_symbolic": "", "formula_words": ""}, {"id": "8ac3de4e-127c-4112-aa24-1b04f6e85cea", "term": "LUNA Summing Extension", "definition": "A category of LUNA Extension that emulates the analog bus-summing stage of a classic mixing console, applying that summing amp's tone and harmonic character to the LUNA mix bus. Examples include Neve Summing, modeling the 80-series console summing, and API Summing, modeling the API 2520 op-amp and output-transformer summing amps. The names reference Neve and API hardware; the method is analog summing-amplifier emulation.", "plain_english": "This LUNA add-on copies how an analog console blends many tracks into a stereo mix. That blending stage adds subtle tone and warmth. The models are based on Neve and API console circuits. It runs on the mix bus inside LUNA.", "purpose_function": "It recreates the subtle coloration and glue of hardware console summing so an in-the-box mix gains analog character.", "practical_application": "A mixer places a summing Extension on the LUNA stereo bus to add Neve- or API-style harmonic color to the full mix.", "category": "Analog Emulation", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["LUNA Extension", "LUNA Console Emulation", "LUNA Tape Extension", "LUNA Recording System", "LUNA Pro"], "common_mistakes": ["Expecting a dramatic change; summing coloration is subtle", "Thinking summing emulation replaces a full console channel strip", "Assuming UA invented the summing circuit rather than modeling Neve/API"], "scenario_contexts": ["Adding API summing on the mix bus for punch", "Using Neve summing to glue a dense mix"], "formula_symbolic": "", "formula_words": ""}, {"id": "d12687c1-9bc4-4668-8815-17c7c288f1a1", "term": "LUNA Tape Extension", "definition": "A category of LUNA Extension that emulates analog magnetic-tape recording, adding tape saturation, compression, and frequency shaping to tracks or buses within LUNA. Examples include Oxide Tape (included), the Studer A800 multitrack, and the Ampex ATR-102 mastering tape, with controls for tape formula, speed, and calibration. The Studer and Ampex names reference those makers' machines; the method is magnetic-tape emulation.", "plain_english": "This LUNA add-on makes tracks sound like they were recorded to analog tape. Tape adds gentle warmth, saturation, and smoothing. The models copy real machines like Studer and Ampex. You can set tape type, speed, and calibration.", "purpose_function": "It brings the saturation, head-bump, and gentle compression of tape machines into LUNA without needing a physical tape deck.", "practical_application": "An engineer runs drums or the mix bus through the tape Extension in LUNA to add analog saturation and cohesion.", "category": "Analog Emulation", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["LUNA Extension", "LUNA Summing Extension", "LUNA Console Emulation", "LUNA Recording System", "LUNA Pro"], "common_mistakes": ["Overdriving the virtual tape and adding unwanted distortion", "Assuming tape speed changes playback pitch; here it shapes tone and head-bump", "Assuming UA built the tape machine circuit rather than modeling Studer/Ampex"], "scenario_contexts": ["Printing a drum bus through Studer A800 emulation in LUNA", "Mastering a stereo mix through the Ampex ATR-102 tape Extension"], "formula_symbolic": "", "formula_words": ""}, {"id": "3aec6667-b9d4-44de-a24d-d7bc6c2884e1", "term": "UAD DSP Accelerator", "definition": "Universal Audio's general product category for hardware that provides dedicated digital signal processing (DSP) power to run UAD Powered Plug-Ins, offloading that processing from the host computer's CPU. Accelerators use SHARC DSP chips and ship as PCIe cards or Satellite units (Thunderbolt, USB, or legacy FireWire) in configurations from SOLO to OCTO; Apollo interfaces contain the same onboard DSP.", "plain_english": "This is Universal Audio hardware that adds extra processing power to your computer. It runs UA's plug-ins on its own chips, called DSP (digital signal processing). That frees up your computer's main processor. It comes as a card or an external box.", "purpose_function": "It lets users run many UAD plug-ins with low latency without overloading the host CPU, expanding the effect count on large sessions.", "practical_application": "An engineer adds a UAD accelerator so a big mix can run more UA compressors, EQs, and reverbs than the computer alone could handle.", "category": "DSP Hardware", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["UAD-2", "UAD Record FX", "Unison Insert", "LUNA Recording System", "Unison-Enabled Plug-In"], "common_mistakes": ["Thinking it speeds up the whole computer; it only runs UAD plug-ins", "Assuming classic UAD plug-ins run without any UA DSP hardware or Apollo", "Equating the SHARC chip count directly with a fixed plug-in count"], "scenario_contexts": ["Adding a Satellite Thunderbolt accelerator to run more UAD reverbs", "Installing a PCIe UAD card in a studio tower for large mixes"], "formula_symbolic": "", "formula_words": ""}, {"id": "bafb3541-4fc6-4b0f-88fd-fd7e93188dec", "term": "UAD MON", "definition": "In Universal Audio's Console monitoring software, the Insert Effects setting (MON) in which UAD plug-in processing on a channel's standard inserts is heard in the monitor mix but recorded dry — the DAW captures the unprocessed signal while the engineer monitors through the effects. It is the counterpart to the UAD REC setting.", "plain_english": "UAD MON is a setting in Universal Audio's Console software. It lets you hear UA effects while you record. But it does not save those effects into the recording. The recorded track stays clean, or dry.", "purpose_function": "It lets performers monitor through effects like reverb or compression for a better feel while keeping the recorded file unprocessed for flexibility later.", "practical_application": "A singer hears reverb and compression while tracking, but the engineer keeps the recording dry by using the MON setting.", "category": "Signal Routing", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["UAD REC", "UAD Record FX", "Unison Insert", "UAD-2", "LUNA Recording System"], "common_mistakes": ["Assuming MON prints the effects; it records dry", "Forgetting that Unison and auxiliary inserts still print regardless of the MON setting", "Confusing monitor-only effects with the recorded file"], "scenario_contexts": ["Tracking a vocalist with monitor reverb but a dry recording", "Letting a guitarist hear an amp model while keeping the DI clean"], "formula_symbolic": "", "formula_words": ""}, {"id": "5de2cead-e66a-4a7b-ae53-34c5a751603b", "term": "UAD REC", "definition": "In Universal Audio's Console software, the Insert Effects setting (REC) in which UAD plug-in processing on a channel's standard inserts is both heard and printed (recorded wet) into the DAW file. It is the counterpart to UAD MON, which records the signal dry.", "plain_english": "UAD REC is a setting in Universal Audio's Console software. It records UA effects right into your track. So the saved file already has the compression, EQ, or amp tone baked in. You both hear and keep the effects.", "purpose_function": "It lets engineers commit real-time UAD processing to the recording, saving DSP later and locking in a chosen sound at the source.", "practical_application": "An engineer prints a UA preamp, compressor, and EQ onto a vocal take by setting Insert Effects to REC.", "category": "Signal Routing", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["UAD MON", "UAD Record FX", "Unison Insert", "UAD-2", "Unison-Enabled Plug-In"], "common_mistakes": ["Printing effects you cannot undo later, then wanting them removed", "Forgetting REC records the processed (wet) signal permanently", "Confusing REC with simply monitoring through effects"], "scenario_contexts": ["Committing an analog-modeled preamp and compressor to a vocal at tracking", "Printing a guitar amp model to save DSP during mixdown"], "formula_symbolic": "", "formula_words": ""}, {"id": "6b46825c-d00b-4b2a-9f0d-8c44206939e7", "term": "UAD Record FX", "definition": "In LUNA and UA Console, the dedicated 'Record FX' insert slots whose UAD plug-in processing is committed (printed) to the recorded file, as opposed to standard monitor inserts that are heard but not recorded. Up to four UAD plug-ins can be placed in a channel's Record FX inserts, and Record FX and Unison-insert processing are always recorded.", "plain_english": "Record FX are special effect slots in Universal Audio's software. Any UA plug-in placed here gets saved into the recording. Other insert slots let you listen without saving the effect. Use Record FX when you want the sound baked in.", "purpose_function": "It gives engineers a clear place to load effects that should be printed to the take, separating recorded processing from monitor-only processing.", "practical_application": "A producer loads a preamp and compressor into a channel's Record FX inserts so those effects are captured in the recorded file.", "category": "Signal Routing", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["UAD REC", "UAD MON", "Unison Insert", "LUNA Recording System", "Unison-Enabled Plug-In"], "common_mistakes": ["Placing effects in monitor inserts and expecting them to be recorded", "Overprocessing at the Record FX stage with no way to undo", "Forgetting that Record FX and Unison inserts always print"], "scenario_contexts": ["Printing UA effects to a vocal by loading them in Record FX in LUNA", "Committing an amp model to a guitar DI at tracking"], "formula_symbolic": "", "formula_words": ""}, {"id": "26f33450-9887-44a0-bf85-80eceba29b7a", "term": "UAD-2", "definition": "The second-generation UAD (Universal Audio Digital) hardware platform, a SHARC-based DSP accelerator line that runs UAD Powered Plug-Ins. Introduced in 2008 as the successor to the original UAD-1, it spans PCIe cards and Satellite units (FireWire, Thunderbolt, USB) in SOLO/DUO/QUAD/OCTO chip counts; the same UAD-2 DSP is built into Apollo interfaces. 'UAD-2' is a trademark of Universal Audio, Inc.", "plain_english": "UAD-2 is the second version of Universal Audio's DSP hardware. DSP means digital signal processing. It uses special chips to run UA's plug-ins. It comes as cards or boxes, and the same chips sit inside Apollo interfaces.", "purpose_function": "It provides the dedicated processing that powers UA's plug-in library, letting engineers run analog-modeled effects with consistent, low-latency performance.", "practical_application": "A studio uses a UAD-2 accelerator or an Apollo interface to run UA plug-ins during tracking and mixing without taxing the computer.", "category": "DSP Hardware", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["UAD DSP Accelerator", "UAD Record FX", "Unison Insert", "LUNA Recording System", "Unison-Enabled Plug-In"], "common_mistakes": ["Confusing the UAD-2 hardware with the UAD plug-in software that runs on it", "Thinking classic UAD plug-ins run natively without UAD-2 or Apollo DSP", "Assuming UAD-2 and the older UAD-1 are interchangeable"], "scenario_contexts": ["Running vintage-modeled compressors on a UAD-2 Satellite", "Recognizing an Apollo's onboard UAD-2 DSP when loading Console inserts"], "formula_symbolic": "", "formula_words": ""}, {"id": "ab43e72a-3e73-4567-9cd7-d234ac43a903", "term": "Unison Analog/Digital Integration", "definition": "Universal Audio's name for the core mechanism of Unison: a bidirectional link between an Apollo interface's analog mic-preamp hardware and a Unison-enabled digital plug-in. The plug-in reconfigures the preamp's physical input impedance and gain-staging to match the modeled hardware, and the front-panel and plug-in controls track each other. It is UA's method of merging analog hardware with digital modeling; the modeled circuits (Neve, API, and others) belong to other makers.", "plain_english": "This is how Universal Audio joins real analog preamps with digital models. A Unison plug-in changes the Apollo preamp's actual electronics to match a classic preamp. The knobs on the hardware and the software move together. So the digital model and the real circuit act as one.", "purpose_function": "It lets a digital model control real analog input electronics (impedance and gain stages) so an interface preamp behaves like the emulated hardware, not just copies its EQ curve.", "practical_application": "When a Unison preamp plug-in loads, it switches the Apollo's input impedance and gain response so mics and instruments react as they would into the modeled preamp.", "category": "Preamp Modeling", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["Unison Insert", "Unison-Enabled Plug-In", "UAD-2", "LUNA Recording System", "UAD Record FX"], "common_mistakes": ["Thinking Unison is only a software EQ; it also switches real hardware input impedance", "Assuming it works on any interface, when it needs Apollo hardware", "Believing UA designed the modeled preamps rather than emulating other brands"], "scenario_contexts": ["Loading a Neve preamp model that changes the Apollo's input impedance for a ribbon mic", "Matching the gain and clipping behavior of a vintage preamp during tracking"], "formula_symbolic": "", "formula_words": ""}, {"id": "ece23367-cff5-47b6-8f16-5997a3cc2cdd", "term": "Unison Insert", "definition": "The dedicated first insert slot on each Apollo mic-preamp (and Hi-Z) channel in UA Console, reserved for Unison-enabled plug-ins. Loading a plug-in here activates Unison's hardware integration — switching the preamp's physical input impedance and gain staging — and its processing is always recorded regardless of the REC/MON setting.", "plain_english": "The Unison insert is a special first effect slot on Apollo's preamp channels. Only Unison plug-ins go there. Loading one changes the real preamp electronics to match a classic model. Whatever you put here always gets recorded.", "purpose_function": "It provides the single point where a Unison plug-in takes control of the analog preamp, ensuring the model shapes the sound at the very front of the signal chain.", "practical_application": "An engineer drops a Unison preamp model into the Unison insert so the mic hits the modeled preamp before any other processing.", "category": "Preamp Modeling", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["Unison-Enabled Plug-In", "Unison Analog/Digital Integration", "UAD REC", "UAD MON", "LUNA Recording System"], "common_mistakes": ["Trying to load a non-Unison plug-in in the Unison slot", "Expecting the Unison insert to follow the MON setting; it always records", "Thinking every insert on the channel is a Unison insert, when only the first is"], "scenario_contexts": ["Placing an API preamp model in the Unison insert of a preamp channel", "Setting input impedance for a ribbon mic via the Unison-inserted model"], "formula_symbolic": "", "formula_words": ""}, {"id": "7f0c8c1b-fe7b-4128-ad1a-655f21d1fe63", "term": "Unison-Enabled Plug-In", "definition": "A specially coded UAD plug-in — typically a mic-preamp, guitar-amp, or pedal emulation — that can load in Apollo's Unison insert and control the interface's analog preamp hardware, including input impedance, gain staging, and clipping behavior. Only these plug-ins activate Unison; ordinary UAD plug-ins do not. Most model named third-party hardware (Neve, API, Manley, guitar amps), so the plug-in emulates that maker's circuit.", "plain_english": "A Unison-enabled plug-in is a special Universal Audio effect. It can go in Apollo's Unison slot and change the real preamp hardware. Normal plug-ins cannot do this. Most copy famous preamps, guitar amps, or pedals.", "purpose_function": "These plug-ins carry the extra coding needed to reconfigure Apollo's analog input stage, so the interface truly behaves like the modeled preamp or amp.", "practical_application": "An engineer loads a Unison-enabled preamp or amp plug-in to make the Apollo's input match a classic device for a mic or guitar.", "category": "Preamp Modeling", "difficulty": "intermediate", "achievement_id": "79ef147c-15ec-458b-9a53-f4f0cd7aa6e9", "cross": [], "related_terms": ["Unison Insert", "Unison Analog/Digital Integration", "UAD-2", "UAD Record FX", "LUNA Recording System"], "common_mistakes": ["Assuming any UAD plug-in is Unison-enabled, when only specific ones are", "Trying to get the same hardware effect from a non-Unison insert", "Thinking UA created the modeled amps/preamps rather than emulating other makers"], "scenario_contexts": ["Choosing a Unison-enabled amp model for a guitar DI into Apollo", "Selecting a Unison-enabled preamp to change input impedance for a dynamic mic"], "formula_symbolic": "", "formula_words": ""}, {"id": "f5150608-3e6e-40a3-b229-3f5dc6d1df27", "term": "Abbey Road Studio 3", "definition": "Abbey Road Studio 3 is a Waves Audio Nx-based headphone plugin that models the control room and monitoring of Studio 3 at Abbey Road Studios in London. It emulates near-field, mid-field and far-field speaker types in stereo and adds 5.1 and 7.1 surround components, using binaural rendering with optional head tracking and headphone EQ correction. The Abbey Road name and the Waves and Nx names are trademarks of their respective owners; the underlying method is generic binaural/HRTF room and speaker emulation.", "plain_english": "This plugin makes headphones sound like the control room of Abbey Road's Studio 3. You can pick different virtual speakers, from small desk monitors to large ones. It models how sound would reach your ears in that room. It lets you reference a famous studio from anywhere.", "purpose_function": "It gives engineers a portable, consistent monitoring reference by recreating a specific well-known control room over headphones, so mixes made on headphones translate more reliably.", "practical_application": "A technician inserts it on the monitor or master path to reference a mix on headphones as if sitting in Studio 3, choosing near, mid or far virtual speakers.", "category": "Room Emulation", "difficulty": "intermediate", "achievement_id": "d1d8da5d-3520-4dbc-8889-e524a536d00b", "cross": [], "related_terms": ["Waves Nx", "Nx Virtual Mix Room", "Nx Head Tracker", "Nx Headphone EQ Correction", "Binaural Rendering", "HRTF (Head-Related Transfer Function)"], "common_mistakes": ["Treating the emulated room as a full replacement for an acoustically treated control room rather than a headphone reference", "Leaving the plugin active on the final bounce, which prints the binaural processing into the mix", "Skipping the head-measurement settings, which lowers the accuracy of the spatial rendering", "Switching virtual speakers mid-mix and forgetting which model the balance decisions were made on"], "scenario_contexts": ["Referencing a stereo mix on headphones while travelling, using the Studio 3 model instead of an untreated room", "Comparing how a mix sits on the emulated near-field versus far-field speakers before committing", "Checking a 5.1 or 7.1 surround balance on headphones when no surround room is available"], "formula_symbolic": "", "formula_words": ""}, {"id": "d65c1c77-af7e-4fe2-b6d9-194031dfacac", "term": "CLA Nx", "definition": "CLA Nx is a Waves Audio Nx-based headphone plugin that models the monitoring environment of mixing engineer Chris Lord-Alge's (CLA) control room. It uses binaural rendering with optional head tracking and headphone EQ correction to reproduce that room's speakers over stereo headphones. The CLA and Waves and Nx names are trademarks of their respective owners; the underlying method is generic binaural/HRTF room emulation.", "plain_english": "This plugin makes headphones sound like the mixing room of engineer Chris Lord-Alge. It places his room's speakers around you using ear-and-room modeling. Head tracking can keep the sound in place as you move. It lets you borrow a pro room's sound on any headphones.", "purpose_function": "It exists so engineers can reference a known professional mix room over headphones, giving a trusted monitoring starting point when a treated room is not available.", "practical_application": "A technician loads CLA Nx on the monitor path to mix or check translation on headphones as if in Chris Lord-Alge's control room.", "category": "Room Emulation", "difficulty": "intermediate", "achievement_id": "d1d8da5d-3520-4dbc-8889-e524a536d00b", "cross": [], "related_terms": ["Waves Nx", "Nx Virtual Mix Room", "Abbey Road Studio 3", "Nx Head Tracker", "Nx Headphone EQ Correction", "Binaural Rendering"], "common_mistakes": ["Assuming the plugin reproduces Chris Lord-Alge's mixing decisions rather than just his room's monitoring", "Relying on it for final critical decisions instead of an acoustically treated room", "Leaving the plugin active on the exported mix", "Not setting personal head measurements, reducing spatial accuracy"], "scenario_contexts": ["Mixing on headphones on the road while wanting a familiar pro-room reference", "Checking whether a rock or pop balance holds up against a known mix-room sound", "Referencing a mix late at night on headphones without disturbing others"], "formula_symbolic": "", "formula_words": ""}, {"id": "859c278b-816d-4d4d-9751-46756cc67ccb", "term": "Nx Germano Studios", "definition": "Nx Germano Studios New York is a Waves Audio Nx-based headphone plugin that models the control room and monitoring of Germano Studios in New York (formerly The Hit Factory). It uses binaural rendering with optional head tracking and headphone EQ correction to reproduce that room's speakers over stereo headphones. The Germano Studios and Waves and Nx names are trademarks of their respective owners; the underlying method is generic binaural/HRTF room emulation.", "plain_english": "This plugin makes headphones sound like the control room of Germano Studios in New York. It uses ear-and-room modeling to place that room's speakers around you. Head tracking can hold the sound steady as you turn. It lets you reference a famous New York room anywhere.", "purpose_function": "It gives engineers a portable headphone reference based on a specific renowned control room, so mixes made on headphones translate more predictably.", "practical_application": "A technician inserts it on the monitor or master bus to reference a mix on headphones as if in the Germano Studios control room.", "category": "Room Emulation", "difficulty": "intermediate", "achievement_id": "d1d8da5d-3520-4dbc-8889-e524a536d00b", "cross": [], "related_terms": ["Waves Nx", "Nx Virtual Mix Room", "Nx Ocean Way Nashville", "Nx Head Tracker", "Nx Headphone EQ Correction", "Binaural Rendering"], "common_mistakes": ["Treating the emulated room as a substitute for a properly treated listening space for final decisions", "Leaving the plugin engaged when bouncing the final file", "Ignoring the head-measurement controls that improve the spatial illusion", "Expecting it to change the mix's tone rather than its spatial monitoring"], "scenario_contexts": ["Referencing a mix on headphones while away from the main studio", "Cross-checking a balance against a specific New York room's monitoring character", "Working quietly on headphones overnight while keeping a pro-room reference"], "formula_symbolic": "", "formula_words": ""}, {"id": "41a33796-e24d-42a3-9043-8da4f8a15445", "term": "Nx Head Tracker", "definition": "The Nx Head Tracker is a small Bluetooth Low Energy hardware device from Waves Audio that clips to the top of headphones and reports the listener's head movement (left/right, up/down and tilt) to Nx plugins in real time. Nx uses this data to keep the virtual speakers and room fixed in space as the head moves, reinforcing the out-of-head illusion; it tracks at roughly 35 to 50 frames per second and can be combined with webcam tracking (sensor fusion). Waves and Nx are trademarks of Waves Audio Ltd.; the generic method is real-time head-tracking for binaural rendering.", "plain_english": "The Nx Head Tracker is a small clip-on sensor for your headphones. It sends your head movements to the Nx software over Bluetooth. As you turn your head, the virtual speakers stay in place instead of moving with you. This makes the fake studio room feel more real.", "purpose_function": "It exists to feed live head-position data to Nx so the virtual speakers stay anchored in the room, which strengthens the sense that the sound is outside the headphones.", "practical_application": "An engineer clips the tracker to the headband, pairs it over Bluetooth, points it forward at the screen, and re-centers it before mixing with an Nx plugin.", "category": "Monitoring Hardware", "difficulty": "intermediate", "achievement_id": "d1d8da5d-3520-4dbc-8889-e524a536d00b", "cross": [], "related_terms": ["Waves Nx", "Nx Virtual Mix Room", "Abbey Road Studio 3", "Binaural Rendering", "HRTF (Head-Related Transfer Function)", "Nx Headphone EQ Correction"], "common_mistakes": ["Mounting the tracker backwards, so 'forward' is offset or reversed from the screen", "Forgetting to re-center the tracker, leaving the virtual room pointing the wrong way", "Assuming head tracking is required, when Nx also works with webcam tracking or with tracking off", "Letting the tracker battery die and blaming the plugin for a frozen or drifting image"], "scenario_contexts": ["Clipping the tracker to headphones so a mix stays anchored when the engineer looks at faders or the screen", "Combining the tracker with the webcam (sensor fusion) for smoother, faster tracking", "Using the tracker during a long headphone mix session to keep monitoring stable"], "formula_symbolic": "", "formula_words": ""}, {"id": "5fa4fd3b-1212-4f50-8bec-94bbe073ff7e", "term": "Nx Headphone EQ Correction", "definition": "Nx Headphone EQ Correction is a feature in Waves Nx plugins that applies a model-specific equalization curve to compensate for the frequency-response irregularities of a selected headphone model, giving a more neutral (flatter) starting point for monitoring. The listener selects their exact headphone model from a menu; the curves are derived from precision third-party headphone measurement data, and the feature is intended only for models offered in that menu.", "plain_english": "Every headphone colors the sound a little. This feature flattens that coloring using a curve made for your exact headphone model. You pick your model from a list to switch it on. It only helps if your headphones are actually on that list.", "purpose_function": "It exists to remove a known headphone's built-in tonal bias so the Nx virtual monitoring starts from a flatter, more trustworthy reference before any mixing decisions.", "practical_application": "An engineer selects their headphone model from the plugin's menu so the correction neutralizes that model's response, then mixes or references through the corrected monitoring.", "category": "Headphone Calibration", "difficulty": "intermediate", "achievement_id": "d1d8da5d-3520-4dbc-8889-e524a536d00b", "cross": [], "related_terms": ["Waves Nx", "Nx Virtual Mix Room", "Abbey Road Studio 3", "Binaural Rendering", "HRTF (Head-Related Transfer Function)", "Nx Head Tracker"], "common_mistakes": ["Enabling a correction curve that does not match the headphones actually being worn, which adds error instead of removing it", "Expecting the feature to correct any headphone, when only listed models have curves", "Confusing headphone EQ correction (tonal) with the binaural room emulation (spatial)", "Leaving it on by default even when the exact headphone model is not in the menu"], "scenario_contexts": ["Selecting a listed studio headphone model so its bass or treble bump is flattened before mixing", "Using the EQ-only mode to hear just the tonal correction without the room emulation", "Turning correction off when working on a headphone model not covered by the menu"], "formula_symbolic": "", "formula_words": ""}, {"id": "9c22e5a0-b755-414f-8631-376d423202ee", "term": "Nx Ocean Way Nashville", "definition": "Nx Ocean Way Nashville is a Waves Audio Nx-based headphone plugin that models the control-room acoustics and monitoring of the Ocean Way Nashville studio. It uses binaural rendering with optional head tracking and headphone EQ correction to reproduce that room's speakers over stereo headphones. The Ocean Way Nashville and Waves and Nx names are trademarks of their respective owners; the underlying method is generic binaural/HRTF room emulation.", "plain_english": "This plugin makes headphones sound like the Ocean Way Nashville control room. It uses ear-and-room modeling to place that room's speakers around you. Head tracking can keep the sound anchored as you move. It lets you reference a top studio room on any headphones.", "purpose_function": "It gives engineers a portable headphone reference based on a specific renowned control room, helping headphone mixes translate more consistently to other systems.", "practical_application": "A technician inserts it on the monitor or master bus to reference a mix on headphones as if in the Ocean Way Nashville control room.", "category": "Room Emulation", "difficulty": "intermediate", "achievement_id": "d1d8da5d-3520-4dbc-8889-e524a536d00b", "cross": [], "related_terms": ["Waves Nx", "Nx Virtual Mix Room", "Nx Germano Studios", "Nx Head Tracker", "Nx Headphone EQ Correction", "Binaural Rendering"], "common_mistakes": ["Using the emulated room as a full replacement for a treated listening room on final decisions", "Leaving the plugin active when exporting the final mix", "Skipping the head-measurement settings that improve the spatial illusion", "Expecting a tonal change to the mix rather than a change in monitoring perspective"], "scenario_contexts": ["Referencing a mix on headphones while away from the studio", "Cross-checking a balance against a specific Nashville room's monitoring character", "Mixing quietly on headphones while keeping a pro-room reference"], "formula_symbolic": "", "formula_words": ""}, {"id": "4d65a7dd-ae50-4709-8c8b-b67b3ec0058c", "term": "Nx Virtual Mix Room", "definition": "Nx - Virtual Mix Room over Headphones is a Waves Audio plugin that emulates monitoring loudspeakers in a generic acoustically treated mix room using binaural rendering with optional head tracking. It supports mono, stereo, 5.0, 5.1 and 7.1 layouts plus first-order Ambisonics, folding them to binaural stereo at the headphone output, and includes room-ambience, head-modeling and headphone EQ correction controls. Waves and Nx are trademarks of Waves Audio Ltd.", "plain_english": "Nx Virtual Mix Room is a plugin that turns headphones into a virtual studio room. It places imaginary speakers around you and adds gentle room sound. If you use tracking, turning your head shifts the sound naturally. It gives a steadier reference than plain headphones.", "purpose_function": "It provides a portable, consistent monitoring reference by simulating speakers in a neutral treated room, so headphone mixes translate better than flat, in-head headphone listening.", "practical_application": "A technician loads it on the master or monitor bus to mix or reference stereo and surround material on headphones when a treated control room is not available.", "category": "Immersive Monitoring", "difficulty": "intermediate", "achievement_id": "d1d8da5d-3520-4dbc-8889-e524a536d00b", "cross": [], "related_terms": ["Waves Nx", "Nx Head Tracker", "Abbey Road Studio 3", "Nx Headphone EQ Correction", "Binaural Rendering", "HRTF (Head-Related Transfer Function)"], "common_mistakes": ["Leaving the plugin active on the final render, which prints the binaural processing into the mix", "Skipping the head circumference and inter-aural settings, reducing spatial accuracy", "Treating it as a full replacement for a treated room on final critical decisions", "Expecting stereo-only support, when it also handles 5.1, 7.1 and first-order Ambisonics"], "scenario_contexts": ["Mixing a stereo song on headphones in a hotel room while touring", "Monitoring a 5.1 or 7.1 surround mix on headphones when no surround room is available", "Checking a mix's balance and depth on headphones before moving to studio speakers"], "formula_symbolic": "", "formula_words": ""}, {"id": "50b4858c-1df9-4f25-90d9-cdc2f7f66408", "term": "Nx Virtual Studio Collection", "definition": "The Nx Virtual Studio Collection is a Waves Audio plugin bundle that packages the company's Nx room-emulation plugins together, including Nx - Virtual Mix Room, Abbey Road Studio 3, CLA Nx, Nx Germano Studios New York and Nx Ocean Way Nashville. Each plugin recreates a specific monitoring environment over stereo headphones using Nx binaural technology with optional head tracking and headphone EQ correction. Waves and Nx are trademarks of Waves Audio Ltd.", "plain_english": "The Nx Virtual Studio Collection is a bundle of Waves' headphone room plugins. Each one copies the sound of a different famous studio room. You get several rooms to compare on the same headphones. It lets you reference more than one pro space from anywhere.", "purpose_function": "It exists to give engineers several trusted virtual monitoring rooms in one package, so they can cross-check a mix against different well-known control-room sounds on headphones.", "practical_application": "A technician buys the collection to A/B a mix across the Virtual Mix Room, Abbey Road Studio 3 and other Nx rooms on headphones during mixing.", "category": "Plugin Bundle", "difficulty": "intermediate", "achievement_id": "d1d8da5d-3520-4dbc-8889-e524a536d00b", "cross": [], "related_terms": ["Waves Nx", "Nx Virtual Mix Room", "Abbey Road Studio 3", "CLA Nx", "Nx Germano Studios", "Nx Ocean Way Nashville"], "common_mistakes": ["Assuming the bundle is a single plugin rather than several separate Nx room plugins", "Switching between rooms so often that no single reference is used to make final decisions", "Relying on the emulated rooms instead of a treated space for final critical listening", "Forgetting that each included plugin still needs head measurements set for best results"], "scenario_contexts": ["Comparing a mix across several virtual studio rooms to see which balance holds up best", "Choosing one room from the collection as a consistent headphone reference for a project", "Referencing multiple famous control-room sounds while working away from the studio"], "formula_symbolic": "", "formula_words": ""}, {"id": "4a871b1f-8242-4b70-8bfc-42654b39f493", "term": "Waves Nx", "definition": "Waves Nx is a headphone monitoring technology and plugin family from Waves Audio Ltd. that uses binaural processing based on head-related transfer functions (HRTF), together with optional real-time head tracking, to simulate listening to loudspeakers in an acoustically treated room over ordinary stereo headphones. It underlies several products (including the Nx Virtual Mix Room and studio-specific plugins) and supports mono, stereo, 5.0, 5.1 and 7.1 inputs plus first-order Ambisonics, rendering them to binaural stereo. Waves and Nx are trademarks of Waves Audio Ltd.; the core method is generic binaural/HRTF rendering with head tracking.", "plain_english": "Waves Nx is technology that makes headphones sound like studio speakers in a real room. It uses a model of how your ears hear sound coming from around you. A tracker can follow your head so the sound stays put as you turn. This helps you judge a mix without a treated studio.", "purpose_function": "It exists so engineers can make more reliable monitoring judgments on headphones by recreating the spatial cues of speakers in a room, cues that flat headphone listening does not provide.", "practical_application": "An engineer inserts an Nx plugin on the monitor or master path to mix or check translation on headphones when a proper control room is not available.", "category": "Immersive Monitoring", "difficulty": "intermediate", "achievement_id": "d1d8da5d-3520-4dbc-8889-e524a536d00b", "cross": [], "related_terms": ["Nx Virtual Mix Room", "Nx Head Tracker", "Abbey Road Studio 3", "Nx Headphone EQ Correction", "Binaural Rendering", "HRTF (Head-Related Transfer Function)"], "common_mistakes": ["Assuming Nx replaces an acoustically treated room for final critical decisions rather than supplementing headphone monitoring", "Skipping the head-measurement settings, which lowers the accuracy of the binaural rendering", "Leaving Nx active on the final render, which prints the binaural processing into the mix", "Confusing the Nx technology platform with any single plugin; it underlies several products"], "scenario_contexts": ["Mixing on headphones in a hotel room while touring, using Nx to approximate control-room monitoring", "Checking a stereo mix's balance and depth on headphones before committing on speakers", "Monitoring a 5.1 or 7.1 surround mix on headphones when no surround room is available"], "formula_symbolic": "", "formula_words": ""}, {"id": "44a95a3d-b02c-422d-ab4e-442c1cdc4534", "term": "Axis One", "definition": "Axis One is a purpose-built computer made by Waves Audio Ltd. and optimized to run the company's live-sound software, chiefly the eMotion LV1 mixer and SuperRack SoundGrid. It ships as a rack-mountable workstation running an embedded Long-Term Servicing Channel build of Windows so that its configuration stays stable for touring and installed use. The Axis One name is a Waves trademark; the underlying concept is a general-purpose x86 audio workstation tuned for real-time audio.", "plain_english": "Axis One is a computer built by Waves to run their live mixing software. It is tuned so the software runs smoothly and reliably at a show. It uses a locked-down version of Windows to avoid surprise changes. Think of it as a road-ready PC made just for mixing.", "purpose_function": "It exists to give engineers a known, tested computer for Waves live software, reducing the setup and reliability problems that come from using an untested off-the-shelf machine.", "practical_application": "A live engineer runs eMotion LV1 or SuperRack on an Axis One in the rack, trusting it as a stable, vendor-supported host for the show.", "category": "Live Sound Hardware", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["eMotion LV1", "SuperRack SoundGrid", "SoundGrid", "SoundGrid DSP Server", "FIT Controller"], "common_mistakes": ["Assuming Axis One does the plugin processing itself, when heavy DSP still runs on a SoundGrid server", "Updating or reconfiguring the embedded Windows build like a normal PC and breaking the tested setup", "UNSAFE: powering the unit down with the rack power switch instead of shutting down through Windows, risking data loss", "Treating it as required, when Waves software can also run on other qualified computers"], "scenario_contexts": ["Running eMotion LV1 for front-of-house on a touring rig with a vendor-supported computer", "Hosting SuperRack SoundGrid in a broadcast rack that must not crash mid-show", "Standardizing on one known computer model across multiple rental systems"], "formula_symbolic": "", "formula_words": ""}, {"id": "50726f7f-4340-473a-b9ba-8f8a2e90906d", "term": "FIT Controller", "definition": "The FIT Controller is a hardware control surface made by Waves Audio Ltd. that gives tactile, hands-on control of the eMotion LV1 mixer and SuperRack SoundGrid. It provides 16 channel faders plus one master fader (16+1), all 100 mm and motorized, along with scribble-strip displays, rotary encoders, fader layers, and Mute/Solo/Select and user-assignable buttons. The FIT name is a Waves trademark; the underlying concept is a generic motorized-fader control surface for a software mixer.", "plain_english": "The FIT Controller is a box of real faders and knobs for the Waves LV1 mixer. It lets you mix with your hands instead of a mouse. The faders move on their own to match the software. Its small screens show each channel's name.", "purpose_function": "It exists so engineers can mix an on-screen Waves console with physical faders and buttons, which is faster and more reliable than mouse control during a live show.", "practical_application": "A front-of-house or monitor engineer connects one or two FIT units to an LV1 or SuperRack system and rides levels, mutes, and plugin parameters by hand.", "category": "Live Sound Hardware", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["eMotion LV1", "eMotion LV1 Classic", "SuperRack SoundGrid", "Axis One", "MyMon"], "common_mistakes": ["Thinking the FIT is a standalone mixer, when it only controls LV1 or SuperRack software", "Forgetting the faders are motorized and fighting them by hand during a layer change", "Overlooking that up to two FIT units can be linked for 32+2 faders in current software", "Confusing its fader layers, so channels appear to be on the wrong strips"], "scenario_contexts": ["Adding physical faders to an LV1 system for hands-on monitor mixing", "Linking two FIT controllers to cover more channels on a large festival input list", "Assigning encoders to control plugin parameters live from the surface"], "formula_symbolic": "", "formula_words": ""}, {"id": "18e359cf-d49a-4946-bccd-9c8e3904a2d7", "term": "MyMon", "definition": "MyMon is a free personal monitor mixing app from Waves Audio Ltd. for iOS and Android devices that lets a performer control their own monitor or in-ear mix on an eMotion LV1 system. Communicating with the mixer over Wi-Fi, it lets the musician adjust input levels, mute channels, pan, apply post-fader EQ, and group inputs under a single fader. The MyMon name is a Waves trademark; the underlying concept is a generic personal-monitor remote-control app over a wireless network.", "plain_english": "MyMon is a phone or tablet app for musicians on stage. It lets each player set their own headphone or wedge mix. They can turn instruments up or down over Wi-Fi. This frees the sound engineer from making every small monitor change.", "purpose_function": "It exists to give performers direct control of what they hear on stage, offloading routine monitor tweaks from the monitor engineer and speeding up soundcheck.", "practical_application": "Each band member runs MyMon on a phone or tablet during soundcheck and the show to dial in and adjust their personal in-ear mix.", "category": "Monitor Mixing App", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["eMotion LV1", "mRecall", "SoundGrid", "FIT Controller", "SuperRack SoundGrid"], "common_mistakes": ["Expecting MyMon to change the front-of-house mix, when it only controls that performer's monitor send", "Losing control because the tablet drops off the Wi-Fi network", "Assuming it works with any console, when it pairs with the eMotion LV1 system", "Confusing personal monitor changes with the master mix and asking the engineer to 'fix' the room"], "scenario_contexts": ["A drummer sets their own in-ear balance from a phone during soundcheck", "A singer boosts their own vocal in the wedges without flagging the engineer", "A band shares control of individual monitor mixes across several tablets on stage"], "formula_symbolic": "", "formula_words": ""}, {"id": "31508d1b-6c20-4b48-a174-bf75fd8a6c13", "term": "ProLink Console Remote", "definition": "ProLink is a console-integration protocol from Waves Audio Ltd. that lets a compatible mixing console (initially DiGiCo models with built-in Waves I/O) remotely control and mirror SuperRack SoundGrid running on a host computer. When linked, loading a console session or firing a snapshot recalls the matching SuperRack state, soloing a channel brings its rack to the front, plugin parameters can be adjusted with the console's Touch & Turn, and time-based plugins follow the console's tempo. Introduced in SuperRack V14.30, ProLink replaces the earlier Legacy remote integration. The ProLink name is a Waves trademark; the underlying concept is generic console-to-outboard remote control and state mirroring.", "plain_english": "ProLink links a mixing console to Waves SuperRack plugin software. When you pick a channel or scene on the console, SuperRack follows along. You can tweak Waves plugins from the console's own controls. It keeps the console and the plugin rack in step during a show.", "purpose_function": "It exists so an engineer can drive Waves plugin racks from the familiar console surface, keeping snapshots, channel selection, and tempo synchronized instead of managing two systems by hand.", "practical_application": "An engineer using a supported DiGiCo console enables ProLink so recalling a scene also recalls the SuperRack racks and plugin settings for that moment in the show.", "category": "Console Integration", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["SuperRack SoundGrid", "SoundGrid", "eMotion LV1", "mRecall", "SoundGrid DSP Server"], "common_mistakes": ["Running mismatched software versions, since ProLink needs specific SuperRack and console firmware", "Assuming ProLink works with every console, when it targets specific supported models", "Confusing ProLink with the older Legacy integration it replaced", "Expecting audio to travel over ProLink, when it carries control and sync, not the audio signal"], "scenario_contexts": ["A festival engineer recalls console scenes that also recall matching SuperRack snapshots per band", "Soloing a vocal on the console automatically brings that channel's plugin rack forward on screen", "Delay and reverb plugins follow the console's tempo through tempo-tapped snapshots"], "formula_symbolic": "", "formula_words": ""}, {"id": "283b2601-dd9b-4516-9c70-656796601b68", "term": "SoundGrid", "definition": "SoundGrid is an audio-over-Ethernet networking and DSP platform from Waves Audio Ltd. that carries many channels of audio and control data between host computers, I/O devices, and dedicated processing servers over standard Gigabit Ethernet (1000BASE-T) using Cat5e/Cat6 cabling in a star topology through network switches. It distributes clock using a proprietary Sync-over-Ethernet (SoE) scheme and offloads plugin processing to SoundGrid DSP servers at low latency. The SoundGrid name is a Waves trademark; the underlying method is generic Ethernet audio networking combined with networked digital signal processing.", "plain_english": "SoundGrid sends audio and control between computers and gear over normal network cables. It uses regular Ethernet switches and Cat cables, like a small office network. Heavy effects processing runs on a separate server on that network. This keeps delay low and frees up the main computer.", "purpose_function": "It exists to move large channel counts of low-latency audio around a rig and to hand plugin processing to dedicated servers, so real-time live and studio work does not overload one computer.", "practical_application": "A technician wires computers, interfaces, and a DSP server to a Gigabit switch so audio and Waves processing flow across one SoundGrid network.", "category": "Audio Networking", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["SoundGrid DSP Server", "SoundGrid Studio", "SoundGrid Connect", "SuperRack SoundGrid", "eMotion LV1"], "common_mistakes": ["Confusing SoundGrid with Dante or AES67, which are separate audio-over-Ethernet standards", "Daisy-chaining devices instead of using the required star topology through a switch", "Using an unqualified or non-Gigabit switch and getting dropouts or clock errors", "Assuming SoundGrid runs over the public internet, when it needs a dedicated local Gigabit network"], "scenario_contexts": ["Building a live rig where a console, computer, and DSP server all share one Ethernet network", "Networking studio interfaces and computers to share I/O and processing", "Adding a second DSP server to the network to expand plugin capacity"], "formula_symbolic": "", "formula_words": ""}, {"id": "b1469bf7-15ab-4e96-93c5-1a17b0db7c36", "term": "SoundGrid Connect", "definition": "SoundGrid Connect is a feature of Waves Audio Ltd.'s SoundGrid Studio application that streams audio between standard ASIO or Core Audio interfaces and the SoundGrid network without requiring a dedicated SoundGrid DSP server. It is intended for mixing use rather than tracking, because processing plugins this way carries higher latency than a dedicated server provides. The SoundGrid Connect name is a Waves trademark; the underlying concept is generic driver-level audio routing that bridges a standard interface into an audio network.", "plain_english": "SoundGrid Connect lets a normal audio interface talk to the SoundGrid system. You do not need the separate processing server to use it. It is meant for mixing, not for recording live performers. That is because it adds more delay than a dedicated server would.", "purpose_function": "It exists to let users route audio into SoundGrid and use Waves processing with an existing interface, lowering the entry cost by skipping the dedicated DSP server.", "practical_application": "An engineer without a SoundGrid server uses SoundGrid Connect to run Waves racks on audio from a standard ASIO or Core Audio interface while mixing.", "category": "Audio Networking", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["SoundGrid", "SoundGrid Studio", "SoundGrid DSP Server", "SuperRack SoundGrid", "eMotion LV1"], "common_mistakes": ["Using it for live tracking or real-time monitoring, where its added latency causes problems", "Assuming it replaces a dedicated SoundGrid server for heavy or low-latency work", "Confusing SoundGrid Connect (interface bridging) with SoundGrid Studio (the whole management app)", "Expecting the very lowest latency, which requires a dedicated DSP server"], "scenario_contexts": ["Mixing with Waves plugins on a laptop and a standard interface, with no DSP server present", "Routing audio between two ASIO or Core Audio devices for a mix session", "Trying out SoundGrid processing before investing in a dedicated server"], "formula_symbolic": "", "formula_words": ""}, {"id": "0db12f09-c003-48fe-8b30-8694860cd2c4", "term": "SoundGrid DSP Server", "definition": "A SoundGrid DSP server is a dedicated computer, sold by Waves Audio Ltd. and running a customized Linux operating system, whose sole job is to process audio on a SoundGrid network. It instantiates plugins and performs mixing and summing for host applications such as SuperRack SoundGrid and eMotion LV1, offloading that work from the host computer at low latency; multiple servers can be networked together and configured for redundancy. The product name is a Waves trademark; the underlying concept is a generic dedicated real-time DSP/plugin processing server.", "plain_english": "A SoundGrid DSP server is a computer that only runs audio effects. It takes the heavy plugin work off the main mixing computer. This keeps delay low and the system stable. You can add more servers for more effects, or a backup server for safety.", "purpose_function": "It exists to run large numbers of plugins in real time with low latency, so the host computer stays responsive and the system can handle demanding live processing.", "practical_application": "A technician connects one or more DSP servers to the SoundGrid network so SuperRack or LV1 can run its plugins on the server rather than the host CPU.", "category": "Live DSP Processing", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["SoundGrid", "SuperRack SoundGrid", "eMotion LV1", "SoundGrid Studio", "SoundGrid Connect"], "common_mistakes": ["Confusing the DSP server with the host computer that runs the user interface", "Loading more plugins than the server can process and causing overloads or dropouts", "Skipping a redundant/backup server on a critical show", "Assuming any PC is a SoundGrid server, when it runs a dedicated customized operating system"], "scenario_contexts": ["Running hundreds of plugin instances on a live rig without taxing the host laptop", "Adding a second server so a large festival input list has enough processing", "Configuring a redundant server so a single failure does not stop the show"], "formula_symbolic": "", "formula_words": ""}, {"id": "67b8c230-4b4c-444b-8b61-64c2eae92cb0", "term": "SoundGrid Studio", "definition": "SoundGrid Studio is a software application from Waves Audio Ltd. that sets up and manages a SoundGrid network in the studio, handling audio patching between host computers, I/O devices, and DSP servers. It installs the SoundGrid driver that connects a DAW to the network and works alongside the StudioRack plugin, which can host Waves and supported third-party VST3 plugins. The SoundGrid Studio name is a Waves trademark; the underlying concept is a generic network configuration and audio-patching application.", "plain_english": "SoundGrid Studio is the app that runs a SoundGrid network in a studio. It patches audio between your computer, interfaces, and the effects server. It also installs the driver that links your recording software to the network. Think of it as the control panel for the whole setup.", "purpose_function": "It exists to configure and route a SoundGrid system, giving one place to connect devices, assign I/O, and bridge a DAW to the network and its processing.", "practical_application": "A studio engineer opens SoundGrid Studio to register devices, patch inputs and outputs, and set up the SoundGrid driver for their DAW.", "category": "Audio Networking", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["SoundGrid", "SoundGrid Connect", "SoundGrid DSP Server", "SuperRack SoundGrid", "eMotion LV1"], "common_mistakes": ["Confusing SoundGrid Studio (studio network management) with SuperRack (the live plugin rack)", "Forgetting to assign a clock master, causing sync errors on the network", "Missing patch assignments so audio does not reach the intended device", "Assuming StudioRack can load any plugin, when third-party support depends on VST3 and the operating system"], "scenario_contexts": ["Setting up a studio SoundGrid network and patching interfaces to a DAW", "Bridging Pro Tools or another DAW to the SoundGrid network via its driver", "Managing which devices act as clock master and I/O on the network"], "formula_symbolic": "", "formula_words": ""}, {"id": "9772b9d3-5471-4e79-98d2-2bf18c48911e", "term": "SuperRack", "definition": "SuperRack is Waves Audio Ltd.'s family of plugin-rack host software for live sound and broadcast, letting engineers insert Waves and third-party plugins into console or interface channels in real time. Its members share a rack-and-snapshot workflow, where each rack holds several plugins in signal order and complete states are saved as snapshots for fast recall; the flagship SuperRack SoundGrid runs processing on dedicated SoundGrid servers, while SuperRack Performer runs natively on the host computer's CPU. The SuperRack name is a Waves trademark; the underlying concept is a generic real-time plugin host used as networked outboard processing.", "plain_english": "SuperRack is software that acts like a rack of effects for live shows. You drop Waves plugins onto console channels and process the audio in real time. You save whole setups as snapshots and recall them fast. It comes in versions that use a separate server or just your computer.", "purpose_function": "It exists to bring studio-grade plugins into live and broadcast mixes as recallable outboard, so engineers get consistent processing they can save and instantly reload.", "practical_application": "An engineer builds racks of plugins for each channel, saves them as snapshots, and recalls them per song or per act during a live show.", "category": "Live Plugin Rack", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["SuperRack SoundGrid", "SuperRack Performer", "SuperRack LiveBox", "SoundGrid", "ProLink Console Remote"], "common_mistakes": ["Confusing the SoundGrid version (server-based) with Performer (native, host CPU)", "Assuming it is a mixer, when it is insert processing that works alongside a console", "Not saving snapshots, then losing recallable settings between shows", "Overloading a rack or the host with more plugins than the system can process"], "scenario_contexts": ["Adding Waves channel strips and reverbs to a DiGiCo or other console via inserts", "Recalling different plugin snapshots for each band on a festival day", "Choosing between the SoundGrid and Performer versions based on the available hardware"], "formula_symbolic": "", "formula_words": ""}, {"id": "dcb82a34-f89d-4a2c-8ccc-21857c5ea807", "term": "SuperRack LiveBox", "definition": "SuperRack LiveBox is a line of rack-mountable hardware units from Waves Audio Ltd. designed specifically to run SuperRack Performer, combining a computer and audio I/O in one turnkey box. It is offered as the LiveBox D with Dante networking (up to 128 channels at 48/96 kHz) and the LiveBox M with MADI (up to 64 channels at 48 kHz or 32 channels at 96 kHz). The LiveBox name is a Waves trademark; the underlying concept is a generic integrated audio computer with networked I/O.", "plain_english": "SuperRack LiveBox is a ready-made box that runs Waves live plugin software. It packs a computer and audio connections into one rack unit. One model uses Dante networking and the other uses MADI. You add it to a rig instead of building your own computer and interface.", "purpose_function": "It exists to give a compact, pre-integrated way to run SuperRack Performer with built-in networked I/O, simplifying setup compared with assembling a separate computer and interface.", "practical_application": "An engineer racks a LiveBox, patches it to the console over Dante or MADI, and runs SuperRack Performer plugin racks on the show audio.", "category": "Live Sound Hardware", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["SuperRack Performer", "SuperRack SoundGrid", "SuperRack", "Axis One", "SoundGrid"], "common_mistakes": ["Confusing LiveBox with a SoundGrid server; it runs Performer natively, not server-based SoundGrid processing", "Choosing the MADI model when a Dante network is required, or vice versa", "Exceeding the channel count for the chosen model and sample rate", "Assuming it is a mixer, when it is a plugin-processing host"], "scenario_contexts": ["Adding Waves processing to a Dante-networked rig with the LiveBox D", "Inserting plugins over a MADI link to a console using the LiveBox M", "Deploying a compact turnkey plugin host on a fly rig instead of a custom computer"], "formula_symbolic": "", "formula_words": ""}, {"id": "2632f2cb-cf0a-4c7f-b00d-bbc6dd764225", "term": "SuperRack Performer", "definition": "SuperRack Performer is a version of Waves Audio Ltd.'s SuperRack plugin host that runs natively on the host computer via an ASIO or Core Audio driver, processing audio on the computer's own CPU rather than on a dedicated SoundGrid DSP server. It supports both Waves and third-party VST3 plugins and shares SuperRack's rack-and-snapshot workflow for live use. The SuperRack Performer name is a Waves trademark; the underlying concept is a generic native (host-CPU) real-time plugin host.", "plain_english": "SuperRack Performer is a version of SuperRack that runs on your computer alone. It does not need a separate effects server. It uses your computer's own processor for the plugins. It also works with many non-Waves plugins.", "purpose_function": "It exists to run live plugin racks without dedicated SoundGrid server hardware, and to open the rack to third-party VST3 plugins, lowering cost and widening plugin choice.", "practical_application": "An engineer runs Performer on a laptop or LiveBox, connects via an ASIO or Core Audio interface, and inserts Waves and third-party plugins into the live mix.", "category": "Live Plugin Rack", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["SuperRack", "SuperRack SoundGrid", "SuperRack LiveBox", "SoundGrid", "ProLink Console Remote"], "common_mistakes": ["Overloading the host CPU with too many plugins, since there is no dedicated DSP server to offload work", "Assuming it uses a SoundGrid server, when processing runs natively on the host", "Expecting the exact same performance and redundancy as the SoundGrid version", "Forgetting that its third-party support is for VST3 plugins"], "scenario_contexts": ["Running live plugin racks from a laptop and interface without buying a DSP server", "Using favorite third-party VST3 plugins alongside Waves plugins in a live rig", "Hosting Performer inside a SuperRack LiveBox for a turnkey setup"], "formula_symbolic": "", "formula_words": ""}, {"id": "596a3484-d502-4164-8c4e-41e4d07a3867", "term": "SuperRack SoundGrid", "definition": "SuperRack SoundGrid is the SoundGrid-network flagship of Waves Audio Ltd.'s SuperRack plugin-host family, letting live sound and broadcast engineers process many audio channels through large numbers of Waves plugin instances at near-zero latency. Audio is not processed on the host computer; instead a dedicated SoundGrid DSP server handles the plugins, connected through a Gigabit switch to consoles or I/O devices, with racks and snapshots for building and recalling processing. The SuperRack SoundGrid name is a Waves trademark; the underlying concept is a generic server-based, networked real-time plugin host.", "plain_english": "SuperRack SoundGrid is the main version of SuperRack for live shows. It runs the plugins on a separate SoundGrid server, not on the mixing computer. This keeps delay very low and the system stable. You build racks of plugins and save them as snapshots to recall fast.", "purpose_function": "It exists to deliver large, low-latency plugin processing for live and broadcast by offloading the work to a dedicated server, giving reliable studio-grade effects on stage.", "practical_application": "An engineer connects a console to a SoundGrid server through SuperRack SoundGrid and inserts recallable Waves plugin racks across the show's channels.", "category": "Live Plugin Rack", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["SuperRack", "SuperRack Performer", "SoundGrid", "SoundGrid DSP Server", "ProLink Console Remote"], "common_mistakes": ["Trying to run without a SoundGrid server, which this version requires for processing", "Confusing it with SuperRack Performer, which processes on the host CPU", "Using an unqualified switch or cabling and causing network dropouts", "Loading more plugin instances than the server can handle"], "scenario_contexts": ["Inserting Waves racks into a large console over a SoundGrid network at a concert", "Processing dozens of broadcast channels with low latency on a dedicated server", "Linking to a DiGiCo console via ProLink so snapshots recall matching racks"], "formula_symbolic": "", "formula_words": ""}, {"id": "0aa63a7f-95dc-4fc4-b063-03bf6d7b9479", "term": "eMotion LV1", "definition": "eMotion LV1 is a software live mixing console from Waves Audio Ltd. that runs on a host computer over a SoundGrid network, with plugin and mixing processing carried out on one or more SoundGrid DSP servers and audio I/O provided by SoundGrid interfaces and stageboxes. It is controlled by touchscreens, tablets, or hardware surfaces such as the FIT Controller, offers configurations up to 64 (expandable to 80) stereo input channels with multiple buses, and lets Waves plugins be inserted directly on channels. The eMotion LV1 name is a Waves trademark; the underlying concept is a generic software-based, networked digital mixing console.", "plain_english": "eMotion LV1 is a mixing console that lives in software on a computer. The audio work runs on a separate SoundGrid server. You control it with touchscreens, tablets, or a fader surface. Waves effects plug straight into the channels, like having outboard built in.", "purpose_function": "It exists to provide a flexible, scalable live console built from computer, network, and server parts, letting engineers size the system to the job and use Waves plugins natively on every channel.", "practical_application": "A front-of-house or monitor engineer runs LV1 on a computer with a SoundGrid server and interfaces, mixing the show from a touchscreen and FIT faders.", "category": "Live Mixing Console", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["eMotion LV1 Classic", "eMotion LV1 Session Editor", "SoundGrid", "SoundGrid DSP Server", "FIT Controller"], "common_mistakes": ["Assuming the host computer does the mixing, when the SoundGrid server handles the processing", "Undersizing the DSP server for the channel and plugin count needed", "Relying only on a tablet for control and losing the mix if Wi-Fi drops", "Confusing LV1 (a full console) with SuperRack (insert plugin processing only)"], "scenario_contexts": ["Mixing front-of-house for a concert on a compact, computer-based console", "Running monitors from LV1 with performers adjusting their own mixes via MyMon", "Scaling a system up with a bigger server and more I/O for a larger show"], "formula_symbolic": "", "formula_words": ""}, {"id": "d6154d18-6c6f-4c94-88ed-7f03a290383b", "term": "eMotion LV1 Classic", "definition": "eMotion LV1 Classic is the software-only digital mixer version in Waves Audio Ltd.'s eMotion LV1 line, offered in 64, 32, or 16 stereo-channel configurations for front-of-house, monitor, and broadcast engineers. It retains the established SoundGrid-based LV1 architecture, running on a host computer with processing on SoundGrid DSP servers, and the 'Classic' name distinguishes it from newer LV1 offerings in the range. The eMotion LV1 Classic name is a Waves trademark; the underlying concept is a generic software-based, networked digital mixing console.", "plain_english": "eMotion LV1 Classic is the software-only version of the LV1 mixer. You buy it in 64, 32, or 16 stereo channel sizes. It runs on a computer and a SoundGrid server like the rest of the LV1 line. The name 'Classic' sets it apart from newer LV1 products.", "purpose_function": "It exists to offer the software LV1 console at set channel tiers, so engineers can pick a size that fits their shows without extra bundled hardware.", "practical_application": "An engineer chooses the 16, 32, or 64 stereo-channel Classic tier to match their input needs and runs it on a SoundGrid system.", "category": "Live Mixing Console", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["eMotion LV1", "eMotion LV1 Session Editor", "SoundGrid", "SoundGrid DSP Server", "FIT Controller"], "common_mistakes": ["Thinking 'Classic' means outdated, when it is the current software-only mixer tier", "Buying a channel tier too small for the show's input list", "Assuming it includes hardware, when it is software only and needs a computer, server, and I/O", "Confusing it with SuperRack, which is insert processing rather than a full console"], "scenario_contexts": ["Selecting the 32-channel Classic tier for a mid-size band's front-of-house mix", "Running Classic on an Axis One with a SoundGrid server and stageboxes", "Adding FIT controllers to a Classic system for hands-on faders"], "formula_symbolic": "", "formula_words": ""}, {"id": "df55ffb8-8886-4a5b-95f6-ed2b97e5d691", "term": "eMotion LV1 Session Editor", "definition": "eMotion LV1 Session Editor is an offline software application from Waves Audio Ltd. that lets engineers build and edit eMotion LV1 mixing sessions on a laptop or desktop without the LV1 system's DSP server or I/O hardware present. It is used to prepare channel layouts, routing, and processing in advance so a session is ready to load when the engineer reaches the venue. The Session Editor name is a Waves trademark; the underlying concept is a generic offline session/scene editor for a digital console.", "plain_english": "The Session Editor lets you build an LV1 show file on a normal computer. You do not need the mixer's server or interfaces to use it. You lay out channels and settings ahead of time. Then you load the finished session when you get to the gig.", "purpose_function": "It exists so engineers can prep LV1 sessions offline, saving setup time at the venue and reducing mistakes made under show-day pressure.", "practical_application": "An engineer builds channel names, routing, and plugin racks in the Session Editor at home, then loads that session onto the LV1 system at the show.", "category": "Live Sound Software", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["eMotion LV1", "eMotion LV1 Classic", "SoundGrid", "mRecall", "FIT Controller"], "common_mistakes": ["Expecting to hear or process audio in the editor, when it is offline preparation only", "Building a session with I/O or channel counts the target system cannot support", "Forgetting to transfer the finished session file to the show computer", "Assuming settings auto-sync, when the prepared session must be loaded onto the console"], "scenario_contexts": ["Prepping a full show session on a laptop the night before a gig", "Editing channel layouts and routing away from the LV1 system", "Preparing venue-specific sessions in advance for a touring production"], "formula_symbolic": "", "formula_words": ""}, {"id": "e3d66e53-f764-4111-8a96-c9be70aa30bf", "term": "mRecall", "definition": "mRecall is a mobile app from Waves Audio Ltd. for iOS and Android that lets engineers recall and manage scenes and snapshots on Waves live systems, including eMotion LV1 and SuperRack, from a phone or tablet. It gives remote access to saved mixing states so scenes can be fired without standing at the main console. The mRecall name is a Waves trademark; the underlying concept is a generic remote scene/snapshot recall app.", "plain_english": "mRecall is a phone or tablet app that fires saved scenes on Waves live systems. It works with the LV1 mixer and SuperRack. You can recall a setup without being at the console. This helps when you need to change scenes from elsewhere in the venue.", "purpose_function": "It exists to give remote, mobile control of scene and snapshot recall, so an engineer can trigger saved states from away from the console during a show.", "practical_application": "An engineer walks the room or stands at the stage and uses mRecall on a tablet to fire the next scene during a performance.", "category": "Remote Control App", "difficulty": "intermediate", "achievement_id": "8db281ce-61c5-4c0f-b9e2-c83fa779792b", "cross": [], "related_terms": ["eMotion LV1", "SuperRack SoundGrid", "MyMon", "eMotion LV1 Session Editor", "SoundGrid"], "common_mistakes": ["Assuming mRecall creates scenes, when scenes are built on the console and mRecall recalls them", "Losing control if the tablet drops off the network", "Confusing mRecall (scene recall) with MyMon (personal monitor mixing)", "Expecting full mixing control, when its role is scene and snapshot recall"], "scenario_contexts": ["Firing scenes from a tablet while checking coverage out in the audience", "Recalling snapshots at the stage during a theatrical cue sequence", "Handing scene recall to an assistant on a tablet away from the console"], "formula_symbolic": "", "formula_words": ""}, {"id": "97874258-5391-4846-9a08-e93330d75213", "term": "Bass Rider", "definition": "Bass Rider is a real-time level-riding plugin from Waves Audio Ltd. that automatically adjusts the moment-to-moment gain of a bass track to keep its level even, without changing the instrument's tone. It applies continuous gain rides rather than the fixed gain reduction of a compressor.", "plain_english": "Bass Rider keeps a bass part at a steady volume. It turns quiet notes up and loud notes down as the track plays. It works like an engineer nudging the fader all the time. It changes level, not tone.", "purpose_function": "It exists to even out the level of a bass performance automatically, saving the engineer from manual fader rides or heavy compression.", "practical_application": "An engineer inserts it on a bass DI or bass guitar track so every note sits at a consistent level in the mix.", "category": "Level Automation", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Vocal Rider", "Compressor", "Automation", "Gain Staging", "Fader"], "common_mistakes": ["Confusing it with a compressor; it rides gain over time rather than reacting to each transient with a fixed ratio", "Setting the target range too aggressively, which flattens the natural dynamics of the performance", "Expecting it to fix tone or remove noise, which it does not do"], "scenario_contexts": ["Smoothing an uneven finger-style bass take before compression", "Balancing bass level under a busy chorus so it stays audible", "Preparing a bass stem with consistent level for mastering"], "formula_symbolic": "", "formula_words": ""}, {"id": "744bd8b7-c8e2-4f2d-a2a0-f3293bb0730a", "term": "Brauer Motion", "definition": "Brauer Motion is a stereo auto-panning plugin from Waves Audio Ltd., created with mixing engineer Michael Brauer as a signature tool. It moves a sound along circular paths in the stereo field to add motion, depth and width, and its movement can be synced to the track's tempo.", "plain_english": "Brauer Motion makes a sound move around the stereo image. Instead of sitting in one spot, the sound circles between left and right. You can lock the movement to the beat of the song. It adds a sense of space and motion.", "purpose_function": "It exists to add dynamic spatial movement and width to a track, going beyond static left-right panning.", "practical_application": "An engineer puts it on a synth, guitar or vocal effect to make the part swirl or drift across the stereo field.", "category": "Panning Effect", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Auto-Pan", "Panning", "Stereo Field", "MondoMod", "LFO"], "common_mistakes": ["Using extreme motion on a lead vocal, which can make it distracting or hard to place", "Forgetting to check the result in mono, where circular panning can change level or phase", "Applying it to low-frequency or bass content, which usually should stay centered"], "scenario_contexts": ["Adding movement to a doubled synth pad in a chorus", "Creating a spinning delay throw on a vocal ad-lib", "Widening a static rhythm guitar in an electronic track"], "formula_symbolic": "", "formula_words": ""}, {"id": "1adb3ed3-5ead-4f7b-998d-8fb511e9ff7e", "term": "CLA Epic", "definition": "CLA Epic is a multi-effects plugin from Waves Audio Ltd. and part of the signature series of mixing engineer Chris Lord-Alge (CLA). It combines several delays and reverbs, modeled on units from his studio, that can be blended and routed together in one interface.", "plain_english": "CLA Epic is a delay-and-reverb effects box in one plugin. It holds several echoes and reverbs picked by engineer Chris Lord-Alge. You can mix and route them to add space and depth. It is mainly used on vocals and instruments.", "purpose_function": "It exists to give quick access to a curated set of delays and reverbs for adding depth and dimension, based on one engineer's go-to sounds.", "practical_application": "An engineer inserts it on a vocal or guitar to stack echoes and reverbs for a big, produced sound without loading many separate plugins.", "category": "Delay & Reverb", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Reverb", "Delay", "CLA MixHub", "Send Effect", "Modulation"], "common_mistakes": ["Overloading a mix with too much reverb and delay, which blurs clarity", "Treating the presets as finished rather than starting points to adjust", "Placing heavy time effects before dynamics in a way that muddies the source"], "scenario_contexts": ["Building a lush vocal effect chain in a pop chorus", "Adding slap and plate depth to a lead guitar", "Creating ambience on a snare in a rock mix"], "formula_symbolic": "", "formula_words": ""}, {"id": "597f0133-7077-42ad-8dd2-dd16f9b3efe9", "term": "CLA MixHub", "definition": "CLA MixHub is a channel-strip mixing plugin from Waves Audio Ltd. in the signature series of Chris Lord-Alge (CLA). It models the channel strips of his SSL console, giving each track EQ, compression, gating and drive, and lets many channels be managed together from one window using a 'bucket' workflow.", "plain_english": "CLA MixHub puts a mixing console inside one plugin. Each track gets an equalizer, compressor, gate and drive, like a channel on a big desk. It copies the SSL console used by engineer Chris Lord-Alge. You can adjust many channels from one window.", "purpose_function": "It exists to bring an analog-style console workflow and channel processing into the DAW, so an engineer can mix many tracks with a consistent set of tools.", "practical_application": "An engineer places instances across channels and switches between them in one window to EQ, compress and drive each track like a hardware console.", "category": "Channel Strip", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Channel Strip", "Equalizer", "Compressor", "Console", "CLA Epic"], "common_mistakes": ["Adding drive on every channel, which can quickly make the whole mix harsh", "Ignoring gain staging into the strip, which changes how the drive and compressor react", "Assuming it replaces careful gain and balance decisions"], "scenario_contexts": ["Mixing a full band with one console-style workflow", "Adding analog color and glue to drum bus channels", "Quickly EQ-ing and compressing each track from a single interface"], "formula_symbolic": "", "formula_words": ""}, {"id": "9f1c2042-9980-425b-8c90-02b52f2960bc", "term": "Clarity Vx", "definition": "Clarity Vx is a real-time noise-reduction plugin from Waves Audio Ltd. that uses Waves Neural Networks (a machine-learning model) to separate a voice from background noise and remove the noise. It is aimed at cleaning vocals and dialogue.", "plain_english": "Clarity Vx removes background noise from voice recordings. It uses artificial intelligence trained to tell a voice apart from noise. It cleans up hiss, hum and room sound in real time. It is made for vocals and speech.", "purpose_function": "It exists to clean noisy voice recordings quickly, using AI instead of manual EQ or gating.", "practical_application": "An editor uses it to strip background noise from a dialogue clip or vocal take during mixing.", "category": "Noise Reduction", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Noise Reduction", "De-Noise", "Clarity Vx Pro", "Dialogue Editing", "Neural Network"], "common_mistakes": ["Pushing the reduction too far, which leaves the voice sounding thin or full of artifacts", "Using it to fix distortion or clipping, which it cannot repair", "Expecting it to replace good recording and mic technique"], "scenario_contexts": ["Cleaning a podcast recorded in a noisy room", "Removing air-conditioning hum from film dialogue", "Reducing crowd noise on a location vocal"], "formula_symbolic": "", "formula_words": ""}, {"id": "5c29c00c-e381-4fb2-9ae6-c32f4d586cbd", "term": "Clarity Vx Pro", "definition": "Clarity Vx Pro is the advanced version of Waves Audio Ltd.'s Clarity Vx real-time noise-reduction plugin, also powered by Waves Neural Networks. It adds finer, multi-component control over the voice, letting the user target different parts of the signal and perform several noise-reduction tasks in one automatable pass.", "plain_english": "Clarity Vx Pro is the bigger version of Clarity Vx. It removes background noise from voices using artificial intelligence. It gives more control, so you can treat different parts of the sound separately. It works in real time and can handle several cleanup jobs at once.", "purpose_function": "It exists to give post-production engineers detailed, professional control over AI noise reduction for voice and dialogue.", "practical_application": "A dialogue mixer uses it to remove noise and shape the voice with several components in one pass on a film or broadcast track.", "category": "Noise Reduction", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Clarity Vx", "Noise Reduction", "Dialogue Editing", "De-Reverb", "Neural Network"], "common_mistakes": ["Over-processing until the voice sounds unnatural or watery", "Assuming Pro presets suit every recording without adjustment", "Using it as a substitute for a clean recording"], "scenario_contexts": ["Cleaning dialogue for a film mix with multiple noise problems", "Restoring a noisy interview for broadcast", "Detailed vocal cleanup on a music session"], "formula_symbolic": "", "formula_words": ""}, {"id": "098f181e-e403-40ef-a48d-88ab0c024c51", "term": "Curves AQ", "definition": "Curves AQ is an AI-driven equalizer plugin from Waves Audio Ltd. When the user runs its Learn function it analyzes the incoming audio and automatically generates EQ profiles, which the user can select, blend and adjust. Waves markets it as an autonomous or cognitive EQ.", "plain_english": "Curves AQ is a smart equalizer. You press Learn and it studies your sound. Then it suggests several ready-made EQ settings for you. You can pick one, blend them, or tweak them by hand. It saves time deciding how to shape the tone.", "purpose_function": "It exists to speed up EQ decisions by using machine learning to propose tone-shaping curves tailored to the material.", "practical_application": "An engineer runs Learn on a vocal or full mix and starts from a generated EQ curve instead of building one from scratch.", "category": "Equalizer Plugin", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Equalizer", "Curves Equator", "Dynamic EQ", "Frequency", "Machine Learning"], "common_mistakes": ["Accepting the generated curve blindly without listening and adjusting", "Assuming an AI EQ removes the need to understand frequency balance", "Using heavy automatic EQ where a gentle manual move would be cleaner"], "scenario_contexts": ["Getting a fast EQ starting point on a lead vocal", "Balancing tone across a full mix bus", "Studying the suggested moves to learn EQ decisions"], "formula_symbolic": "", "formula_words": ""}, {"id": "9f31ab80-2736-4a8a-b466-9bd6f6167304", "term": "Curves Equator", "definition": "Curves Equator is a dynamic resonance-suppression equalizer plugin from Waves Audio Ltd. It uses a threshold curve to attenuate frequencies only when they rise above a set contour, taming resonances and frequency buildup. A capture mode can analyze representative audio to build a starting curve, and it supports sidechain unmasking.", "plain_english": "Curves Equator finds and lowers harsh, ringing frequencies. It only acts when a frequency gets too loud against a set line. You can draw the line by hand or let it study your sound to build one. This clears buildup and makes the track smoother.", "purpose_function": "It exists to control resonances and frequency buildup dynamically, cleaning harshness that static EQ cuts handle poorly.", "practical_application": "An engineer uses it on vocals, guitars or a full mix to tame ringing frequencies that only appear on louder notes.", "category": "Dynamic EQ", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Dynamic EQ", "Curves AQ", "Equalizer", "Resonance", "F6 Floating-Band Dynamic EQ", "Sidechain"], "common_mistakes": ["Over-suppressing until the source sounds dull and lifeless", "Assuming it uses AI learning; its capture mode analyzes audio to build a threshold curve, not a neural network", "Setting thresholds so low it acts on wanted tone, not just resonances"], "scenario_contexts": ["Taming resonances on a boxy acoustic guitar", "Reducing harsh buildup on a bright lead vocal only on loud notes", "Using sidechain to carve space for a kick under a bass"], "formula_symbolic": "", "formula_words": ""}, {"id": "4efbcbfa-3a3d-44e3-8420-a065f349d725", "term": "F6 Floating-Band Dynamic EQ", "definition": "The F6 Floating-Band Dynamic EQ is a plugin from Waves Audio Ltd. offering six fully adjustable parametric bands that each combine equalization with dynamic (compression/expansion) control. It includes a real-time spectrum analyzer, mid-side processing and external sidechain, so each band can react to level as well as set a fixed cut or boost.", "plain_english": "The F6 is a smart equalizer with six bands. Each band can boost or cut a frequency like a normal EQ. Each band can also react to volume, acting only when the sound gets loud. It shows a live frequency display to help you aim.", "purpose_function": "It exists to combine surgical EQ with dynamic control, so problem frequencies are tamed only when they actually build up.", "practical_application": "An engineer uses it to reduce harsh vocal resonances or boomy notes that appear only on certain words or hits.", "category": "Dynamic EQ", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Dynamic EQ", "Equalizer", "Curves Equator", "Compressor", "Mid-Side", "Sidechain"], "common_mistakes": ["Setting a wide, deep dynamic cut that dulls the whole source", "Confusing a dynamic band with a static EQ cut; the dynamic band only moves above threshold", "Ignoring the analyzer and guessing the problem frequency"], "scenario_contexts": ["De-essing or taming a harsh vocal frequency dynamically", "Controlling a resonant note on a bass that jumps out", "Using mid-side EQ to clean the center of a mix"], "formula_symbolic": "", "formula_words": ""}, {"id": "4521ea41-4c7a-4b64-88c7-8fcba9ef0933", "term": "IDX Intelligent Dynamics", "definition": "IDX Intelligent Dynamics is a plugin from Waves Audio Ltd. that applies frequency-aware, automatic dynamics processing. It analyzes different frequency ranges and compresses or enhances them independently to add punch, focus and energy, controlled mainly by a single macro knob.", "plain_english": "IDX adds punch and energy to a track automatically. It looks at different frequency ranges and treats each one on its own. One main knob controls how strong the effect is. It works like a smart compressor for clarity and impact.", "purpose_function": "It exists to quickly enhance a track's energy and clarity using automatic, frequency-dependent dynamics, with minimal setup.", "practical_application": "An engineer drops it on a dull mix or instrument and turns one knob to add punch and focus.", "category": "Dynamics Plugin", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Compressor", "Dynamic EQ", "F6 Floating-Band Dynamic EQ", "Multiband Compression", "Transient"], "common_mistakes": ["Pushing the macro too far, which can make the track sound squashed or unnatural", "Assuming it replaces careful multiband compression or EQ decisions", "Using it to fix a poor arrangement or balance"], "scenario_contexts": ["Adding quick punch to a flat drum bus", "Enhancing focus on a dull rhythm guitar", "Energizing a full mix before final polish"], "formula_symbolic": "", "formula_words": ""}, {"id": "1415e045-e13f-4971-aa89-4af3733dddee", "term": "Increased Digital Resolution", "definition": "Increased Digital Resolution (IDR) is a proprietary requantization system from Waves Audio Ltd., co-developed with Michael Gerzon, used to reduce the bit depth (word length) of digital audio with minimal quality loss. It combines dither and psychoacoustic noise shaping so that reducing high-bit-depth audio, for example 24-bit to 16-bit, keeps more apparent resolution.", "plain_english": "IDR helps shrink audio to fewer bits without losing quality. Fewer bits normally add ugly distortion. IDR adds a tiny, smart noise that hides that distortion. It pushes the leftover noise into sounds people barely hear.", "purpose_function": "It exists to convert high-bit-depth audio to a lower bit depth, such as 16-bit for CD, while keeping the sound as clean as possible.", "practical_application": "An engineer uses IDR, built into the Waves L-series limiters, as the last step when exporting a master to 16-bit.", "category": "Dithering Technology", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Dither", "Noise Shaping", "Bit Depth", "Quantization", "L2 Ultramaximizer", "Requantization"], "common_mistakes": ["Dithering more than once in a chain, which adds noise each time", "Applying IDR before further processing instead of as the final step", "Reducing bit depth with no dither, which causes quantization distortion"], "scenario_contexts": ["Exporting a 24-bit master down to 16-bit for CD", "Setting the final limiter's output word length for a release", "Choosing a noise-shaping curve when bouncing a mastered file"], "formula_symbolic": "", "formula_words": ""}, {"id": "66907d2c-9458-4dd6-b265-32659d7d1430", "term": "L1 Ultramaximizer", "definition": "The L1 Ultramaximizer is a peak limiter and level maximizer plugin from Waves Audio Ltd. It uses a look-ahead brickwall design to raise loudness while preventing peaks from exceeding a set ceiling, and it includes IDR (Increased Digital Resolution) for dithered word-length reduction.", "plain_english": "The L1 Ultramaximizer makes a mix louder without letting peaks clip. It looks slightly ahead in the audio to catch loud peaks before they cross a set ceiling. It also raises the quieter level up toward that ceiling. It can dither the file down to fewer bits at the end.", "purpose_function": "It exists to maximize loudness and prevent digital overs at the final stage of a mix or master, with clean word-length reduction.", "practical_application": "An engineer places it last on the master bus to raise level to a ceiling and export at 16-bit with dither.", "category": "Limiter Plugin", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Limiter", "Look-Ahead", "Increased Digital Resolution", "Dither", "L2 Ultramaximizer", "Brickwall Limiter"], "common_mistakes": ["Pushing the threshold down too far, which squashes dynamics and causes distortion", "Placing other processing after the limiter, which can reintroduce peaks over the ceiling", "Skipping dither when reducing bit depth on export"], "scenario_contexts": ["Maximizing loudness on a mix bus before export", "Setting a true ceiling to avoid clipping on a master", "Bouncing a 16-bit file with dither for CD"], "formula_symbolic": "", "formula_words": ""}, {"id": "25bbbed8-ec15-479d-b737-36dcf817f78e", "term": "L2 Ultramaximizer", "definition": "The L2 Ultramaximizer is a look-ahead peak limiter and level maximizer from Waves Audio Ltd., originally released as hardware and software. It anticipates peaks to give an overshoot-free brickwall response, raises loudness, and includes IDR dithering with ninth-order noise shaping for word-length reduction.", "plain_english": "The L2 Ultramaximizer makes audio louder while stopping peaks from clipping. It looks ahead so no peak sneaks past the ceiling. It is a common tool for making masters loud. It can also dither the audio down to fewer bits.", "purpose_function": "It exists to maximize loudness with brickwall limiting and clean bit-depth reduction, mainly in mastering.", "practical_application": "An engineer uses it on the master bus to reach a target ceiling and loudness, then exports with dither.", "category": "Limiter Plugin", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Limiter", "L1 Ultramaximizer", "Look-Ahead", "Increased Digital Resolution", "Mastering", "Brickwall Limiter"], "common_mistakes": ["Over-limiting until the master sounds flat and distorted", "Adding gain or EQ after the limiter, which breaks the ceiling", "Not dithering when creating a 16-bit master"], "scenario_contexts": ["Loudness maximizing on a final master", "Setting an output ceiling to prevent clipping", "Bouncing a dithered 16-bit master for release"], "formula_symbolic": "", "formula_words": ""}, {"id": "b649ea56-e081-48e6-870e-49c9d6752a67", "term": "L3 Multimaximizer", "definition": "The L3 Multimaximizer is a multiband peak limiter and maximizer plugin from Waves Audio Ltd. It divides the signal into five frequency bands using a linear-phase crossover and limits them together, so loudness and level can be maximized per band while keeping the overall sound balanced. It also includes IDR dithering.", "plain_english": "The L3 Multimaximizer makes audio louder by splitting it into five frequency ranges. It limits each range but keeps them working together. This lets it get loud without one band ruining another. It is used mainly in mastering.", "purpose_function": "It exists to maximize loudness with more control than a single-band limiter, by limiting separate frequency bands that share the workload.", "practical_application": "A mastering engineer uses it to push loudness while controlling low, mid and high bands independently.", "category": "Multiband Limiter", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Limiter", "Multiband Compression", "L2 Ultramaximizer", "Crossover", "Increased Digital Resolution", "Mastering"], "common_mistakes": ["Setting extreme band limiting that pumps or dulls the mix", "Assuming multiband limiting fixes a poorly balanced mix", "Forgetting it is a mastering-level tool, not a fix for every track"], "scenario_contexts": ["Loudness maximizing a master with tricky low end", "Controlling harsh highs and heavy bass separately during mastering", "Getting a competitive level on a full mix"], "formula_symbolic": "", "formula_words": ""}, {"id": "bc11f9b2-18de-437e-a450-011da1399f90", "term": "L4 Ultramaximizer", "definition": "The L4 Ultramaximizer is a limiter and level maximizer plugin from Waves Audio Ltd. and the newest member of the Waves L-series. It uses adaptive clipping and adaptive release to reach high loudness while preserving dynamics and low-end punch, and it includes true-peak and LUFS loudness metering.", "plain_english": "The L4 Ultramaximizer is the newest Waves loudness limiter. It makes a master loud while trying to keep its punch. It adjusts its clipping and release on its own as the music changes. It also shows true-peak and loudness (LUFS) meters.", "purpose_function": "It exists to push modern, competitive loudness while protecting dynamics, with built-in loudness metering.", "practical_application": "A mastering engineer uses it on the master bus to hit a loudness target while watching true-peak and LUFS meters.", "category": "Limiter Plugin", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Limiter", "L2 Ultramaximizer", "True Peak", "LUFS", "Clipper", "Mastering"], "common_mistakes": ["Chasing extreme loudness until the master distorts or loses punch", "Ignoring true-peak overs that cause distortion after lossy encoding", "Assuming louder always sounds better than a dynamic master"], "scenario_contexts": ["Hitting a streaming loudness target during mastering", "Maximizing a modern loud master while limiting true peaks", "Comparing dynamics before and after loudness maximizing"], "formula_symbolic": "", "formula_words": ""}, {"id": "c7efa903-6bdf-4988-b908-8cf6b5159143", "term": "LoAir", "definition": "LoAir is a subharmonic generator plugin from Waves Audio Ltd. that creates deep low-frequency (sub) content below the source signal, with adjustable frequency and low-pass controls. It can process polyphonic material and generate LFE (low-frequency effects) tracks from stereo or surround sources.", "plain_english": "LoAir adds deep, felt sub-bass under a sound. It builds very low frequencies that small speakers cannot make. You control how low it goes and how much you add. It can even make the deep boom channel for surround mixes.", "purpose_function": "It exists to add or reinforce ultra-low sub-bass energy, for example under kicks, bass or film effects.", "practical_application": "An engineer adds it to a kick or bass to add weight, or uses it to create an LFE channel for a film mix.", "category": "Bass Enhancement", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["MaxxBass", "Subharmonic", "LFE", "Low-Pass Filter", "Sub Bass"], "common_mistakes": ["Adding too much sub, which eats headroom and muddies the low end", "Using it on systems that cannot reproduce sub, so problems go unheard", "Confusing subharmonic generation with a simple bass EQ boost"], "scenario_contexts": ["Adding deep weight to a kick drum in a dance track", "Creating an LFE channel for a film mix", "Reinforcing sub-bass on a hip-hop 808"], "formula_symbolic": "", "formula_words": ""}, {"id": "993916ed-7dbd-4849-9bc7-4c4bea779e3d", "term": "MaxxAudio", "definition": "MaxxAudio is a suite of consumer audio-enhancement technologies from Waves Audio Ltd., licensed to device makers rather than sold as a studio plugin. It bundles several Waves processes, such as MaxxBass, MaxxVolume, MaxxEQ and MaxxStereo, to improve sound on laptops, tablets, phones, TVs and audio chips.", "plain_english": "MaxxAudio is a package of sound-boosting tools built into everyday devices. You find it in laptops, phones and TVs, not in a studio. It makes small speakers sound louder, clearer and fuller. It bundles several Waves technologies together.", "purpose_function": "It exists to improve playback sound on consumer electronics with small speakers, using studio-derived processing.", "practical_application": "A technician may meet it as the audio-enhancement software on a laptop, for example on some Dell computers, rather than in a mixing session.", "category": "Audio Enhancement Suite", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["MaxxBass", "Psychoacoustics", "Equalizer", "Loudness", "Signal Processing"], "common_mistakes": ["Thinking it is a studio mixing plugin; it is a consumer and OEM technology", "Confusing MaxxAudio the suite with MaxxBass, which is one part of it", "Assuming it changes the actual recording rather than the playback"], "scenario_contexts": ["Explaining the audio enhancement app on a customer's laptop", "Comparing built-in device sound processing to studio tools", "Understanding why small-speaker playback sounds boosted"], "formula_symbolic": "", "formula_words": ""}, {"id": "44a63c9f-7ac8-48c8-a6e0-b7579854eeeb", "term": "MaxxBass", "definition": "MaxxBass is a psychoacoustic bass-enhancement plugin from Waves Audio Ltd. It uses the missing-fundamental principle: instead of boosting low frequencies, it generates a series of higher harmonics that lead the ear to perceive deeper bass, so bass seems present even on small speakers.", "plain_english": "MaxxBass makes bass sound deeper, even on tiny speakers. It does not add real low notes. Instead, it adds matching higher tones. Your brain fills in the missing deep note by itself. This is a trick of how hearing works.", "purpose_function": "It exists to make bass audible on speakers that cannot reproduce low frequencies, using harmonics rather than raw low-end boost.", "practical_application": "An engineer uses it so a bassline still reads on phones, laptops and earbuds, or to add perceived weight without extra sub energy.", "category": "Bass Enhancement", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Psychoacoustics", "Missing Fundamental", "Harmonics", "LoAir", "MaxxAudio", "Sub Bass"], "common_mistakes": ["Adding a real sub boost and MaxxBass together, which overloads the low end", "Overusing it until the bass sounds thin and buzzy", "Thinking it creates true low frequencies rather than the illusion of them"], "scenario_contexts": ["Making a bass guitar translate on small speakers", "Adding perceived weight to a mix with limited sub", "Keeping bass audible on a laptop or phone playback"], "formula_symbolic": "", "formula_words": ""}, {"id": "6ac92a0a-3f32-4677-8ccb-83fed3f5ca96", "term": "MetaFlanger", "definition": "MetaFlanger is a modulation-effect plugin from Waves Audio Ltd. that recreates flanging, along with related tape-flanging, phasing and chorus effects. It works by mixing the signal with a short, modulated delay of itself, and its controls range from gentle chorus to extreme jet-sweep flanging.", "plain_english": "MetaFlanger creates that whooshing, sweeping sound called flanging. It copies the signal, delays the copy a tiny bit, and moves that delay up and down. Mixing the two makes a sweeping effect. It can also do softer chorus and phasing sounds.", "purpose_function": "It exists to add movement and sweep to a sound, emulating classic tape-flanging, chorus and phasing effects.", "practical_application": "An engineer adds it to a guitar, synth or drum bus for a sweeping, animated texture.", "category": "Modulation Plugin", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Flanger", "Chorus", "Phaser", "MondoMod", "LFO", "Modulation"], "common_mistakes": ["Confusing flanging with phasing; they use different methods and sound different", "Setting feedback so high it becomes harsh or metallic when subtlety is wanted", "Applying a deep flange on a lead vocal where it distracts from the words"], "scenario_contexts": ["Adding a jet-sweep flange to a rhythm guitar", "Creating vintage tape-flange movement on a drum loop", "Widening a synth pad with gentle chorus"], "formula_symbolic": "", "formula_words": ""}, {"id": "849688e8-cd1c-463e-a08f-9d3143dce601", "term": "MondoMod", "definition": "MondoMod is a modulation-effect plugin from Waves Audio Ltd. that combines three linked modulators: amplitude modulation (AM), frequency modulation (FM) and rotation (auto-panning). Driven together, they create effects ranging from subtle movement to dramatic, turbulent textures.", "plain_english": "MondoMod adds motion to a sound in three ways at once. It can pulse the volume, wobble the pitch, and pan it around. These effects are linked so they move together. This makes anything from gentle shimmer to wild, swirling sounds.", "purpose_function": "It exists to add rich, combined modulation, blending tremolo-like level, vibrato-like pitch, and auto-pan movement in one tool.", "practical_application": "An engineer uses it on synths, pads or guitars to add shimmer, wobble and stereo movement.", "category": "Modulation Plugin", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Modulation", "LFO", "Tremolo", "Vibrato", "Auto-Pan", "MetaFlanger"], "common_mistakes": ["Pushing the FM (pitch) modulation too far, which sounds out of tune", "Stacking all three modulators heavily until the part becomes seasick", "Applying strong pitch modulation to a tuned lead where it clashes"], "scenario_contexts": ["Adding shimmer and movement to a synth pad", "Creating a swirling, evolving texture on a guitar", "Animating a static background part with gentle modulation"], "formula_symbolic": "", "formula_words": ""}, {"id": "7acda9ab-7cb4-44a8-afa7-282abbc6ea05", "term": "Morphoder", "definition": "Morphoder is a vocoder plugin from Waves Audio Ltd. It imposes the changing tone of one sound (the modulator, often a voice) onto a carrier sound, such as its built-in synthesizer, to create classic vocoder and talking-synth effects.", "plain_english": "Morphoder makes the classic robot-voice, or talking-synth, sound. It takes the shape of your voice and stamps it onto a synth tone. The synth then seems to speak or sing. This effect is called a vocoder.", "purpose_function": "It exists to create vocoder effects, blending the character of a voice with a musical carrier for robotic or synthetic vocal textures.", "practical_application": "A producer routes a vocal into it and uses a synth carrier to make the voice sound robotic or musical.", "category": "Vocoder Plugin", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Vocoder", "OVox", "Carrier", "Modulator", "Synthesizer"], "common_mistakes": ["Feeding a bass-heavy carrier so the words become unclear", "Forgetting the vocoder needs both a modulator and a carrier to work", "Confusing a vocoder with simple pitch shifting or Auto-Tune"], "scenario_contexts": ["Creating a robotic vocal hook in an electronic track", "Adding a talking-synth effect to a pad", "Turning a spoken phrase into a musical vocoder line"], "formula_symbolic": "", "formula_words": ""}, {"id": "e095acdb-e7ad-4145-ab73-d145db64a42d", "term": "OVox", "definition": "OVox is a vocal-resynthesis and voice-controlled synthesizer plugin from Waves Audio Ltd. It analyzes an incoming voice and uses it to drive built-in synthesizer and effect engines, producing vocoder, harmony, tuning, talkbox and synthesized-vocal sounds, and it can be controlled with MIDI notes.", "plain_english": "OVox turns your voice into a synthesizer. It listens to your singing and rebuilds it as new sounds. It can make vocoder, harmony, robot and synth-vocal effects. You can also play it with MIDI keys to set the notes.", "purpose_function": "It exists to transform a voice into synthesized and processed vocal textures, combining a vocoder, harmonizer and synth in one tool.", "practical_application": "A producer sings into it and plays MIDI chords to generate harmonies, vocoder lines or synth-vocal hooks.", "category": "Vocal Synth", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Vocoder", "Morphoder", "Synthesizer", "MIDI", "Harmonizer", "Auto-Tune"], "common_mistakes": ["Expecting a clean, natural vocal; it is designed to transform, not just tune", "Not providing MIDI or a scale, so harmonies land on wrong notes", "Confusing its tuning effect with transparent pitch correction"], "scenario_contexts": ["Building a stacked vocoder hook from a single vocal", "Generating instant vocal harmonies with MIDI chords", "Designing a robotic synth-vocal for electronic music"], "formula_symbolic": "", "formula_words": ""}, {"id": "de611db2-4f87-4814-af32-d0b00b0a93af", "term": "OneKnob Series", "definition": "The OneKnob Series is a set of eight single-knob audio processing plug-ins from Waves Audio Ltd., each dedicated to one common mixing task controlled by a single macro parameter. The set includes Brighter (high-frequency EQ), Driver (overdrive/distortion), Filter (resonant sweepable filter), Louder (limiter/loudness), Phatter (low-end enhancement), Pressure (compression), Pumper (sidechain-style ducking), and Wetter (reverb).", "plain_english": "OneKnob is a family of simple Waves plug-ins. Each one does a single job, like adding brightness, distortion, loudness, or reverb. You turn just one knob to control it. Behind that knob sits a normal effect such as an equalizer, compressor, limiter, or reverb.", "purpose_function": "It exists to give fast, low-effort results by hiding many parameters behind one control, so a user can shape a sound quickly without deep menu-diving. Each plug-in still performs a standard audio process under the hood.", "practical_application": "An engineer drops OneKnob Louder on a track to raise perceived loudness, or OneKnob Filter on a loop for a quick sweep, adjusting the single knob to taste during a mix.", "category": "Plugin Bundle", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["OneKnob Louder", "Renaissance Vox", "SuperTap", "Smack Attack", "Renaissance Bass"], "common_mistakes": ["Assuming 'one knob' means low quality; each plug-in is a full standard effect with a simplified control.", "Pushing OneKnob Louder too hard and causing audible limiting distortion.", "Treating OneKnob Pumper as a real compressor when it simulates sidechain ducking, not level-dependent compression."], "scenario_contexts": ["Quickly brightening a dull vocal with OneKnob Brighter.", "Adding parallel-style punch to a drum bus with OneKnob Pressure.", "Creating rhythmic ducking under a synth with OneKnob Pumper."], "formula_symbolic": "", "formula_words": ""}, {"id": "2c733647-fdc5-4f73-b47a-9cf24347c809", "term": "PS22 StereoMaker", "definition": "PS22 StereoMaker is a mono-to-stereo synthesis plug-in from Waves Audio Ltd. that creates a stereo image from a mono source using frequency-dependent panning built on low-Q IIR (infinite impulse response) all-pass/filter networks, distributing different frequencies to different positions across the stereo field. It can also re-image or widen existing stereo material via Spread, Rotation, Width and frequency controls.", "plain_english": "PS22 turns a mono recording into a stereo one. It spreads different pitches to different spots between the left and right speakers. This makes a single-channel sound feel wide. It uses gentle filters so it does not color the tone much.", "purpose_function": "It exists to add width and stereo interest to mono tracks or to reshape a stereo image, without simply copying and delaying the signal. Frequency-dependent spreading gives a wider, more natural image than a simple pan.", "practical_application": "An engineer uses PS22 on a mono synth, guitar, or archival recording to place it across the stereo field, adjusting Spread and checking mono compatibility to avoid phase problems.", "category": "Stereo Imaging", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["MondoMod", "SuperTap", "Brauer Motion", "Renaissance Vox"], "common_mistakes": ["Adding too much Spread, which introduces frequency-response ripple and weak mono summing.", "Assuming the widened signal stays fully mono-compatible; heavy spreading can cause partial cancellation in mono.", "Using it on already-wide stereo mixes and creating an unstable phantom center."], "scenario_contexts": ["Widening a mono synth pad in a pop mix.", "Creating a stereo image from a mono vintage recording.", "Re-balancing the width of a stereo submix before mastering."], "formula_symbolic": "", "formula_words": ""}, {"id": "d61a1be5-1517-464d-b986-42decf3143d7", "term": "Playlist Rider", "definition": "Playlist Rider is a real-time automatic level-riding plug-in from Waves Audio Ltd. designed to balance the volume of multiple audio sources, such as a host microphone, guests, music playlist and clips, automatically and non-destructively during a show. It continuously adjusts gain so different sources sit at consistent, natural levels.", "plain_english": "Playlist Rider keeps the volume of several sources even during a show. It watches hosts, guests, music, and clips as they play. Then it raises or lowers each one automatically. This keeps everything at a steady, comfortable level without the engineer constantly moving each fader by hand.", "purpose_function": "It exists to save engineers from constantly riding faders across many live sources, keeping loudness consistent for broadcast, streaming and podcasts. It works in real time and does not permanently alter the source files.", "practical_application": "A podcast or livestream engineer inserts Playlist Rider so host, guest and background music stay balanced automatically as the show moves between talking and music.", "category": "Level Automation", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Vocal Rider", "Waves IDR", "Renaissance Vox", "OneKnob Louder"], "common_mistakes": ["Expecting it to replace loudness metering for broadcast delivery specs.", "Setting an unrealistic target so quiet sources are pushed up with noise.", "Assuming it edits the recorded files; the riding is applied non-destructively in real time."], "scenario_contexts": ["Balancing host and guest mics plus music during a live podcast.", "Keeping levels even across varied clips in a livestream.", "Managing multiple sources when a system processor is not accessible."], "formula_symbolic": "", "formula_words": ""}, {"id": "6304d28f-c347-46be-bd15-5d1df0617e89", "term": "R-Bass", "definition": "R-Bass is a psychoacoustic bass enhancement plug-in from Waves Audio Ltd. that adds low-end perception by generating upper harmonics of a chosen bass frequency rather than boosting the fundamental itself. It exploits the 'missing fundamental' effect, and its two main controls are a target Frequency and an Intensity that sets the strength of the generated harmonics.", "plain_english": "R-Bass makes bass sound fuller, even on small speakers. Instead of boosting the deep note itself, it adds higher tones related to that note. Your ear fills in the missing low pitch. You pick a frequency and set how strong the effect is.", "purpose_function": "It exists to make low end audible on speakers and earbuds that cannot reproduce deep frequencies, and to add weight without overloading a system with real sub energy. Generating harmonics stresses speakers far less than large low-frequency EQ boosts.", "practical_application": "An engineer places R-Bass on a bass or kick, sets the Frequency near the instrument's fundamental, and raises Intensity until the low end translates on laptops and phones.", "category": "Bass Enhancement", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Renaissance Bass", "MaxxBass", "LoAir", "Renaissance Vox"], "common_mistakes": ["Overusing Intensity, which makes the effect obvious and harsh.", "Confusing it with LoAir; R-Bass adds upper harmonics, while LoAir generates true subharmonic content an octave down.", "Setting the target frequency far from the source's fundamental, so the added harmonics do not reinforce the intended note."], "scenario_contexts": ["Making a bassline audible on phone and laptop speakers.", "Adding perceived weight to a kick without extra sub energy.", "Reinforcing low end where big EQ boosts would overload the playback system."], "formula_symbolic": "", "formula_words": ""}, {"id": "d3fee2ec-9844-4d68-9a7a-7c31fe76f447", "term": "Renaissance Bass", "definition": "Renaissance Bass is a psychoacoustic bass enhancement plug-in from Waves Audio Ltd. built on MaxxBass technology, which reconstructs perceived low end by generating harmonics of low frequencies so the brain infers a 'missing fundamental.' Its controls include a Frequency threshold (roughly 32-256 Hz), an Intensity for harmonic amplitude, an Original Bass in/out option, and output Gain.", "plain_english": "Renaissance Bass makes low notes seem deeper and louder. It creates higher tones that stand in for the deep note. Your brain then imagines the missing low pitch. This lets bass be heard even on small or cheap speakers.", "purpose_function": "It exists to deliver strong, translatable low end on playback systems too small or inefficient to reproduce deep bass, while reducing amplifier strain compared with large low-frequency EQ boosts. It trades real sub energy for perceived depth.", "practical_application": "An engineer inserts Renaissance Bass on bass or full mixes, sets the Frequency near the low content, and adds modest Intensity so the low end survives on laptops, phones and earbuds.", "category": "Bass Enhancement", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["MaxxBass", "R-Bass", "LoAir", "Renaissance Vox", "Renaissance Maxx"], "common_mistakes": ["Using high Intensity, which draws attention to the effect; small amounts translate better.", "Assuming it produces real sub energy rather than perceived bass from harmonics.", "Setting the Frequency far above the actual bass content, so harmonics are generated in the wrong range."], "scenario_contexts": ["Ensuring a mix's bass translates on small consumer speakers.", "Adding low-end body to a thin bass recording.", "Protecting amplifiers and headroom by avoiding heavy low-frequency EQ."], "formula_symbolic": "", "formula_words": ""}, {"id": "8243f190-8c16-4068-a9db-88a75a0c90b4", "term": "Renaissance Maxx", "definition": "Renaissance Maxx is a plug-in bundle from Waves Audio Ltd. that collects the Renaissance series of mixing processors into one package. It includes Renaissance Vox, Renaissance Bass, Renaissance Compressor, Renaissance DeEsser, Renaissance Equalizer, Renaissance Reverb, Renaissance Channel and Renaissance Axx.", "plain_english": "Renaissance Maxx is a set of Waves mixing tools sold together. It bundles the Renaissance plug-ins for vocals, bass, compression, de-essing, EQ, and reverb. Each one is easy to use. Together they cover most everyday mixing jobs.", "purpose_function": "It exists to give a compact, streamlined toolkit of the core Renaissance processors, so an engineer can cover common mixing tasks with a consistent, simple design. The bundle groups related tools rather than adding a new effect.", "practical_application": "An engineer relies on the Renaissance Maxx tools across a session, for example Renaissance Vox on lead vocals, Renaissance Compressor on bass and Renaissance EQ on guitars.", "category": "Plugin Bundle", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Renaissance Vox", "Renaissance Bass", "OneKnob Series", "Scheps Omni Channel"], "common_mistakes": ["Treating it as a single plug-in rather than a bundle of separate processors.", "Assuming the exact contents never change; the included titles have varied across versions.", "Overlooking that these are streamlined tools, not full-featured versions of every processor."], "scenario_contexts": ["Equipping a new studio with a simple core mixing toolkit.", "Mixing vocals and instruments with a consistent Renaissance workflow.", "Teaching students essential processing with easy-to-use plug-ins."], "formula_symbolic": "", "formula_words": ""}, {"id": "4d8d8f15-6251-4743-9c05-b5726c0a66e5", "term": "Renaissance Vox", "definition": "Renaissance Vox is a vocal dynamics plug-in from Waves Audio Ltd. that combines compression, a downward-expander gate and an output limiter behind a simplified interface. Its main Vox/Compression fader increases gain reduction and output together, while an integrated peak limiter prevents clipping and a Gate control reduces low-level noise.", "plain_english": "Renaissance Vox is a simple vocal processor. One main fader adds compression and makes the voice louder at the same time. A built-in limiter stops clipping. A gate quietly lowers background noise between phrases.", "purpose_function": "It exists to make vocals sit forward and even with minimal setup, folding compression, gating and limiting into one easy control set. The single-fader design speeds up common vocal treatment.", "practical_application": "An engineer inserts Renaissance Vox on a lead vocal, lowers the Compression fader for a denser, louder sound, and sets the Gate to tame room noise in the gaps.", "category": "Vocal Dynamics", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Renaissance Maxx", "Scheps Omni Channel", "Vocal Rider", "OneKnob Louder", "Renaissance Bass"], "common_mistakes": ["Pulling the Compression fader too far, over-compressing and raising noise.", "Setting the Gate too high and clipping soft word endings.", "Assuming separate ratio and threshold controls exist; the design combines them in one fader."], "scenario_contexts": ["Fast, even vocal leveling during a mix.", "Controlling dynamics on a spoken-word or podcast voice.", "Adding density to a background vocal stack."], "formula_symbolic": "", "formula_words": ""}, {"id": "05db8c4d-f596-496d-ba2b-a64d53e83342", "term": "Scheps Omni Channel", "definition": "Scheps Omni Channel is a channel-strip plug-in from Waves Audio Ltd. developed with engineer Andrew Scheps, combining several processing modules in one signal chain: a Pre module (saturation, filters, low-end 'thump'), a parametric EQ, two dynamics modules (a compressor with VCA/FET/OPT modes and a gate/expander), a dual dynamic de-esser (DS2), plus an insert slot and master section. Modules can be reordered to change how they interact.", "plain_english": "Scheps Omni Channel is one plug-in that holds many tools in a row. It has saturation, filters, an equalizer, two compressors, a gate, and a de-esser. Engineer Andrew Scheps helped design it. You can move the tools around to change the sound.", "purpose_function": "It exists to provide a complete per-channel processing chain in one plug-in, reducing the need to stack many separate effects. Reorderable modules let the engineer control processing order and interaction.", "practical_application": "An engineer places Scheps Omni Channel on a vocal or bus, uses the Pre for warmth, shapes tone with the EQ, controls dynamics with the compressor and gate, and tames sibilance with the de-esser.", "category": "Channel Strip", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Scheps Parallel Particles", "Renaissance Vox", "Renaissance Maxx", "Smack Attack"], "common_mistakes": ["Ignoring module order, which strongly affects the result because processors can be rearranged.", "Overdriving the Pre saturation and adding unwanted harshness.", "Assuming the two compressor types sound the same; VCA, FET and OPT behave differently."], "scenario_contexts": ["Building a full vocal chain in a single plug-in.", "Processing a bass DI with saturation, EQ and compression together.", "Reordering modules to compress before or after EQ for different tone."], "formula_symbolic": "", "formula_words": ""}, {"id": "75a20884-c88b-40d7-8266-83f5bec54c80", "term": "Scheps Parallel Particles", "definition": "Scheps Parallel Particles is a mixing plug-in from Waves Audio Ltd. designed with engineer Andrew Scheps that shapes tone through four parallel-processing controls: Air (high-frequency openness), Bite (aggressive presence), Thick (body and weight) and Sub (low-frequency depth). Each control blends processed signal in parallel with the source.", "plain_english": "Scheps Parallel Particles adds character with four simple knobs. Air adds high sparkle, Bite adds edge, Thick adds body, and Sub adds low depth. Engineer Andrew Scheps helped design it. Each knob mixes an effect in alongside the original sound.", "purpose_function": "It exists to quickly add air, presence, body and sub-weight to a track without complex EQ or dynamics setup. Parallel blending keeps the original signal intact while adding the effect.", "practical_application": "An engineer uses Scheps Parallel Particles on vocals, drums or bass, dialing in Bite for presence and Thick for body until the source cuts through the mix.", "category": "Parallel Processing", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Scheps Omni Channel", "Smack Attack", "Renaissance Bass", "OneKnob Series"], "common_mistakes": ["Turning up all four controls at once and overwhelming the sound.", "Treating Sub as a clean tone control; it can add unwanted low-end buildup if overused.", "Assuming it is a simple EQ rather than parallel processing."], "scenario_contexts": ["Adding presence and air to a lead vocal.", "Thickening a thin drum bus.", "Reinforcing sub-weight on a bass without a dedicated enhancer."], "formula_symbolic": "", "formula_words": ""}, {"id": "27780dd5-6136-4f9a-8e9d-6b41199f22fd", "term": "Smack Attack", "definition": "Smack Attack is a transient-shaping plug-in from Waves Audio Ltd. that independently adjusts the attack and sustain portions of a sound. Separate Attack and Sustain sections each provide Sensitivity, Duration and (for attack) Shape controls (Needle, Nail, Blunt), letting the user exaggerate or soften the initial transient and the tail.", "plain_english": "Smack Attack changes the punch and tail of a sound. Transients are the quick bursts at the start of a note. You can make the hit sharper or softer. You can also make the tail longer or shorter, which is great on drums.", "purpose_function": "It exists to reshape dynamics by level of transient rather than by threshold, so an engineer can add punch or reduce it without a compressor. Independent attack and sustain control makes drums and percussion sit better in a mix.", "practical_application": "An engineer puts Smack Attack on a snare or drum bus, boosts the attack for more crack, and adjusts sustain to control room ambience.", "category": "Transient Shaping", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["Scheps Parallel Particles", "Renaissance Vox", "OneKnob Pressure", "Waves Organic ReSynthesis"], "common_mistakes": ["Over-boosting attack and causing clipping or an unnatural click.", "Confusing transient shaping with compression; it works on transients, not a threshold.", "Cutting sustain too hard and making drums sound dead."], "scenario_contexts": ["Adding crack to a snare drum.", "Reducing room tail on an overhead drum bus.", "Tightening the attack of a plucked bass."], "formula_symbolic": "", "formula_words": ""}, {"id": "e5081d3e-357d-4c00-b2c0-b2d35a2744b0", "term": "Sub Align", "definition": "Sub Align is a live-sound plug-in from Waves Audio Ltd. that helps front-of-house engineers time- and phase-align subwoofers with the main (top) speakers when the system processor is inaccessible. It provides a crossover point, polarity flip, delay adjustment and output gain to correct the phase relationship at the crossover region.", "plain_english": "Sub Align helps subs and main speakers work together. It fixes timing and phase where their sounds overlap. This matters when you cannot reach the system's own processor. You set a crossover point, delay, and polarity to line them up.", "purpose_function": "It exists to fix weak or cancelled low end caused by poor timing between subs and tops, especially in installed rigs where the main processor is locked. Correct alignment restores full, punchy bass through the crossover region.", "practical_application": "An FOH engineer inserts Sub Align on the sub or main feed, sets the crossover frequency, and adjusts delay and polarity until the low end is loudest and tightest at the listening position.", "category": "System Alignment", "difficulty": "intermediate", "achievement_id": "af40f73e-7316-43ea-a1e2-faa8c7cadbfb", "cross": [], "related_terms": ["LoAir", "Renaissance Bass", "Waves IDR", "Playlist Rider"], "common_mistakes": ["UNSAFE: Chasing bass level by pushing amplifier and sub gain past rated limits instead of fixing alignment, risking driver or amplifier damage.", "Setting the crossover frequency far from the system's real crossover, so alignment does not match the rig.", "Ignoring polarity and delay together; both may be needed to align the crossover region."], "scenario_contexts": ["Aligning subs and tops in a venue with a locked system processor.", "Tuning a small PA where subs are fed from the same output as tops.", "Fixing thin, phasey bass at the crossover point during soundcheck."], "formula_symbolic": "", "formula_words": ""}]$ap$::jsonb)),
elig AS (SELECT r FROM p
  WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id=(r->>'id')::uuid)
    AND NOT EXISTS (SELECT 1 FROM glossary g WHERE g.term=r->>'term')),
g AS (
  INSERT INTO glossary (id, term, definition, plain_english, purpose_function, practical_application,
     category, difficulty, related_terms, common_mistakes, scenario_contexts, formula_symbolic, formula_words, achievement_id)
  SELECT (r->>'id')::uuid, r->>'term', r->>'definition',
     NULLIF(r->>'plain_english',''), NULLIF(r->>'purpose_function',''), NULLIF(r->>'practical_application',''),
     NULLIF(r->>'category',''), NULLIF(r->>'difficulty',''),
     ARRAY(SELECT jsonb_array_elements_text(r->'related_terms')),
     ARRAY(SELECT jsonb_array_elements_text(r->'common_mistakes')),
     ARRAY(SELECT jsonb_array_elements_text(r->'scenario_contexts')),
     NULLIF(r->>'formula_symbolic',''), NULLIF(r->>'formula_words',''), (r->>'achievement_id')::uuid
  FROM elig ON CONFLICT (id) DO NOTHING RETURNING 1
),
tp AS (
  INSERT INTO glossary_topics (glossary_id, achievement_id, is_primary, difficulty)
  SELECT (r->>'id')::uuid, (r->>'achievement_id')::uuid, true, NULLIF(r->>'difficulty','')
  FROM elig WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id=(r->>'id')::uuid AND gt.achievement_id=(r->>'achievement_id')::uuid)
  RETURNING 1
)
INSERT INTO glossary_topics (glossary_id, achievement_id, is_primary, difficulty)
SELECT (r->>'id')::uuid, ct::uuid, false, NULLIF(r->>'difficulty','')
FROM elig, jsonb_array_elements_text(r->'cross') ct
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id=(r->>'id')::uuid AND gt.achievement_id=ct::uuid);
COMMIT;
